/**
 * TensorFlow.js(전역 tf) 백엔드를 고급 설정의 AI 처리 장치에 맞춘다.
 * tmimage, tmpose, tmsound, imageproject, icimage, faceapi 와 GUI 이미지 학습 창(ai-panel)이 모델을 불러오기 전에 호출한다.
 *
 * 전역 tf 엔진은 TM·speech-commands·knn 이 함께 쓰므로 한꺼번에 바뀐다. face-api 는 내장 엔진이 따로 있어 같이 바꾼다(getEngines).
 * 이미 불러온 모델이 있을 때 백엔드를 바꾸면 텐서 이동/오류가 생길 수 있어, 모델을 불러올 때만 적용한다.
 *  - gpu → 'webgl', cpu → 'cpu'
 *  - auto → 작은 연산을 webgl과 cpu로 각각 계산해 결과가 같으면 webgl, 다르거나 오류면 cpu.
 *           결과는 기기에 저장해 두고 브라우저(WebView) 버전이 바뀔 때만 다시 점검한다.
 */
const AiDelegateSetting = require('./ai-delegate-setting');

const {Delegate, Engine} = AiDelegateSetting;
const BACKEND = {
    [Delegate.GPU]: 'webgl',
    [Delegate.CPU]: 'cpu'
};
// webgl은 float32 정밀도 차이가 있으므로 상대 오차 1e-3 이내면 같은 결과로 본다.
const SELFTEST_TOLERANCE = 1e-3;

const getTf = () => window.tf;

// 백엔드를 맞출 tfjs 엔진 목록. 전역 tf와 같은 엔진(window._tfengine)을 쓰는 라이브러리
// (teachablemachine image/pose, speech-commands, knn-classifier)는 전역 tf 하나로 함께 바뀐다.
// face-api 0.20 은 tfjs-core 1.0.3 을 내장해 별도 엔진을 쓰므로 따로 setBackend 해야 한다.
const getEngines = () => {
    const engines = [window.tf];
    const faceTf = window.faceapi && window.faceapi.tf;
    if (faceTf && faceTf !== window.tf && typeof faceTf.setBackend === 'function') engines.push(faceTf);
    return engines;
};

// 엔진의 백엔드를 바꾼다. 바꿀 수 없으면 false.
const setEngineBackend = async (engine, backend) => {
    if (engine.getBackend() === backend) return true;
    const ok = await engine.setBackend(backend);
    if (engine.ready) await engine.ready();
    // tfjs 1.0.x 의 setBackend 는 값을 돌려주지 않는다 — 실제 백엔드로 판단한다.
    return ok !== false && engine.getBackend() === backend;
};

// conv2d + relu + matMul — 이미지 모델이 쓰는 기본 연산을 고정된 입력으로 계산한다.
const selfTestOnce = async backend => {
    const tf = getTf();
    await tf.setBackend(backend);
    await tf.ready();
    const output = tf.tidy(() => {
        const input = tf.tensor4d(Array.from({length: 32 * 32 * 3}, (_, i) => (Math.sin(i) * 0.5) + 0.5), [1, 32, 32, 3]);
        const filter = tf.tensor4d(Array.from({length: 3 * 3 * 3 * 8}, (_, i) => Math.cos(i * 0.7) * 0.2), [3, 3, 3, 8]);
        const weights = tf.tensor2d(Array.from({length: 8 * 4}, (_, i) => Math.sin(i * 1.3)), [8, 4]);
        const features = tf.conv2d(input, filter, 1, 'same').relu();
        return tf.matMul(features.reshape([32 * 32, 8]), weights).sum(0);
    });
    const values = await output.data();
    output.dispose();
    return Array.from(values);
};

const selfTestWebgl = async logTag => {
    try {
        const gpu = await selfTestOnce(BACKEND[Delegate.GPU]);
        const cpu = await selfTestOnce(BACKEND[Delegate.CPU]);
        const maxDiff = Math.max(...gpu.map((v, i) => Math.abs(v - cpu[i]) / (Math.abs(cpu[i]) + 1e-3)));
        return maxDiff <= SELFTEST_TOLERANCE ?
            {delegate: Delegate.GPU, reason: 'gpu-ok'} :
            {delegate: Delegate.CPU, reason: 'gpu-mismatch'};
    } catch (e) {
        console.error(logTag, 'TensorFlow.js GPU 점검 실패', e);
        return {delegate: Delegate.CPU, reason: 'gpu-error'};
    }
};

/**
 * @param {string} logTag 콘솔 로그 접두어
 * @return {Promise<string>} 적용한 장치 'gpu' | 'cpu'
 */
const applyTfjsBackend = async logTag => {
    const tf = getTf();
    if (!tf) return null;

    const setting = AiDelegateSetting.getSetting();
    let delegate = setting;
    let source = 'setting';
    if (setting === Delegate.AUTO) {
        const resolved = AiDelegateSetting.getResolved(Engine.TFJS);
        if (resolved) {
            delegate = resolved.delegate;
            source = 'auto-cached';
        } else {
            const result = await selfTestWebgl(logTag);
            delegate = result.delegate;
            source = 'auto';
            AiDelegateSetting.setResolved(Engine.TFJS, delegate, result.reason);
            console.error(logTag, 'TensorFlow.js 처리 장치 자동 선택', delegate, result.reason);
        }
    }

    const engines = getEngines();
    let ok = true;
    for (const engine of engines) {
        ok = (await setEngineBackend(engine, BACKEND[delegate])) && ok;
    }
    if (!ok && delegate === Delegate.GPU) {
        // webgl을 쓸 수 없는 환경이면 cpu로 내려간다.
        for (const engine of engines) await setEngineBackend(engine, BACKEND[Delegate.CPU]);
        delegate = Delegate.CPU;
        source = setting === Delegate.AUTO ? 'auto-fallback' : source;
    }
    await tf.ready();
    AiDelegateSetting.setLast(Engine.TFJS, delegate, source);
    console.error(logTag, 'TensorFlow.js 백엔드', engines.map(engine => engine.getBackend()).join(','), `setting=${setting}`);
    return delegate;
};

module.exports = applyTfjsBackend;
