    bytesToFloat(bytes) {
        const buffer = new ArrayBuffer(4);
        const view = new DataView(buffer);
        bytes.forEach((byte, index) => {
            view.setUint8(index, byte);
        });
        const floatVal = view.getFloat32(0, true); // true: little endian, false: big endian
        return floatVal;
    }

