    clearIntervalTimeID(name) {
        switch (name) {
            case INTERVAL_TIME_ID:
                if (this._interval.lineTraceTimeID) {
                    window.clearTimeout(this._interval.lineTraceTimeID);
                    this._interval.lineTraceTimeID = null;
                }
                break;
            case LINETRACE_TIME_ID:
                if (this._interval.lineTraceTimeID) {
                    window.clearTimeout(this._interval.lineTraceTimeID);
                    this._interval.lineTraceTimeID = null;
                }
                break;
            case INTERVAL_STOPALL:
                if (this._interval.lineTraceTimeID) {
                    window.clearTimeout(this._interval.lineTraceTimeID);
                    this._interval.lineTraceTimeID = null;
                }
                break;
        }
    }

    disconnect(address) {
        console.error("🦊 CoCoBoard disconnect: address :", address);

        this._connectState = 0;
        if (this._timeoutID) {
            window.clearTimeout(this._timeoutID);
            this._timeoutID = null;
        }
        // if (this._connectDevice.id === address) {
        //     if (this._parent._ble) {
        //         this._parent._ble.disconnect(address);
        //     }
        // }

        console.info(
            "🦊 this._connectDevice.peripheralId === address ->",
            this._connectDevice.peripheralId === address
        );
        if (this._connectDevice.peripheralId === address) {
            if (this._parent._ble) {
                console.info("🦊 this._parent ->", this._parent);
                console.info("🦊this._parent._ble ->", this._parent._ble);

                // this._parent._ble는 bleLink
                this._parent._ble.disconnect(address);
            }
        }
    }

