    short2array(value) {
        const tempBytes = {};
        for (let i = 0; i < 2; i++) {
            const temp = value & 0xff;
            tempBytes[i] = temp;
            value = (value - temp) / 256;
        }
        return [tempBytes[0], tempBytes[1]];
    }

