    touch_initialize(args, util) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return new Promise((resolve) => {
                resolve(false);
            });
        } else {
            bitblock.touch_initialize();
            bitblock._ack.isReadyBBTrace = true;

            return new Promise((resolve) => {
                bitblock.clearIntervalTimeID(LINETRACE_TIME_ID);
                // setTimeout( fnc, milliseconds)
                bitblock._interval.lineTraceTimeID = window.setTimeout(
                    function _touch_initialize() {
                        bitblock.clearIntervalTimeID(LINETRACE_TIME_ID);
                        if (bitblock == null || bitblock === undefined) {
                            resolve(false);
                        } else {
                            if (bitblock._ack.isArriveBBTrace === true) {
                                bitblock._ack.isArriveBBTrace = false;
                                bitblock._ack.isReadyBBTrace = false;
                                resolve(true);
                            } else {
                                bitblock._interval.lineTraceTimeID =
                                    window.setTimeout(
                                        _touch_initialize,
                                        RESPONSE_INTERVAL
                                    );
                            }
                        }
                    },
                    RESPONSE_INTERVAL
                );
            });
        }
    }

