import classNames from "classnames";
import bindAll from "lodash.bindall";
import PropTypes from "prop-types";
import React, { useState, useEffect } from "react";
import { defineMessages, FormattedMessage, injectIntl, intlShape } from "react-intl";

import Box from "../box/box.jsx";

import Paper from "@material-ui/core/Paper";
import { makeStyles } from "@material-ui/core/styles";
import TableContainer from "@material-ui/core/TableContainer";
import InputLabel from "@material-ui/core/InputLabel";
import MenuItem from "@material-ui/core/MenuItem";
import FormControl from "@material-ui/core/FormControl";
import Select from "@material-ui/core/Select";

import FormControlLabel from "@material-ui/core/FormControlLabel";
import Checkbox from "@material-ui/core/Checkbox";

import { Line } from "react-chartjs-2";
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Title,
    Tooltip,
    Legend,
} from "chart.js";

ChartJS.register(
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    // Title,
    Tooltip,
    Legend
);

import styles from "./linechart-compo.css";

const useStyles = makeStyles((theme) => ({
    chart: {
        width: "80%",
        marginTop: "0",
        // backgroundColor: 'red'
    },
    formControl: {
        margin: theme.spacing(2),
        minWidth: 200,
    },
    selectEmpty: {
        marginTop: theme.spacing(2),
    },
}));

const BORDER_COLOSRS = [
    "rgb(146, 43, 33)",
    "rgb(118, 68, 138)",
    "rgb(40, 116, 166)",
    "rgb(20, 143, 119)",
    "rgb(212, 172, 13)",
    "rgb(244, 208, 63)",
];
const BACKGROUND_COLORS = [
    "rgb(146, 43, 33)",
    "rgb(118, 68, 13)",
    "rgb(40, 116, 166)",
    "rgb(20, 143, 119)",
    "rgb(212, 172, 13)",
    "rgb(244, 208, 63)",
];

const chartOptions = {
    responsive: true,
    // aspectRatio: 1,
    plugins: {
        legend: {
            position: "top",
        },
        title: {
            display: false,
            // text: "Chart.js Line Chart",
            text: "Data Classification",
        },
    },
};

const emptyData = {
    labels: [],
    datasets: [],
};

// {
//     label:"Step By Pedro",
//     data:[3000, 5000,4500, 6000, 8000, 7000, 9000],
//     borderColor: 'rgb(255, 99, 132)', //그래프 선 color
//     backgroundColor: 'rgba(255, 99, 132, 0.5)', //마우스 호버시 나타나는 분류네모 표시 bg
// }

function LineChart(props) {
    const classes = useStyles();
    const [rows, setRows] = useState(props.data);
    const [headers, setHeaders] = useState(props.headers);
    const [xaxis, setXaxis] = React.useState("");
    const [yaxis, setYaxis] = React.useState("");
    const [chartData, setChartData] = React.useState(emptyData);
    const [sorted, setSorted] = React.useState(true);

    useEffect(() => {
        if (xaxis == "" || yaxis == "") {
            // console.error("@@@ 축이 설정되지 않았슴...");
            return;
        }

        // 객체 DEEP COPY
        let sortedData = [...rows];
        if (sorted) {
            sortedData = sortedData.sort((a, b) => {
                if (isNaN(a[xaxis]) || isNaN(b[xaxis])) {
                    if (a[xaxis] < b[xaxis]) {
                        return -1;
                    }
                } else {
                    if (Number(a[xaxis]) < Number(b[xaxis])) {
                        return -1;
                    }
                }
            });
        }

        const lebels = sortedData.map((item) => item[xaxis]);
        const data = sortedData.map((item) => item[yaxis]);

        const c = _.random(0, BORDER_COLOSRS.length);
        const objectData = {
            labels: lebels,
            datasets: [
                {
                    label: yaxis,
                    data: data,
                    borderColor: BORDER_COLOSRS[c],
                    backgroundColor: BACKGROUND_COLORS[c],
                    pointRadius: 5,
                },
            ],
        };
        setChartData(objectData);
    }, [xaxis, yaxis, sorted]);

    const handleXAxisChange = (event) => {
        setXaxis(event.target.value);
    };

    const handleYAxisChange = (event) => {
        setYaxis(event.target.value);
    };

    const handleCheckChange = (event) => {
        setSorted(!sorted);
    };

    // console.error("CHART-COMPO props :", props);
    // console.error("CHART-COMPO headers :", headers);
    // console.error("CHART-COMPO rows :", rows);

    return (
        <>
            <TableContainer component={Paper} className={classes.chart}>
                <Line options={chartOptions} data={chartData} />

                <Box className={styles.selectContainer}>
                    <FormControl
                        variant="outlined"
                        size="small"
                        className={classes.formControl}
                    >
                        <InputLabel id="xaxis-select-outlined-label">
                            <FormattedMessage defaultMessage="X axis" description="Chart axis selector label" id="gui.dataTable.chart.xAxis" />
                        </InputLabel>
                        <Select
                            labelId="xaxis-select-outlined-label"
                            id="xaxis-select-outlined"
                            value={xaxis}
                            onChange={handleXAxisChange}
                            label="x_axis"
                        >
                            <MenuItem value="">
                                <em>None</em>
                            </MenuItem>
                            {headers.map((header, index) => (
                                <MenuItem key={index} value={header.value}>
                                    {header.value}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <FormControl
                        variant="outlined"
                        size="small"
                        className={classes.formControl}
                    >
                        <InputLabel id="yaxis-select-outlined-label">
                            <FormattedMessage defaultMessage="Y axis" description="Chart axis selector label" id="gui.dataTable.chart.yAxis" />
                        </InputLabel>
                        <Select
                            labelId="yaxis-select-outlined-label"
                            id="yaxis-select-outlined"
                            value={yaxis}
                            onChange={handleYAxisChange}
                            label="y_axis"
                        >
                            <MenuItem value="">
                                <em>None</em>
                            </MenuItem>
                            {headers.map((header, index) => (
                                <MenuItem key={index} value={header.value}>
                                    {header.value}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    {/* 여백 */}
                    <Box className={styles.fr}></Box>
                    {/* checkbox */}
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={sorted}
                                onChange={handleCheckChange}
                                name="sortCheck"
                                color="primary"
                            />
                        }
                        label={<FormattedMessage defaultMessage="Sort by X axis" description="Checkbox to sort chart by X axis" id="gui.dataTable.chart.sortXAxis" />}
                    />
                </Box>
            </TableContainer>
        </>
    );
}

export default LineChart;
