const JSONRPC = require('./jsonrpc');
const log = require('../util/log');

class JSONRPCWebSocket extends JSONRPC {
    constructor (webSocket) {
        super();

        this._ws = webSocket;
        this._ws.onmessage = e => this._onSocketMessage(e);
        this._ws.onopen = e => this._onSocketOpen(e);
        this._ws.onclose = e => this._onSocketClose(e);
        this._ws.onerror = e => this._onSocketError(e);
    }

    dispose () {
        this._ws.close();
        this._ws = null;
    }

    _onSocketOpen () {
        log.info(`_onSocketOpen`);
    }

    _onSocketClose () {
    }

    _onSocketError () {
    }

    /**
     * Receive messages from the device (kamibot)
     * @param {object} event messages from the device
     */
    _onSocketMessage (event) {
        const json = JSON.parse(event.data);
        this._handleMessage(json);
    }

    /**
     * Sending a message to a device (kamibot)
     * @param {object} message messages to the device
     */
    _sendMessage (message) {
        const messageText = JSON.stringify(message);
        this._ws.send(messageText);
    }
}

module.exports = JSONRPCWebSocket;
