const commandType = {
    DIGITAL_WRITE: 0x01,
    DIGITAL_READ: 0x02,
    ANALOG_WRITE: 0x03,
    ANALOG_READ: 0x04,
    SET_SERVO: 0x05,
    SET_TONE: 0x06,
    GET_ULTRASONIC: 0x07,
    TURN_LED: 0x08,
    BOARD_RESET: 0xaa
};

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

const LOGTAG = '{bitboard} ';

class BitBoard {
    constructor(runtime, extensionId) {
        this._runtime = runtime;
        this._extensionId = extensionId;

        this._serial = null;
        this._sensorData = null;
        this._runtime.registerPeripheralExtension(extensionId, this);

        this.disconnect = this.disconnect.bind(this);
        this._onConnect = this._onConnect.bind(this);
        this._onMessage = this._onMessage.bind(this);
        this._pollValues = this._pollValues.bind(this);
    }

    /**
     * 스크래치 빨간 정지 버튼을 누를때 호출
     */
    async stopAll() {
        // Do nothing
    }

    /**
     * 녹색 깃발을 누를 때 호출
     */
    reset() {
        // DO nothing
    }

    scan() {

        if (this._serial) {
            this._serial.disconnect();
        }

        this._serial = new SERIAL(
            this._runtime,
            this._extensionId,
            {
                extensionId: this._extensionId,
                majorDeviceClass: 8,
                minorDeviceClass: 1
            },
            this._onConnect,
            this.disconnect,
            this._onMessage
        );
    }

    connect(id) {
        if (this._serial) {
            this._serial.connectPeripheral(id, this._extensionId);
        }
    }

    disconnect() {
        if (this._serial) {
            this._serial.disconnect(this._extensionId);
        }
    }

    /**
     * Called by the runtime to detect whether the EV3 peripheral is connected.
     * @return {boolean} - the connected state.
     */
    isConnected() {
        let connected = false;
        if (this._serial) {
            connected = this._serial.isConnected();
        }
        return connected;
    }

    /**
     * Send a message to the peripheral socket.
     * @param {object} message - the message to send.
     * @return {Promise} - a promise result of the send operation.
     */
    send(message) {
        if (!this.isConnected()) {
            return Promise.resolve();
        }

        console.info(LOGTAG, '!!! this._serial.getCountOfRequest() !!! ', this._serial.getCountOfRequest());
        if (this._serial.getCountOfRequest() > 0) {
            console.info(LOGTAG, '!!! If more than one countOfRequir, {ignore command} !!!');
            return Promise.resolve();
        }

        const msg = {
            message: message,
            encoding: 'plain'
        };
        
        this._serial.sendMessage(msg);

        return new Promise((resolve, reject) => {
            const id = setInterval(() => {
                console.info(`{bitblock} Bitblock::setInterval => request ::: ${this._serial.getCountOfRequest()}`);
                if (this._serial.getCountOfRequest() === 0) {
                    clearInterval(id);
                    console.info(`{bitblock} send counter promise resolved`);
                    resolve(true);
                }
            }, 10);
        });
    }

    async digitalWrite(pin, value) {
        const msg = {
            extensionId: this._extensionId,
            command: commandType.DIGITAL_WRITE,
            args: {
                param1: pin,
                param2: value
            }
        };
        await this.send(msg);
    }

    async digitalRead(pin) {
        const msg = {
            extensionId: this._extensionId,
            command: commandType.DIGITAL_READ,
            args: {
                param1: pin
            }
        };
        await this.send(msg);
        const ret = this._sensorData ? this._sensorData.retValue : 0;
        return ret;
    }

    async analogWrite(pin, value) {
        const msg = {
            extensionId: this._extensionId,
            command: commandType.ANALOG_WRITE,
            args: {
                param1: pin,
                param2: value
            }
        };
        await this.send(msg);
    }

    async analogRead(pin) {
        const msg = {
            extensionId: this._extensionId,
            command: commandType.ANALOG_READ,
            args: {
                param1: pin
            }
        };
        await this.send(msg);
        const ret = this._sensorData ? this._sensorData.retValue : 0;
        return ret;
    }

    async tone(pin, hz, sec) {
        const msg = {
            extensionId: this._extensionId,
            command: commandType.SET_TONE,
            args: {
                param1: pin,
                param2: hz,
                param3: sec
            }
        };
        await this.send(msg);
    }

    async setServo(pin, angle) {
        const msg = {
            extensionId: this._extensionId,
            command: commandType.SET_SERVO,
            args: {
                param1: pin,
                param2: angle
            }
        };
        await this.send(msg);
    }

    async getUltrasonic(trig, echo) {
        const msg = {
            extensionId: this._extensionId,
            command: commandType.GET_ULTRASONIC,
            args: {
                param1: trig,
                param2: echo
            }
        };
        await this.send(msg);
        const ret = this._sensorData ? this._sensorData.retValue : 0;
        return ret;
    }

    async stopBitblock() {
        const msg = {
            extensionId: this._extensionId,
            command: commandType.BOARD_RESET,
            args: {}
        };
        await this.send(msg);
    }

    /**
     * When the bitblock peripheral connects, start polling for sensor and motor values.
     * @private
     */
    _onConnect() {
        // this._pollingIntervalID = window.setInterval(this._pollValues, this._pollingInterval);
        console.info(LOGTAG, `_onConnect()`);
    }


    /**
     * 일정 시간 단위로 계속 불려진다.
     * _onConnect 함수에서 150ms 단위로 불려진다.
     * @deprecated
     * @private
     */
    _pollValues() {
        // Do nothing
    }


    /**
     * Message handler for incoming bitblock reply messages, either a list of connected
     * devices (sensors and motors) or the values of the connected sensors and motors.
     * @param {object} params - incoming message parameters
     * @private
     * 카미봇에서 전달되는 메세지를 다룬다.
     */
    _onMessage(params) {

        // {"action":"get","idx":3,"device":1,"value":0,"pin":2,"data":0}
        this._sensorData = params.message;

        // console.info(`{bitblock} bitblock::_onMessage params: ${JSON.stringify(params)}`);
        console.info(`{bitblock} bitblock::_onMessage this._sensorData: ${JSON.stringify(this._sensorData)}`);
    }

    _sleep(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

} /* end of Bitblock */

