const checkPermission = async () => {
    console.log("{scratch3_camera, checkPermission}");
    console.log("{scratch3_camera, navigator} :", navigator);
    console.log(
        "{scratch3_camera, navigator} permissions :",
        navigator.permissions
    );
    console.log("{scratch3_camera, navigator} platform:", navigator.platform);

    await navigator.permissions
        .query({ name: "camera" })
        .then(async (permission) => {
            // console.log('camera state', permission.state);
            if (permission.state !== "granted") {
                await navigator.mediaDevices.getUserMedia({
                    audio: false,
                    video: true,
                });
            }
        })
        .catch(async (error) => {
            console.error(
                "{Scratch_camera}-{checkPermission} Got error :",
                error
            );
        });
};

