/**
 * Class for the motion-related blocks in Scratch 3.0
 * @param {Runtime} runtime - the runtime instantiating this block package.
 * @constructor
 */
class Scratch3CameraBlocks {
    constructor(runtime) {
        this.locale = this._setLocale();
        /**
         * The runtime instantiating this block package.
         * @type {Runtime}
         */
        this.runtime = runtime;
        this.firstInstall = true;

        this.cameraList = [];

        this.initialize();

        if (this.runtime.ioDevices) {
            this.runtime.on(
                Runtime.PROJECT_LOADED,
                this.updateVideoDisplay.bind(this)
            );
            this.runtime.on(Runtime.PROJECT_RUN_START, this.reset.bind(this));
        }

        // this.runtime.on("targetWasRemoved", (target) => {
        //     console.error('CAMERA @@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@');
        // });
    }

    get EXTENSION_ID() {
        return "camera";
    }

    /**
     * Dimensions the video stream is analyzed at after its rendered to the
     * sample canvas.
     * @type {Array.<number>}
     */
    static get DIMENSIONS() {
        return [480, 360];
    }

    /**
     * The key to load & store a target's motion-related state.
     * @type {string}
     */
    static get STATE_KEY() {
        return "Scratch.videoSensing";
    }

    /**
     * The default motion-related state, to be used when a target has no existing motion state.
     * @type {MotionState}
     */
    static get DEFAULT_MOTION_STATE() {
        return {
            motionFrameNumber: 0,
            motionAmount: 0,
            motionDirection: 0,
        };
    }

    /**
     * The transparency setting of the video preview stored in a value
     * accessible by any object connected to the virtual machine.
     * @type {number}
     */
    get globalVideoTransparency() {
        const stage = this.runtime.getTargetForStage();
        if (stage) {
            return stage.videoTransparency;
        }
        return 0;
    }

    set globalVideoTransparency(transparency) {
        const stage = this.runtime.getTargetForStage();
        if (stage) {
            stage.videoTransparency = transparency;
        }
        return transparency;
    }

    /**
     * The video state of the video preview stored in a value accessible by any
     * object connected to the virtual machine.
     * @type {number}
     */
    get globalVideoState() {
        const stage = this.runtime.getTargetForStage();
        if (stage) {
            return stage.videoState;
        }
        // Though the default value for the stage is normally 'on', we need to default
        // to 'off' here to prevent the video device from briefly activating
        // while waiting for stage targets to be installed that say it should be off
        return VIDEOSTATE.OFF;
    }

    set globalVideoState(state) {
        const stage = this.runtime.getTargetForStage();
        if (stage) {
            stage.videoState = state;
        }
        return state;
    }

    /**
     * Get the latest values for video transparency and state,
     * and set the video device to use them.
     */
    updateVideoDisplay() {
        this.setVideoTransparency({
            TRANSPARENCY: this.globalVideoTransparency,
        });
        this.videoToggle({
            VIDEO_STATE: this.globalVideoState,
        });
    }

    /**
     * Reset the extension's data motion detection data. This will clear out
     * for example old frames, so the first analyzed frame will not be compared
     * against a frame from before reset was called.
     */
    reset() {
        const targets = this.runtime.targets;
        for (let i = 0; i < targets.length; i++) {
            const state = targets[i].getCustomState(
                Scratch3CameraBlocks.STATE_KEY
            );
            if (state) {
                // state.motionAmount = 0;
                // state.motionDirection = 0;
            }
        }
    }

    requestVideoStream_2 = async () => {
        // 20240415 아래 부분은 안드로이드에서 에러가 나고,일단 없어도 실행은 되는것 같으니..
        // await checkPermission();

        if (this.runtime.isMobile.Android() || this.runtime.isMobile.iOS()) {
            // let constraints = {
            //     // video: { facingMode: "environment" },
            //     video: { facingMode: "environment" },
            // };
            // let medias = await navigator.mediaDevices.getUserMedia(constraints);
            // console.log("### medias : ", medias);

            const videoInputList = [
                new Array("전면 카메라", "face-camera", "frontCamera"), // @hangul-ok value stored in projects; [2] = Message key for display
                new Array("후면 카메라", "enviroment-camera", "rearCamera"), // @hangul-ok value stored in projects; [2] = Message key for display
            ];
            console.log("### videoInputList : ", videoInputList);
            return videoInputList;
        } else {
            const inputList = await getInputList();
            // console.log("@@@ inputList : ", inputList);

            const videoInputList = inputList
                .filter((input) => input.kind === "videoinput")
                .map((item) => [item.label, item.deviceId]);

            // console.log("### videoInputList : ", videoInputList);
            return videoInputList;
        }
    };

    async initialize() {
        this.cameraList = await this.requestVideoStream_2();
        // console.log("@@@ {scratch_camera} this.cameraList", this.cameraList);

        // const camerMenu = this.cameraList.map((entry, index) => {
        //     console.log('entry', entry)
        //     const obj = {};
        //     obj.text = entry[0];
        //     obj.value = String(index);
        //     return obj;
        // });
    }

    /**
     * Create data for a menu in scratch-blocks format, consisting of an array
     * of objects with text and value properties. The text is a translated
     * string, and the value is one-indexed.
     * @param {object[]} info - An array of info objects each having a name
     *   property.
     * @return {array} - An array of objects with text and value properties.
     * @private
     */
    _buildMenu(info) {
        return info.map((entry, index) => {
            const obj = {};
            obj.text = entry.name;
            obj.value = entry.value || String(index + 1);
            return obj;
        });
    }

    /**
     * States the video sensing activity can be set to.
     * @readonly
     * @enum {string}
     */
    static get VideoState() {
        return VIDEOSTATE;
    }

    /**
     * An array of info on video state options for the "turn video [STATE]" block.
     * @type {object[]}
     * @param {string} name - the translatable name to display in the video state menu
     * @param {string} value - the serializable value stored in the block
     */
    get VIDEO_STATE_INFO() {
        return [
            {
                name: formatMessage({
                    id: "videoSensing.off",
                    default: "off",
                    description: 'Option for the "turn video [STATE]" block',
                }),
                value: VIDEOSTATE.OFF,
            },
            {
                name: formatMessage({
                    id: "videoSensing.on",
                    default: "on",
                    description: 'Option for the "turn video [STATE]" block',
                }),
                value: VIDEOSTATE.ON,
            },
        ];
    }

    /**
     * @returns {object} metadata for this extension and its blocks.
     */
    _setLocale() {
        const locale = formatMessage.setup().locale;
        return AvailableLocales.includes(locale) ? locale : "en";
    }

    getInfo() {
        this.locale = this._setLocale();
        if (this.firstInstall) {
            this.globalVideoState = VIDEOSTATE.ON;
            this.globalVideoTransparency = 0;
            this.updateVideoDisplay();
            this.firstInstall = false;
        }

        const BLOCKS = {
            id: "camera",
            name: Message.extName[this.locale],
            blockIconURI: blockIconURI,
            menuIconURI: menuIconURI,
            blocks: [
                {
                    opcode: "videoToggle",
                    text: formatMessage({
                        id: "camera.videoToggle",
                        default: "turn camera [VIDEO_STATE]",
                        description:
                            "Controls display of the camera preview layer",
                    }),
                    arguments: {
                        VIDEO_STATE: {
                            type: ArgumentType.NUMBER,
                            menu: "VIDEO_STATE",
                            defaultValue: VIDEOSTATE.ON,
                        },
                    },
                },
                {
                    opcode: "mirrorDisplay",
                    text: Message.mirror[this.locale],
                    arguments: {
                        MIRROR_STATE: {
                            type: ArgumentType.NUMBER,
                            menu: "VIDEO_STATE",
                            defaultValue: VIDEOSTATE.OFF,
                        },
                    },
                },
                // 안드로이드에서도 되는가?
                {
                    opcode: "selectCamera",
                    blockType: BlockType.COMMAND,
                    text: Message.selectCamera[this.locale],
                    arguments: {
                        CAMERA_LIST: {
                            type: ArgumentType.STRING,
                            menu: "camera_list_menu",
                            defaultValue: "카메라", // @hangul-ok sentinel menu value (see selectCamera)
                        },
                    },
                },
                {
                    opcode: "setVideoTransparency",
                    text: formatMessage({
                        id: "camera.setVideoTransparency",
                        default: "set camera transparency to [TRANSPARENCY]",
                        description:
                            "Controls transparency of the camera preview layer",
                    }),
                    arguments: {
                        TRANSPARENCY: {
                            type: ArgumentType.NUMBER,
                            defaultValue: 50,
                        },
                    },
                },
                // 테스트
                // {
                //     opcode: "startVibrate",
                //     blockType: BlockType.COMMAND,
                //     text: "진동하기",
                // },
            ],
            menus: {
                VIDEO_STATE: {
                    acceptReporters: true,
                    items: this._buildMenu(this.VIDEO_STATE_INFO),
                },
                camera_list_menu: {
                    acceptReporters: false,
                    items: "getCameraList",
                },
            },
        };

        // if (this.runtime.isMobile.Windows()) {
        //     const CAMERA_BLOCK = {
        //         opcode: "selectCamera",
        //         blockType: BlockType.COMMAND,
        //         text: "[CAMERA_LIST] 변경하기",
        //         arguments: {
        //             CAMERA_LIST: {
        //                 type: ArgumentType.STRING,
        //                 menu: "camera_list_menu",
        //                 defaultValue: "카메라",
        //             },
        //         },
        //     };
        //     BLOCKS["blocks"].push(CAMERA_BLOCK);
        //     // console.error('%%% BLOCKS : ', BLOCKS['blocks']);
        // }

        // Return extension definition
        return BLOCKS;
    }

    startVibrate() {
        console.error("******* WWW **********");
        console.error("---- navigator ----");
        console.error(navigator);
    }

    /**
     * Return menu for video showing state.
     * @return {Array} - Menu items.
     */
    getCameraList() {
        const items = [{ text: Message.cameraItem[this.locale], value: "카메라" }]; // @hangul-ok sentinel value kept

        if (this.cameraList.length > 0) {
            for (let index = 0; index < this.cameraList.length; index++) {
                const entry = this.cameraList[index];
                const msgKey = entry[2];
                // value 는 저장된 프로젝트와 selectCamera 비교를 위해 그대로 두고, 표시만 번역한다.
                items.push({ text: msgKey && Message[msgKey] ? Message[msgKey][this.locale] : entry[0], value: entry[0] });
            }
        }
        return items;
    }

    /**
     * A scratch command block handle that configures the video state from
     * passed arguments.
     * @param {object} args - the block arguments
     * @param {VideoState} args.VIDEO_STATE - the video state to set the device to
     */
    videoToggle(args) {
        const state = args.VIDEO_STATE;

        this.globalVideoState = state;
        if (state === VIDEOSTATE.OFF) {
            this.runtime.ioDevices.video.disableVideo();
        } else {
            this.runtime.ioDevices.video.mirror = true;
            console.log('########## 카메라 활성화, 미러표시:', this.runtime.ioDevices.video.mirror);

            this.runtime.ioDevices.video.enableVideo();
            // Mirror if state is ON. Do not mirror if state is ON_FLIPPED.
            // this.runtime.ioDevices.video.mirror = state === VIDEOSTATE.ON;
        }
    }

    mirrorDisplay(args) {
        const state = args.MIRROR_STATE;

        this.runtime.ioDevices.video.disableVideo();
        if (state === VIDEOSTATE.OFF) {
            // 거울모드 끄기 
            this.runtime.ioDevices.video.mirror = false;
        } else {
            // 거울모드 켜기
            this.runtime.ioDevices.video.mirror = true;
        }
        this.runtime.ioDevices.video.enableVideo();
    }

    /**
     * A scratch command block handle that configures the video preview's
     * transparency from passed arguments.
     * @param {object} args - the block arguments
     * @param {number} args.TRANSPARENCY - the transparency to set the video
     *   preview to
     */
    setVideoTransparency(args) {
        const transparency = Cast.toNumber(args.TRANSPARENCY);
        this.globalVideoTransparency = transparency;
        this.runtime.ioDevices.video.setPreviewGhost(transparency);
    }

    sleep(ms) {
        const wakeUpTime = Date.now() + ms;
        while (Date.now() < wakeUpTime) {}
    }

    selectCamera(args) {
        console.log("Selected Camera->", args.CAMERA_LIST);

        if (args.CAMERA_LIST == "카메라") { // @hangul-ok sentinel value
            return;
        }

        // 카메라를 끄고 카메라를 바꾼다.
        this.videoToggle({ VIDEO_STATE: VIDEOSTATE.OFF });
        this.sleep(500);

        if (this.cameraList.length == 0) {
            this.runtime.ioDevices.video.selectCamera(0);
        }

        for (let i = 0; i < this.cameraList.length; i++) {
            if (this.cameraList[i][0] == args.CAMERA_LIST) {
                this.runtime.ioDevices.video.selectCamera(i);
                break;
            }
        }

        this.sleep(1000);

        this.videoToggle({
            VIDEO_STATE: "on",
        });

        // // 비디오 체인지 알림 발생...
        // this.runtime.emitVideoChanged();
    }
}

module.exports = Scratch3CameraBlocks;
