/**
 * Shared locale helpers for the custom extensions' Message tables.
 *
 * Each Message entry looks like {ko: "...", en: "...", ja: "...", ...}. Not every entry has
 * every language, so withFallback() makes a missing language fall back to English (then Korean)
 * instead of returning undefined, which would show an empty block label.
 */

// Languages offered in the editor's language menu (scratch-l10n/src/supported-locales.js).
const LOCALES = ["ko", "en", "ja", "ja-Hira", "zh-cn", "zh-tw", "es", "fr", "ru", "id", "ms", "th", "vi"];

const entryHandler = {
    get(target, key) {
        if (typeof key === "string" && !(key in target) && LOCALES.includes(key)) {
            return target.en !== undefined ? target.en : target.ko;
        }
        return target[key];
    }
};

const isEntry = value =>
    value && typeof value === "object" && !Array.isArray(value) && ("en" in value || "ko" in value);

/**
 * Wrap each entry of a Message table so missing languages fall back to English.
 * @param {object} table Message table keyed by message id.
 * @returns {object} the same table, with each entry wrapped.
 */
const withFallback = table => {
    for (const key of Object.keys(table)) {
        if (isEntry(table[key])) table[key] = new Proxy(table[key], entryHandler);
    }
    return table;
};

module.exports = {LOCALES, withFallback};
