/**
 * Get the settings strings for a locale, with English for any missing key.
 * @param {string} locale the editor locale (intl.locale)
 * @returns {object} strings keyed by message name
 */
const getSettingsMessages = locale => Object.assign({}, MESSAGES.en, MESSAGES[locale] || {});

/**
 * Fill {name} in a template string.
 * @param {string} template string containing {name}
 * @param {string} name value for {name}
 * @returns {string} filled string
 */
const withName = (template, name) => template.replace('{name}', name);

export {getSettingsMessages, withName};
