import {defineMessages, FormattedMessage, injectIntl, intlShape} from 'react-intl';
import PropTypes from 'prop-types';
import React from 'react';

import Box from '../box/box.jsx';
import Modal from '../../containers/modal.jsx';

import styles from './disconnect-confirm-modal.css';

const messages = defineMessages({
    title: {
        id: 'gui.disconnectConfirmModal.title',
        defaultMessage: 'Disconnect',
        description: 'Title of the disconnect confirmation modal'
    }
});

const DisconnectConfirmModalComponent = props => (
    <Modal
        className={styles.modalContent}
        contentLabel={props.intl.formatMessage(messages.title)}
        shouldCloseOnOverlayClick={false}
        onRequestClose={props.onCancel}
    >
        <Box className={styles.body}>
            <Box className={styles.message}>
                <FormattedMessage
                    defaultMessage="Are you sure you want to disconnect?"
                    description="Confirmation message asking whether to disconnect the hardware"
                    id="gui.disconnectConfirmModal.message"
                />
            </Box>
            <Box className={styles.buttonRow}>
                <button
                    className={styles.cancelButton}
                    onClick={props.onCancel}
                >
                    <FormattedMessage
                        defaultMessage="Cancel"
                        description="Button in disconnect confirmation modal to cancel"
                        id="gui.disconnectConfirmModal.cancel"
                    />
                </button>
                <button
                    className={styles.okButton}
                    onClick={props.onConfirm}
                >
                    <FormattedMessage
                        defaultMessage="OK"
                        description="Button in disconnect confirmation modal to confirm disconnect"
                        id="gui.disconnectConfirmModal.confirm"
                    />
                </button>
            </Box>
        </Box>
    </Modal>
);

DisconnectConfirmModalComponent.propTypes = {
    intl: intlShape.isRequired,
    onCancel: PropTypes.func.isRequired,
    onConfirm: PropTypes.func.isRequired
};

export default injectIntl(DisconnectConfirmModalComponent);
