import classNames from 'classnames';
import bindAll from 'lodash.bindall';
import PropTypes from 'prop-types';
import React, { useState, useEffect } from 'react';
import {defineMessages, injectIntl, intlShape} from 'react-intl';

import Box from '../box/box.jsx';
import styles from './table-compo.css';

// *** material ui 3 ***
import { makeStyles } from '@material-ui/core/styles';
import { withStyles } from "@material-ui/core/styles";
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableContainer from '@material-ui/core/TableContainer';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import TablePagination from '@material-ui/core/TablePagination';
import Paper from '@material-ui/core/Paper';

const ROWS_PER_PAGE = 12;
const useStyles = makeStyles({
    table: {
        width: '80%',
        // backgroundColor: 'red'
    },
});

const StyledTableCell = withStyles((theme) => ({
    head: {
      backgroundColor: "#2ecc71",
      color: "#ffffff",
      fontSize: 17,
    },
    body: {
      fontSize: 16,
    },
  }))(TableCell);

  const StyledTableRow = withStyles((theme) => ({
    root: {
      '&:nth-of-type(odd)': {
        backgroundColor: theme.palette.action.hover,
      },
    },
  }))(TableRow);

function TableCompo(props) {
    const classes = useStyles();
    const [order, setOrder] = React.useState('asc');
    // const [orderBy, setOrderBy] = React.useState('calories');
    const [rows, setRows] = useState(props.data);
    const [headers, setHeaders] = useState(props.headers);
    const [rowsPerPage, setRowsPerPage] = React.useState(ROWS_PER_PAGE);
    const [page, setPage] = React.useState(0);

    useEffect(() => {
        // props.vm.on('PERIPHERAL_LIST_UPDATE', this.handlePeripheralListUpdate);
        console.log('COMPONENT HEADERS:', headers);
        console.log('COMPONENT ROWS:', rows);

    });
    
    // const handlePeripheralListUpdate = (data) => {
    //     console.error('############## data : ', data);
    // }

    const handleChangePage = (event, newPage) => {
        setPage(newPage);
    };

    const handleChangeRowsPerPage = (event) => {
        setRowsPerPage(parseInt(event.target.value, 10));
        setPage(0);
    };

    const emptyRows = rowsPerPage - Math.min(rowsPerPage, rows.length - page * rowsPerPage);
    
    return (
        <>
        
            <TableContainer component={Paper} className={classes.table}>
        
                <Table aria-label="simple table">
                    <TableHead>
                        <TableRow>
                            {headers.map((header, index) => (
                                <StyledTableCell key={index} align="right">
                                    {header.text}
                                </StyledTableCell>
                            ))}
                        </TableRow>
                    </TableHead>
                    <TableBody>
                    {rows.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((row, index) => (
                        <StyledTableRow  key={index}>

                            {headers.map((header, j) => (
                                <TableCell key={j} align="right">
                                    {row[header.value]}
                                </TableCell>
                            ))}

                        </StyledTableRow>
                    ))}
                    {emptyRows > 0 && (
                        <TableRow style={{ height: 53 * emptyRows }}>
                        <TableCell colSpan={6} />
                        </TableRow>
                    )}
                    </TableBody>
                </Table>
   
            </TableContainer>
            <TablePagination
                rowsPerPageOptions={[ROWS_PER_PAGE, 15]}
                component="div"
                count={rows.length}
                rowsPerPage={rowsPerPage}
                page={page}
                onPageChange={handleChangePage}
                onRowsPerPageChange={handleChangeRowsPerPage}
                />
        </>    
    );
    
}

export default TableCompo;
