class CaptureImage extends React.Component {
    constructor(props) {
        super(props);

        bindAll(this, [
            "handleDelete",
            "handleMouseEnter",
            "handleDeleteCapture",
            "handleMouseOut",
        ]);

        this.state = {
            visibilty: false,
        };
    }

    handleDelete() { }

    handleMouseEnter() {
        this.setState({
            visibilty: true,
        });
    }

    handleMouseOut() {
        this.setState({
            visibilty: false,
        });
    }

    handleDeleteCapture(evt) {
        this.props.handleDeleteCapture(this.props.idx, this.props.seq);
    }

    render() {
        return (
            <div
                idx={this.props.idx}
                className={styles.overImage}
                onMouseOver={this.handleMouseEnter}
                onMouseOut={this.handleMouseOut}
            >
                <img
                    className={styles.capture}
                    draggable={false}
                    src={this.props.item}
                />
                <img
                    className={classNames(
                        styles.icon,
                        this.props.trash && this.state.visibilty
                            ? styles.visibilty
                            : null
                    )}
                    draggable={false}
                    src={trashIcon}
                    idx={this.props.idx}
                    seq={this.props.seq}
                    onClick={this.handleDeleteCapture}
                />
            </div>
        );
    }
}

