const ALGORITHM_OPTIONS = [
    { value: "knn", label: "KNN (default)" },
    { value: "softmax", label: "Transfer Learning (Softmax)" },
];

// MobileNet 특징 벡터 위에 dense 1층 + softmax 를 얹어 학습한다.
async function trainSoftmax(features, labels, numClasses, inputDim) {
    const model = tf.sequential();
    model.add(
        tf.layers.dense({
            units: numClasses,
            activation: "softmax",
            inputShape: [inputDim],
        })
    );
    model.compile({
        optimizer: tf.train.adam(0.001),
        loss: "categoricalCrossentropy",
        metrics: ["accuracy"],
    });

    const xs = tf.tensor2d(features);
    // tidy 로 감싸지 않으면 tensor1d 중간 텐서가 누수된다.
    const ys = tf.tidy(() =>
        tf.oneHot(tf.tensor1d(labels, "int32"), numClasses).cast("float32")
    );

    try {
        await model.fit(xs, ys, {
            epochs: 50,
            batchSize: Math.min(32, features.length),
            shuffle: true,
        });
    } finally {
        xs.dispose();
        ys.dispose();
    }

    return model;
}

// KNNClassifier 와 같은 인터페이스로 감싼다.
// scratch-vm 의 doClassify 가 predictClass(텐서) → {label, classIndex, confidences}
// 만 사용하므로, 이 계약만 맞추면 VM 은 분류기 종류를 알 필요가 없다.
// confidences 의 키는 KNN 과 똑같이 클래스 인덱스여야 한다
// (VM 이 imageMetadata[result.label] 로 배열 인덱싱한다).
class SoftmaxClassifier {
    constructor(model, numClasses) {
        this.model = model;
        this.numClasses = numClasses;
    }

    getNumClasses() {
        return this.numClasses;
    }

    async predictClass(features) {
        // features 는 squeeze 된 1-D 텐서 → [1, inputDim] 으로 만들어 넣는다.
        const logits = tf.tidy(() => this.model.predict(features.expandDims(0)));
        const probs = await logits.data();
        logits.dispose();

        let best = 0;
        const confidences = {};
        for (let i = 0; i < this.numClasses; i++) {
            confidences[i] = probs[i];
            if (probs[i] > probs[best]) {
                best = i;
            }
        }

        return {
            label: String(best),
            classIndex: best,
            confidences: confidences,
        };
    }

    dispose() {
        if (this.model) {
            this.model.dispose();
            this.model = null;
        }
    }
}

