// 클래스 카드 → 학습 카드 → 미리보기 카드를 잇는 베지어 곡선.
// 카드를 펼치면 높이가 바뀌므로 ResizeObserver로 모든 카드를 관찰해야 선이 어긋나지 않는다.
function BezierConnectors({
    containerRef,
    classRefs,
    trainingRef,
    previewRef,
    classCount,
    captureIdx,
}) {
    const [paths, setPaths] = React.useState([]);
    const [size, setSize] = React.useState({ width: 0, height: 0 });

    React.useEffect(() => {
        const container = containerRef.current;
        const training = trainingRef.current;
        if (!container || !training) {
            return;
        }

        const compute = () => {
            const containerRect = container.getBoundingClientRect();
            const scrollLeft = container.scrollLeft;
            const scrollTop = container.scrollTop;
            const trainingRect = training.getBoundingClientRect();

            const tx = trainingRect.left - containerRect.left + scrollLeft;
            const tcy =
                trainingRect.top +
                trainingRect.height / 2 -
                containerRect.top +
                scrollTop;

            const newPaths = [];

            // 클래스 카드 오른쪽 중앙 → 학습 카드 왼쪽 중앙
            classRefs.current.forEach((el) => {
                if (!el) {
                    return;
                }
                const r = el.getBoundingClientRect();
                const cx = r.right - containerRect.left + scrollLeft;
                const cy =
                    r.top + r.height / 2 - containerRect.top + scrollTop;
                const cp = (tx - cx) * 0.5;
                newPaths.push(
                    `M${cx},${cy} C${cx + cp},${cy} ${tx - cp},${tcy} ${tx},${tcy}`
                );
            });

            // 학습 카드 오른쪽 중앙 → 미리보기 카드 왼쪽 중앙
            const preview = previewRef.current;
            if (preview) {
                const previewRect = preview.getBoundingClientRect();
                const sx = trainingRect.right - containerRect.left + scrollLeft;
                const px = previewRect.left - containerRect.left + scrollLeft;
                const pcy =
                    previewRect.top +
                    previewRect.height / 2 -
                    containerRect.top +
                    scrollTop;
                const cp = (px - sx) * 0.5;
                newPaths.push(
                    `M${sx},${tcy} C${sx + cp},${tcy} ${px - cp},${pcy} ${px},${pcy}`
                );
            }

            setPaths(newPaths);
            setSize({
                width: container.scrollWidth,
                height: container.scrollHeight,
            });
        };

        compute();

        const observer = new ResizeObserver(compute);
        observer.observe(container);
        if (training) observer.observe(training);
        if (previewRef.current) observer.observe(previewRef.current);
        classRefs.current.forEach((el) => {
            if (el) observer.observe(el);
        });

        container.addEventListener("scroll", compute);
        window.addEventListener("resize", compute);

        return () => {
            observer.disconnect();
            container.removeEventListener("scroll", compute);
            window.removeEventListener("resize", compute);
        };
    }, [containerRef, classRefs, trainingRef, previewRef, classCount, captureIdx]);

    return (
        <svg
            className={styles.connectors}
            width={size.width || "100%"}
            height={size.height || "100%"}
        >
            {paths.map((d, i) => (
                <path
                    key={i}
                    d={d}
                    fill="none"
                    stroke="#c4c4c4"
                    strokeWidth="2"
                />
            ))}
        </svg>
    );
}

