    removeScriptByUrl(url) {
        const scriptTag = document.querySelector(`script[src="${url}"]`);
        if (scriptTag) {
            scriptTag.remove();
            console.log(`Script tag with src="${url}" has been removed.`);
        } else {
            console.log(`No script tag found with src="${url}".`);
        }
    }

    loadExternalScript(src) {
        return new Promise((resolve, reject) => {
            // 이미 해당 스크립트가 로드되었는지 확인
            if (document.querySelector(`script[src="${src}"]`)) {
                resolve();
                return;
            }
            const script = document.createElement('script');
            script.src = src;
            script.async = true;
            script.onload = () => resolve();
            script.onerror = () => reject(new Error(`Failed to load script: ${src}`));
            document.body.appendChild(script);

            // body 태그의 가장 처음에 추가합니다.
            //   document.body.insertBefore(script, document.body.firstChild);
        });
    }


    loadScriptSynchronously(url) {

        const scriptTag = document.querySelector(`script[src="${url}"]`);
        if (scriptTag) {
            scriptTag.remove();
            console.log(`Script tag with src="${url}" has been removed.`);
        }

        const request = new XMLHttpRequest();
        request.open('GET', url, false);
        request.send(null);
        if (request.status === 200) {
            const script = document.createElement('script');
            script.text = request.responseText;
            script.type = "text/javascript";
            // document.head.appendChild(script);
            document.body.appendChild(script);
        }
    }



