        let cameraList = await this.requestVideoStream_2();
        this.setState({
            cameraList: cameraList,
        });

        const tmData = this.props.onGetTMImageData();

        if (
            tmData == null ||
            tmData.length == 0 ||
            tmData[0] != "image-model"
        ) {
            return;
        }

        this.setState({ labelNames: tmData[1], classIndex: tmData[1].length });
        this.setState({ captureSamples: tmData[2] });

