    requestVideoStream_2() {
        return new Promise((resolve, reject) => {
            if (
                this.vm.runtime.isMobile.Android() ||
                this.vm.runtime.isMobile.iOS()
            ) {
                let videoInputList = [
                    new Array("Front camera", "face-camera"),
                    new Array("Back camera", "enviroment-camera"),
                ];
                resolve(videoInputList);
            } else {
                this.getInputList().then((inputList) => {

                    let videoInputList = inputList
                        .filter((input) => input.kind === "videoinput")
                        .map((item) => [item.label, item.deviceId]);
                    resolve(videoInputList);
                });
            }
        });
    }

    getInputList = async () => {
        if (navigator.mediaDevices.getUserMedia) {
            return (await navigator.mediaDevices.enumerateDevices()) || [];
        } else if (navigator.getUserMedia) {
            return (await navigator.enumerateDevices()) || [];
        } else {
            return [];
        }
    };

