    handleCapture(idx) {
        if (this.state.loaded) {
            const capture = this.videoDevice.takeSnapshot();

            // [[], [], []]
            const captureSamples = this.state.captureSamples;
            const samples = captureSamples[idx];

            const MAX_IMAGE_COUNTS = 500;

            // 클래스당 이미지 500개를 넘을 수 없다.
            if (samples.length < MAX_IMAGE_COUNTS) {
                // samples.push(capture);
                samples.unshift(capture);
                captureSamples[idx] = samples;
                this.setState({ captureSamples: captureSamples });
            }

            this.isTrainable();
        }
    }

