    async handleChange(selector) {

        this.videoDevice.disableVideo();
        this.delay(300);
        this.videoDevice.selectCamera(selector);
        this.delay(100);
        this.videoDevice.enableVideo();

        this.setState({
            selectorNo: selector,
        });
    }

    // 미리보기 캔버스. 웹캠 모드일 때만 VideoManager를 붙인다.
    previewCanvasRef(canvas) {
        this.previewCanvas = canvas;

        if (canvas) {
            this.previewVideo = new VideoManager(
                canvas,
                this.vm,
                this.videoProvider
            );
            // 미리보기가 카메라를 먼저 켜는 경우에도 캡쳐 버튼이 열리도록
            // 클래스 카드와 같은 콜백을 넘긴다.
            this.previewVideo.enableVideo(this.handleAccess, this.handleLoaded);
        } else if (this.previewVideo) {
            this.previewVideo.disableVideo();
            this.previewVideo = null;
        }
    }

    // 클래스 카드 카메라가 열려있지 않으면 공유 카메라를 내린다.
    disableCameraIfIdle() {
        if (!this.canvas) {
            this.videoProvider.disableVideo();
        }
    }

    // Softmax 모델은 tf 텐서를 들고 있으므로 버릴 때 명시적으로 해제한다.
    // 단, 이미 내보낸 모델은 scratch-vm 이 참조 중이라 해제하면 블록이 깨진다.
    disposeClassifier() {
        if (
            this.classifier &&
            this.classifier !== this.exportedClassifier &&
            typeof this.classifier.dispose === "function"
        ) {
            this.classifier.dispose();
        }
        this.classifier = null;
    }

    // 알고리즘을 바꾸면 이전 모델로 추론하지 않도록 학습 상태를 초기화한다.
    handleChangeAlgorithm(algorithm) {
        if (algorithm === this.state.algorithm) {
            return;
        }

        this.stopPredict();
        this.disposeClassifier();

        this.setState({
            algorithm: algorithm,
            modelTrained: false,
            saveModel: false,
            predictions: [],
        });
    }

    handleTogglePreview(enabled) {
        this.setState({ previewEnabled: enabled, predictions: [] }, () => {
            if (enabled) {
                this.startPredict();
            } else {
                this.stopPredict();
                this.disableCameraIfIdle();
            }
        });
    }

    startPredict() {
        if (this.predictInterval) {
            return;
        }
        if (!this.state.previewEnabled || !this.state.modelTrained) {
            return;
        }

        this.predictInterval = setInterval(this.predictFrame, 200);
    }

    stopPredict() {
        if (this.predictInterval) {
            clearInterval(this.predictInterval);
            this.predictInterval = null;
        }
    }

    async predictFrame() {
        if (this.predictBusy || !this.previewCanvas) {
            return;
        }
        if (!this.classifier || !this.featureExtractor) {
            return;
        }
        if (this.classifier.getNumClasses() === 0) {
            return;
        }

        this.predictBusy = true;
        try {
            // handleTrainModel 과 동일한 전처리
            const squeezed = tf.tidy(() => {
                const mytensor = tf.browser
                    .fromPixels(this.previewCanvas)
                    .resizeNearestNeighbor([224, 224])
                    .toFloat()
                    .div(127.5)
                    .sub(1)
                    .expandDims(0);

                const featureVector = this.featureExtractor.predict(mytensor);
                return featureVector.squeeze();
            });

            const result = await this.classifier.predictClass(squeezed);
            squeezed.dispose();

            // 언마운트되었으면 버린다.
            if (!this.previewCanvas) {
                return;
            }

            this.setState({
                predictions: this.state.labelNames.map((name, i) => ({
                    name: name,
                    value: result.confidences[i] || 0,
                })),
            });
        } catch (error) {
            console.error("미리보기 추론 실패:", error);
        } finally {
            this.predictBusy = false;
        }
    }

    isTrainable() {
        if (
            this.state.labelNames.length > 1 &&
            this.state.captureSamples[0].length > 9 &&
            this.state.captureSamples[1].length > 9
        ) {
            this.setState({
                isTrainable: true,
            });
        } else {
            this.setState({
                isTrainable: false,
            });
        }
    }

