    // 양팔과 코의 위치가 이루는 각도를 계산한다.
    calc_angle(args, utils) {

        if (this.handLandMarks.length < 20) {
            return 0;
        }

        const bX = Math.floor((this.handLandMarks[11].x + this.handLandMarks[12].x)/2);
        const bY = Math.floor((this.handLandMarks[11].y + this.handLandMarks[12].y)/2);

        const A = {x:this.handLandMarks[19].x, y:this.handLandMarks[19].y}
        const B = {x:bX, y:bY}
        const C = {x:this.handLandMarks[20].x, y:this.handLandMarks[20].y}

        // B를 꼭짓점으로 하는 두 벡터: BA = A - B, BC = C - B
        const BA = { x: A.x - B.x, y: A.y - B.y };
        const BC = { x: C.x - B.x, y: C.y - B.y };

        // 두 벡터의 내적 (dot product)
        const dotProduct = BA.x * BC.x + BA.y * BC.y;
        
        // 두 벡터의 크기 (magnitude)
        const magBA = Math.sqrt(BA.x * BA.x + BA.y * BA.y);
        const magBC = Math.sqrt(BC.x * BC.x + BC.y * BC.y);
        
        // 벡터 중 하나라도 길이가 0이면 각을 계산할 수 없음
        if (magBA === 0 || magBC === 0) {
            throw new Error(Message.errZeroVector[this.locale]);
        }
        
        // 코사인 값 계산 (내적/곱)
        let cosTheta = dotProduct / (magBA * magBC);
        // 부동소수점 오차를 방지하기 위해 -1과 1 사이로 제한
        cosTheta = Math.min(1, Math.max(-1, cosTheta));
        
        // arccos로 각(라디안 단위) 계산
        const angleRad = Math.acos(cosTheta);
        // 라디안을 도(degree)로 변환
        const angleDeg = angleRad * (180 / Math.PI);
        return Math.floor(angleDeg);
    }
