import classNames from "classnames";
import bindAll from "lodash.bindall";
import PropTypes from "prop-types";
import React, { useState, useEffect } from "react";
import { defineMessages, FormattedMessage, injectIntl, intlShape } from "react-intl";

import Modal from "../../containers/modal.jsx";
import Box from "../box/box.jsx";

import Paper from "@material-ui/core/Paper";
import Tabs from "@material-ui/core/Tabs";
import Tab from "@material-ui/core/Tab";
import Typography from "@material-ui/core/Typography";

import { makeStyles } from "@material-ui/core/styles";

import styles from "./table.css";

import TableCompo from "./table-compo.jsx";

import LineChart from "./linechart-compo.jsx";
import ScatterPlot from "./scatter-compo.jsx";

const useStyles = makeStyles({
    table: {
        width: "100%",
    },
});

function TabPanel(props) {
    const { children, value, index, ...other } = props;

    return (
        <div
            role="tabpanel"
            hidden={value !== index}
            id={`simple-tabpanel-${index}`}
            aria-labelledby={`simple-tab-${index}`}
            {...other}
        >
            {
                value === index && children
                // (
                //   <Box p={3}>
                //     {children}
                //   </Box>
                // )
            }
        </div>
    );
}

TabPanel.propTypes = {
    children: PropTypes.node,
    index: PropTypes.any.isRequired,
    value: PropTypes.any.isRequired,
};

function TableComponent(props) {
    const classes = useStyles();
    const [value, setValue] = React.useState(0); // 첫번째 탭

    const handleClose = () => {
        props.onRequestClose();
    };

    const handleChange = (event, newValue) => {
        setValue(newValue);
    };

    let chartElement = (
        <ScatterPlot headers={props.headers} data={props.data} />
    );

    if (props.chartType == "dataregression") {
        chartElement = <LineChart headers={props.headers} data={props.data} />;
    }

    return (
        <Modal
            fullScreen
            contentLabel={props.title}
            id={props.id}
            onRequestClose={handleClose}
        >
            <Box square className={styles.root}>
                <Tabs
                    className={styles.tabsCompo}
                    value={value}
                    indicatorColor="primary"
                    textColor="primary"
                    onChange={handleChange}
                    aria-label="table and chart tabs"
                >
                    <Tab label={<FormattedMessage defaultMessage="Table" description="Tab title for the data table" id="gui.dataTable.table.tab.table" />} />
                    <Tab label={<FormattedMessage defaultMessage="Chart" description="Tab title for the data chart" id="gui.dataTable.table.tab.chart" />} />
                </Tabs>
                {value == 0 ? (
                    <TabPanel
                        value={value}
                        index={0}
                        className={styles.tabPanel}
                    >
                        <TableCompo headers={props.headers} data={props.data} />
                    </TabPanel>
                ) : (
                    <TabPanel
                        value={value}
                        index={1}
                        className={styles.tabPanel}
                    >
                        {/* <LineChart headers={props.headers} data={props.data} /> */}
                        {/* <ScatterPlot
                            headers={props.headers}
                            data={props.data}
                        /> */}
                        {chartElement}
                    </TabPanel>
                )}

                {/* <TabPanel value={value} index={0}  className={styles.tabPanel}>
                    <TableCompo
                        headers={props.headers}
                        data={props.data}
                    />
                </TabPanel>
                <TabPanel value={value} index={1}  className={styles.tabPanel}>
                    <LineChart 
                         headers={props.headers}
                         data={props.data}
                    />
                </TabPanel> */}
            </Box>
        </Modal>
    );
}

export default injectIntl(TableComponent);
