import React from 'react';
import {injectIntl, intlShape} from 'react-intl';

import BufferedInputHOC from '../forms/buffered-input-hoc.jsx';
import Input from '../forms/input.jsx';
import {
    getBitblockBtNumber,
    setBitblockBtNumber,
    setKamibotBtNumber,
    normalizeBtNumber
} from '../../lib/bluetooth-filter-preference.js';
import {getSettingsMessages} from '../../lib/settings-messages.js';

import styles from './bt-filter-input.css';

const BufferedInput = BufferedInputHOC(Input);

// 헤더의 단일 블루투스 필터 입력창.
// 오른쪽 패널의 블루투스 카드와 동일한 기능이며, 입력한 숫자(1~255)를
// 비트블록·카미봇파이 두 기기의 localStorage 필터 키에 함께 저장한다.
const BtFilterInput = ({intl}) => {
    const t = getSettingsMessages(intl.locale);
    const label = t.btNo;
    const ariaLabel = t.btFilterAria;

    // 초기값은 비트블록 키 기준으로 표시한다.
    const [btNumber, setBtNumber] = React.useState(getBitblockBtNumber);

    const handleSubmit = React.useCallback(raw => {
        const value = normalizeBtNumber(raw);
        if (value === null) return; // 유효하지 않으면 무시 → BufferedInput 이 이전 값 복원
        setBtNumber(value);
        // 두 기기 모두 동일 적용
        setBitblockBtNumber(value);
        setKamibotBtNumber(value);
    }, []);

    return (
        <div className={styles.btFilterItem}>
            <span className={styles.btFilterLabel}>{label}</span>
            <BufferedInput
                type="text"
                className={styles.btFilterInput}
                value={btNumber}
                aria-label={ariaLabel}
                onSubmit={handleSubmit}
            />
        </div>
    );
};

BtFilterInput.propTypes = {
    intl: intlShape.isRequired
};

export default injectIntl(BtFilterInput);
