const BITBLOCK_KEY = "bitblock.btfilter.bitblock";
const KAMIBOT_KEY = "bitblock.btfilter.kamibotpi";

// 유효값: 빈 문자열("") 또는 정수 1~255 의 문자열
const normalize = (value) => {
    if (value === "" || value === null || typeof value === "undefined") return "";
    const s = String(value).trim();
    if (s === "") return "";
    if (!/^\d+$/.test(s)) return null;
    const n = Number(s);
    if (n >= 1 && n <= 255) return String(n);
    return null;
};

const readKey = (key) => {
    try {
        const saved = window.localStorage.getItem(key);
        const v = normalize(saved);
        return v === null ? "" : v;
    } catch (_) {
        /* private mode / SecurityError */
    }
    return "";
};

const writeKey = (key, value) => {
    const v = normalize(value);
    if (v === null) return; // 유효하지 않으면 저장하지 않음
    try {
        window.localStorage.setItem(key, v);
    } catch (_) {
        /* ignore */
    }
};

const getBitblockBtNumber = () => readKey(BITBLOCK_KEY);
const setBitblockBtNumber = (value) => writeKey(BITBLOCK_KEY, value);
const getKamibotBtNumber = () => readKey(KAMIBOT_KEY);
const setKamibotBtNumber = (value) => writeKey(KAMIBOT_KEY, value);

export {
    getBitblockBtNumber,
    setBitblockBtNumber,
    getKamibotBtNumber,
    setKamibotBtNumber,
    normalize as normalizeBtNumber,
    BITBLOCK_KEY as BITBLOCK_BTFILTER_KEY,
    KAMIBOT_KEY as KAMIBOT_BTFILTER_KEY,
};
