import React from "react";
import PropTypes from "prop-types";
import classNames from "classnames";
import {injectIntl, intlShape} from "react-intl";

import Switch from "../switch/switch.jsx";
import Input from "../forms/input.jsx";
import BufferedInputHOC from "../forms/buffered-input-hoc.jsx";
import {
    getKamibotTransport,
    setKamibotTransport,
    getBitblockTransport,
    setBitblockTransport,
    getBBconTransport,
    setBBconTransport,
    TRANSPORTS,
} from "../../lib/transport-preference.js";
import {
    getBitblockBtNumber,
    setBitblockBtNumber,
    getKamibotBtNumber,
    setKamibotBtNumber,
} from "../../lib/bluetooth-filter-preference.js";
import {
    getCameraSwapRedBlue,
    setCameraSwapRedBlue,
} from "../../lib/camera-color-preference.js";

import {getSettingsMessages, withName} from "../../lib/settings-messages.js";

import styles from "./settings-panel.css";

const BufferedInput = BufferedInputHOC(Input);

const SettingsPanel = ({intl, onClose}) => {
    const t = getSettingsMessages(intl.locale);
    const ariaLabel = (name) => withName(t.connectionType, name);
    const filterAriaLabel = (name) => withName(t.btFilterNumber, name);

    const [kamibotTransport, setKamibotState] = React.useState(getKamibotTransport);
    const [bitblockTransport, setBitblockState] = React.useState(getBitblockTransport);
    const [bbconTransport, setBBconState] = React.useState(getBBconTransport);

    const handleKamibotChange = React.useCallback((next) => {
        const value = next ? TRANSPORTS.WEBSERIAL : TRANSPORTS.WEBBLUETOOTH;
        setKamibotState(value);
        setKamibotTransport(value);
    }, []);

    const handleBitblockChange = React.useCallback((next) => {
        const value = next ? TRANSPORTS.WEBSERIAL : TRANSPORTS.WEBBLUETOOTH;
        setBitblockState(value);
        setBitblockTransport(value);
    }, []);

    const handleBBconChange = React.useCallback((next) => {
        const value = next ? TRANSPORTS.WEBSERIAL : TRANSPORTS.WEBBLUETOOTH;
        setBBconState(value);
        setBBconTransport(value);
    }, []);

    const [bitblockBtNumber, setBitblockBtState] = React.useState(getBitblockBtNumber);
    const [kamibotBtNumber, setKamibotBtState] = React.useState(getKamibotBtNumber);

    // 빈 값 또는 1~255 정수만 저장; 그 외 입력은 무시(BufferedInput 이 이전 값으로 복원)
    const normalizeBtNumber = (raw) => {
        const s = String(raw).trim();
        if (s === "") return "";
        if (!/^\d+$/.test(s)) return null;
        const n = Number(s);
        return n >= 1 && n <= 255 ? String(n) : null;
    };

    const handleBitblockBtNumber = React.useCallback((raw) => {
        const value = normalizeBtNumber(raw);
        if (value === null) return;
        setBitblockBtState(value);
        setBitblockBtNumber(value);
    }, []);

    const handleKamibotBtNumber = React.useCallback((raw) => {
        const value = normalizeBtNumber(raw);
        if (value === null) return;
        setKamibotBtState(value);
        setKamibotBtNumber(value);
    }, []);

    const [cameraSwapRedBlue, setCameraSwapState] = React.useState(getCameraSwapRedBlue);

    const handleCameraSwapChange = React.useCallback((next) => {
        setCameraSwapState(next);
        setCameraSwapRedBlue(next);
    }, []);

    return (
        <div className={styles.panel}>
            {onClose ? (
                <button
                    type="button"
                    className={styles.closeButton}
                    onClick={onClose}
                    aria-label={t.close}
                    title={t.close}
                >
                    {"×"}
                </button>
            ) : null}
            <div className={styles.card}>
                <div className={styles.header}>{t.header}</div>
                <div className={styles.row}>
                    <div className={styles.rowLabel}>
                        <span className={styles.rowTitle}>{t.kamibot}</span>
                    </div>
                    <Switch
                        checked={kamibotTransport === TRANSPORTS.WEBSERIAL}
                        leftLabel={t.webBluetooth}
                        rightLabel={t.webSerial}
                        onChange={handleKamibotChange}
                        ariaLabel={ariaLabel(t.kamibot)}
                    />
                </div>
                <div className={styles.divider} />
                <div className={styles.row}>
                    <div className={styles.rowLabel}>
                        <span className={styles.rowTitle}>{t.bitblock}</span>
                    </div>
                    <Switch
                        checked={bitblockTransport === TRANSPORTS.WEBSERIAL}
                        leftLabel={t.webBluetooth}
                        rightLabel={t.webSerial}
                        onChange={handleBitblockChange}
                        ariaLabel={ariaLabel(t.bitblock)}
                    />
                </div>
                <div className={styles.divider} />
                <div className={styles.row}>
                    <div className={styles.rowLabel}>
                        <span className={styles.rowTitle}>{t.bbcon}</span>
                    </div>
                    <Switch
                        checked={bbconTransport === TRANSPORTS.WEBSERIAL}
                        leftLabel={t.webBluetooth}
                        rightLabel={t.webSerial}
                        onChange={handleBBconChange}
                        ariaLabel={ariaLabel(t.bbcon)}
                    />
                </div>
            </div>
            <div className={classNames(styles.card, styles.cardDisabled)}>
                <div className={styles.header}>{t.bluetoothHeader}</div>
                <div className={styles.hint}>{t.btHint}</div>
                <div className={styles.filterRow}>
                    <span className={styles.rowTitle}>{t.bitblock}</span>
                    <BufferedInput
                        small
                        disabled
                        type="text"
                        className={styles.numberInput}
                        value={bitblockBtNumber}
                        onSubmit={handleBitblockBtNumber}
                        aria-label={filterAriaLabel(t.bitblock)}
                    />
                </div>
                <div className={styles.divider} />
                <div className={styles.filterRow}>
                    <span className={styles.rowTitle}>{t.kamibot}</span>
                    <BufferedInput
                        small
                        disabled
                        type="text"
                        className={styles.numberInput}
                        value={kamibotBtNumber}
                        onSubmit={handleKamibotBtNumber}
                        aria-label={filterAriaLabel(t.kamibot)}
                    />
                </div>
            </div>
            <div className={styles.card}>
                <div className={styles.header}>{t.cameraHeader}</div>
                <div className={styles.row}>
                    <div className={styles.rowLabel}>
                        <span className={styles.rowTitle}>{t.cameraSwap}</span>
                        <span className={styles.hint}>{t.cameraSwapHint}</span>
                    </div>
                    <Switch
                        checked={cameraSwapRedBlue}
                        leftLabel={t.off}
                        rightLabel={t.on}
                        onChange={handleCameraSwapChange}
                        ariaLabel={t.cameraSwap}
                    />
                </div>
            </div>
        </div>
    );
};

SettingsPanel.propTypes = {
    intl: intlShape.isRequired,
    onClose: PropTypes.func,
};

export default injectIntl(SettingsPanel);
