    matrix_block(args) {
        return args.MATRIX;
    }

    get_ledColor(args, util) {
        const color = args.COLOR;
        return color;
    }

    get_rgbColor(args, util) {
        let red = MathUtil.clamp(Cast.toNumber(args.RED), 0, 255);
        let green = MathUtil.clamp(Cast.toNumber(args.GREEN), 0, 255);
        let blue = MathUtil.clamp(Cast.toNumber(args.BLUE), 0, 255);

        red = red.toString(16).toUpperCase();
        green = green.toString(16).toUpperCase();
        blue = blue.toString(16).toUpperCase();

        if (red.length == 1) {
            red = "0" + red;
        }
        if (green.length == 1) {
            green = "0" + green;
        }
        if (blue.length == 1) {
            blue = "0" + blue;
        }

        return `#${red}${green}${blue}`;
    }

    get_randomColor(args, util) {
        const letters = "0123456789ABCDEF";
        let color = "#";
        for (let i = 0; i < 6; i++) {
            color += letters[Math.floor(Math.random() * 16)];
        }
        return color;
    }

    display_bright(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (!bitblock) {
            return Promise.resolve();
        }
        // 0 ~ 100사이 값
        let bright = MathUtil.clamp(Cast.toNumber(args.BRIGHT), 0, 100);
        return bitblock.display_bright(bright)
        .then(packet => {
            // 3. 응답 패킷이 정상적으로 도착한 경우
            if (packet) {
                return; 
            }
            // 타임아웃 등의 이유로 패킷이 없으면 기본값 0 반환
            return;
        });
    }

