    //text: '기울기[DIRECT] 인식했을 때',
    whenBoardTilted(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (!bitblock) {
            return Promise.resolve();
        }

        const dir = Cast.toNumber(args.DIRECT);
        const postVal = bitblock.getPosture;



        // MPU 센서와 실제와 다른부분을 조정한다.
        const LEFT_TILT = 0;
        const RIGHT_TILT = 1;
        const UP_TILT = 2;
        const DOWN_TILT = 3;

        if (dir == 1) {
            return postVal[LEFT_TILT] == 1 ? true : false;
        } else if (dir == 2) {
            return postVal[RIGHT_TILT] == 1 ? true : false;
        } else if (dir == 3) {
            return postVal[UP_TILT] == 1 ? true : false;
        } else if (dir == 4) {
            return postVal[DOWN_TILT] == 1 ? true : false;
        } else if (dir == 5) {
            return postVal[LEFT_TILT] == 1 ||
                postVal[RIGHT_TILT] == 1 ||
                postVal[UP_TILT] == 1 ||
                postVal[DOWN_TILT] == 1
                ? true
                : false;
        }
        return false;
    }

    mpu_posture(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (!bitblock) {
            return Promise.resolve(0);
        }

        return new Promise((resolve) => {
            let strVal = 0;
            const postVal = bitblock.getPosture;

            // MPU 센서와 실제와 다른부분을 조정한다.
            const LEFT_TILT = 0;
            const RIGHT_TILT = 1;
            const UP_TILT = 2;
            const DOWN_TILT = 3;

            if (postVal[LEFT_TILT] == 1) {
                strVal = 1;
            } else if (postVal[RIGHT_TILT] == 1) {
                strVal = 2;
            } else if (postVal[UP_TILT] == 1) {
                strVal = 3;
            } else if (postVal[DOWN_TILT] == 1) {
                strVal = 4;
            }
            resolve(strVal);
        });
    }


    mpu_posture_2(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return false;
        }

        const dir = Cast.toNumber(args.DIRECT);

        const postVal = bitblock.getPosture;
        // MPU 센서와 실제와 다른부분을 조정한다.
        const LEFT_TILT = 0;
        const RIGHT_TILT = 1;
        const UP_TILT = 2;
        const DOWN_TILT = 3;

        if (dir == 1) {
            return postVal[LEFT_TILT] == 1 ? true : false;
        } else if (dir == 2) {
            return postVal[RIGHT_TILT] == 1 ? true : false;
        } else if (dir == 3) {
            return postVal[UP_TILT] == 1 ? true : false;
        } else if (dir == 4) {
            return postVal[DOWN_TILT] == 1 ? true : false;
        } else if (dir == 5) {
            return postVal[LEFT_TILT] == 1 ||
                postVal[RIGHT_TILT] == 1 ||
                postVal[UP_TILT] == 1 ||
                postVal[DOWN_TILT] == 1
                ? true
                : false;
        }
        return false;
    }

    
