    light_value(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (!bitblock) {
            return Promise.resolve();
        }

        const pinNo = Cast.toNumber(args.LIGHTSPIN);
        let floatVal = 0;
        if (pinNo === 9 || pinNo === "9") {
            floatVal = bitblock.getLight1;
        } else if (pinNo === 7 || pinNo === "7") {
            floatVal = bitblock.getLight2;
        }
        return parseInt(floatVal, 10);
    }

    light_value_all(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (!bitblock) {
            return Promise.resolve();
        }

        return new Promise((resolve) => {
            const val1 = parseInt(bitblock.getLight1, 10);
            const val2 = parseInt(bitblock.getLight2, 10);
            resolve(`${val1}, ${val2}`);
        });        
    }

    mic_value(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (!bitblock) {
            return Promise.resolve(0);
        }
        return new Promise((resolve) => {
            let floatVal = bitblock.getMic;
            resolve(parseInt(floatVal, 10));
        });
    }

    
    read_joystick(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (!bitblock) {
            return Promise.resolve();
        }

        return bitblock.read_joystic()
        .then(packet => {
            if (packet) {
                // return [xvalue, yvalue];
                const x_axis = (packet[BBRETURN.DATA4] << 8) | packet[BBRETURN.DATA3];
                const y_axis = (packet[BBRETURN.DATA2] << 8) | packet[BBRETURN.DATA1];

                const centerX = 500;
                const centerY = 500;
                const deadZone = 150;
                const dx = x_axis - centerX;
                const dy = y_axis - centerY;
                let retValue = 0;

                if (Math.abs(dx) <= deadZone && Math.abs(dy) <= deadZone) {
                    retValue = 0;
                } else {
                    if (Math.abs(dx) > Math.abs(dy)) {
                        // 수평 방향이 더 큰 경우
                        if (dx > 0) {
                            retValue = 2; // 오른쪽
                        } else {
                            retValue = 4; // 왼쪽
                        }
                    } else {
                        // 수직 방향이 더 큰 경우
                        if (dy < 0) {
                            retValue = 1; // 위쪽 (y가 작을수록 위쪽)
                        } else {
                            retValue = 3; // 아래쪽
                        }
                    }
                    return retValue;
                }
            }
            // 타임아웃 등의 이유로 패킷이 없으면 기본값 0 반환
            return 0;
        });
    }


    joystick_button(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (!bitblock) {
            return Promise.resolve();
        }

        const pin = Cast.toNumber(args.PIN);
        return bitblock.digital_read(pin)
        .then(packet => {
            if (packet) {
                return packet[BBRETURN.DATA1];
            }
            // 타임아웃 등의 이유로 패킷이 없으면 기본값 0 반환
            return 0;
        });
    }

    multi_switch(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (!bitblock) {
            return Promise.resolve();
        }
        const pin = Cast.toNumber(args.PIN);
        return bitblock.analog_read(pin)
        .then(packet => {
            if (packet) {
                const al = packet[BBRETURN.DATA1]; // low byte
                const ah = packet[BBRETURN.DATA2]; // high byte
                const val = (ah << 8) | al;

                if( val > 1000) {
                    return 1;
                } else if (val > 600) {
                    return 4;
                } else if (val > 300) {
                    return 2;
                } else if (val > 100) {
                    return 3;
                } else {
                    return 0;
                } 
            }
            // 타임아웃 등의 이유로 패킷이 없으면 기본값 0 반환
            return 0;
        });
    }

    func_map(args) {
        if (
            args.VALUE1 == "" ||
            args.VALUE2 == "" ||
            args.VALUE3 == "" ||
            args.VALUE4 == "" ||
            args.VALUE5 == ""
        ) {
            return 0;
        }

        let val1 = Cast.toNumber(args.VALUE1);
        let val2 = Cast.toNumber(args.VALUE2);
        let val3 = Cast.toNumber(args.VALUE3);
        let val4 = Cast.toNumber(args.VALUE4);
        let val5 = Cast.toNumber(args.VALUE5);

        if (val1 >= val3) {
            val1 = val3;
        }
        return MathUtil.scale(val1, val2, val3, val4, val5).toFixed(3);
    }

    func_random(args) {
        if (args.MIN == "" || args.MAX == "") {
            return 0;
        }

        const min = Cast.toNumber(args.MIN);
        const max = Cast.toNumber(args.MAX);
        return Math.floor(Math.random() * (max - min + 1) + min);
    }

    func_value1_or_value2(args) {
        const cond = Cast.toBoolean(args.CONDITION);

        const value_1 = args.VALUE1;
        const value_2 = args.VALUE2;
        return cond ? value_1 : value_2;
    }

    get_firmware_version(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (!bitblock) {
            return Promise.resolve();
        }

        return bitblock.get_firmware_version()
        .then(packet => {
            // 3. 응답 패킷이 정상적으로 도착한 경우
            if (packet) {
                const main = packet[BBRETURN.DATA1];
                const minor = packet[BBRETURN.DATA2];
                const fix = packet[BBRETURN.DATA3];
                return `${main}.${minor}.${fix}`;
            }
            // 타임아웃 등의 이유로 패킷이 없으면 기본값 0 반환
            return "0.0.0";
        });
    }

    _targetSay(message) {
        if (!this.enableLog) {
            return;
        }

        const target = this.runtime.targets[1];
        if (target) {
            this.runtime.emit("SAY", this.runtime.targets[1], "say", message);
        }

        setTimeout(() => {
            if (target) {
                this.runtime.emit("SAY", this.runtime.targets[1], "say", "");
            }
        }, 1000);
    }

    _setLocale() {
        const locale = formatMessage.setup().locale;
        return AvailableLocales.includes(locale) ? locale : "en";
    }
