import VideoProvider from "../../lib/video/video-provider.js";
/**
 * Video Manager for Camera Modal
 */
class VideoManager {
    constructor(canvas, vm, sharedProvider = null) {
        this._vm = vm;
        // sharedProvider가 주어지면 getUserMedia 스트림을 공유한다(미리보기 + 클래스 카드 동시 사용).
        this._ownsProvider = !sharedProvider;
        this._videoProvider = sharedProvider || new VideoProvider(vm);
        this._frameTimeout = 16;
        this._canvas = canvas;

        this._canvasWidth = 240; // Double Stage Width
        this._canvasHeight = 240; // Double Stage Height

        this._videoFeedInterval = null;
        // console.error("🐶🐶🐶 {VideoManager} this._vm : ", this._vm);
    }

    enableVideo(onPermissionSuccess, onVideoLoaded) {
        const thisContext = this;

        console.error('🔰🔰🔰 enable');
        console.error('this._vm.runtime.ioDevices.video.mirror : ' , this._vm.runtime.ioDevices.video.mirror);


        this._videoProvider.enableVideo(onVideoLoaded).then(() => {
            if (onPermissionSuccess) onPermissionSuccess();

            const ctx = thisContext._canvas.getContext("2d", { willReadFrequently: true });

            if (thisContext._vm.runtime.ioDevices.video.mirror) {
                console.error("미러모드 설정");

                // 좌우 반전시켜서 
                ctx.scale(-1, 1);
                // 좌우 반전되면 캔버스의 위치가 바뀐다. 캔버스의 위치를 원래 위치로 이동시킴.
                ctx.translate(thisContext._canvasWidth * -1, 0);
            }

            if (onVideoLoaded) {
                thisContext._videoProvider.video.onloadeddata = () => {
                    onVideoLoaded();
                };
            }

            thisContext._drawFrames_2();
        });
    }

    _getFrame(width, height, mirror = false) {
        return this._videoProvider.getFrame({
            dimensions: [width, height],
            // dimensions: [360, 360],
            mirror: mirror,
            format: VideoProvider.FORMAT_CANVAS,
        });
    }

    _drawFrames_2() {
        if (this._videoFeedInterval) {
            clearInterval(this._videoFeedInterval);
            this._videoFeedInterval = null;
        }

        this._videoFeedInterval = setInterval(() => {
            const frame = this._getFrame(360, 360);
            if (!frame) return; // 영상이 아직 준비되지 않았으면 이번 프레임은 건너뛴다.

            //360x360 캔버스를 224x224캔버스에 축소해서 그리기
            this._canvas
                .getContext("2d", { willReadFrequently: true })
                .drawImage(
                    frame,
                    0,
                    0,
                    this._canvas.width,
                    this._canvas.height
                );
        }, this._frameTimeout);
    }

    _drawFrames() {
        const video = this._videoProvider.video;

        // 960x720으로 설정해야 한다. 20240815
        video.setAttribute("width", "960px");
        video.setAttribute("height", "720px");

        // ----------------------------------------------------------
        // console.log(
        //     "{video-manager} video  width: ",
        //     video.width,
        //     " height: ",
        //     video.height
        // );
        // console.log(
        //     "{video-manager} _canvas width: ",
        //     this._canvasWidth,
        //     " height: ",
        //     this._canvasHeight
        // );
        // console.log(
        //     "{video-manager} canvas width: ",
        //     this._canvas.width,
        //     " height: ",
        //     this._canvas.height
        // );
        // ----------------------------------------------------------

        const offX = Math.round((video.width - video.height) / 2);

        if (this._videoFeedInterval) {
            clearInterval(this._videoFeedInterval);
            this._videoFeedInterval = null;
        }

        this._videoFeedInterval = setInterval(() => {
            //SRC 120, 0, 720, 720
            //DEST 0,0,480,480
            this._canvas.getContext("2d", { willReadFrequently: true }).drawImage(
                video,
                // source x, y, width, height
                0 + offX,
                0,
                video.width - offX * 2,
                video.height,
                // dest x, y, width, height
                0,
                0,
                this._canvasWidth + 120, // 224인 경우
                this._canvasHeight + 120
            );
        }, this._frameTimeout);
    }

    takeSnapshot() {
        // 계속 사진을 찍어야 하니까...
        // clearInterval(this._videoFeedInterval);
        // return this._canvas.toDataURL("image/png");

        // 데이터는 360x360사이즈, 미러 적용(좌우전환)로 저장해둔다.
        let mirror = this._vm.runtime.ioDevices.video.mirror;
        // console.error("takeSnapshot :", mirror);
        
        // const mycanvas = this._getFrame(360, 360, true);
        const mycanvas = this._getFrame(360, 360, mirror)
        return mycanvas.toDataURL("image/png");
    }

    selectCamera(idx) {
        this._videoProvider.selectCamera(idx);
    }

    disableVideo() {
        if (this._videoFeedInterval) {
            clearInterval(this._videoFeedInterval);
            this._videoFeedInterval = null;
        }
        if (this._ownsProvider) {
            this._videoProvider.disableVideo();
        }
    }
}

export default VideoManager;
