/**
 * Targets to print, in page order: the stage first, then the sprites in sprite list order.
 * Clones and targets without any scripts are skipped.
 * @param {VirtualMachine} vm the VM instance
 * @return {Array.<RenderedTarget>} targets that have at least one script
 */
const getPrintableTargets = vm => {
    const targets = vm.runtime.targets.filter(t => t.isStage || t.isOriginal);
    const stage = targets.filter(t => t.isStage);
    const sprites = targets.filter(t => !t.isStage);
    return stage.concat(sprites).filter(t => t.blocks.getScripts().length > 0);
};

/**
 * Build the workspace XML for a target, the same way VirtualMachine.emitWorkspaceUpdate
 * does for the editing target, minus its unused-broadcast cleanup (which mutates the project).
 * @param {VirtualMachine} vm the VM instance
 * @param {RenderedTarget} target the target to serialize
 * @return {string} workspace XML that scratch-blocks can load
 */
const getTargetXml = (vm, target) => {
    const stageVariables = vm.runtime.getTargetForStage().variables;
    const globalVariables = Object.keys(stageVariables).map(k => stageVariables[k]);
    const localVariables = target.isStage ? [] :
        Object.keys(target.variables).map(k => target.variables[k]);
    const workspaceComments = Object.keys(target.comments)
        .map(k => target.comments[k])
        .filter(c => c.blockId === null);

    return `<xml xmlns="http://www.w3.org/1999/xhtml">
        <variables>
            ${globalVariables.map(v => v.toXML()).join()}
            ${localVariables.map(v => v.toXML(true)).join()}
        </variables>
        ${workspaceComments.map(c => c.toXML()).join()}
        ${target.blocks.toXML(target.comments)}
    </xml>`;
};

export {
    getPrintableTargets,
    getTargetXml
};
