const KEY = "bitblock.transport.kamibotpi";
const BITBLOCK_KEY = "bitblock.transport.bitblock";
const BBCON_KEY = "bitblock.transport.bbcon";

const VALUES = {
    WEBSERIAL: "webserial",
    WEBBLUETOOTH: "webbluetooth",
};

// 디폴트: 모바일(Android/iOS)이면 WebBluetooth, 그 외에는 WebSerial 지원 시 WebSerial
const computeDefault = () => {
    if (typeof navigator === "undefined") return VALUES.WEBBLUETOOTH;
    const ua = navigator.userAgent || "";
    const isMobile = /Android|iPhone|iPad|iPod/i.test(ua);
    const hasWebSerial = !!navigator.serial;
    if (isMobile) return VALUES.WEBBLUETOOTH;
    return hasWebSerial ? VALUES.WEBSERIAL : VALUES.WEBBLUETOOTH;
};

const getKamibotTransport = () => {
    try {
        const saved = window.localStorage.getItem(KEY);
        if (saved === VALUES.WEBSERIAL || saved === VALUES.WEBBLUETOOTH) {
            return saved;
        }
    } catch (_) {
        /* private mode / SecurityError */
    }
    return computeDefault();
};

const setKamibotTransport = (value) => {
    if (value !== VALUES.WEBSERIAL && value !== VALUES.WEBBLUETOOTH) return;
    try {
        window.localStorage.setItem(KEY, value);
    } catch (_) {
        /* ignore */
    }
};

const getBitblockTransport = () => {
    try {
        const saved = window.localStorage.getItem(BITBLOCK_KEY);
        if (saved === VALUES.WEBSERIAL || saved === VALUES.WEBBLUETOOTH) {
            return saved;
        }
    } catch (_) {
        /* private mode / SecurityError */
    }
    return computeDefault();
};

const setBitblockTransport = (value) => {
    if (value !== VALUES.WEBSERIAL && value !== VALUES.WEBBLUETOOTH) return;
    try {
        window.localStorage.setItem(BITBLOCK_KEY, value);
    } catch (_) {
        /* ignore */
    }
};

const getBBconTransport = () => {
    try {
        const saved = window.localStorage.getItem(BBCON_KEY);
        if (saved === VALUES.WEBSERIAL || saved === VALUES.WEBBLUETOOTH) {
            return saved;
        }
    } catch (_) {
        /* private mode / SecurityError */
    }
    return computeDefault();
};

const setBBconTransport = (value) => {
    if (value !== VALUES.WEBSERIAL && value !== VALUES.WEBBLUETOOTH) return;
    try {
        window.localStorage.setItem(BBCON_KEY, value);
    } catch (_) {
        /* ignore */
    }
};

export {
    getKamibotTransport,
    setKamibotTransport,
    getBitblockTransport,
    setBitblockTransport,
    getBBconTransport,
    setBBconTransport,
    VALUES as TRANSPORTS,
    KEY as KAMIBOT_TRANSPORT_KEY,
    BITBLOCK_KEY as BITBLOCK_TRANSPORT_KEY,
    BBCON_KEY as BBCON_TRANSPORT_KEY,
};
