// 응답을 기다리지 않는 명령의 ACK 가 이 시간 안에 오지 않으면 더는 기다리지 않는다.
// (실측 22~181ms. 같은 코드를 기다리는 명령의 완료 ACK 를 잘못 삼키는 구간이므로 짧게 둔다)
const UNAWAITED_ACK_MS = 500;

// 보낸 패킷의 Mode type(buf[5]) → 로봇이 돌려주는 ACK 패킷의 data[5] 코드.
// 2026-10-19 실제 로봇 실측. 프로토콜 문서 3.2절 표와 다르므로 실측값을 따른다.
// 컨트롤 모드 응답(0x02)과 맵 오른쪽 돌기 완료(0x02)는 패킷 전체가 같은 모양이라
// 내용으로는 구분할 수 없다 → 보낸 명령 기준으로 짝을 맞춘다.
function ackCodeOf(buf) {
    switch (buf[5]) {
        case 0x01: // 맵보드: Mode command 그대로 (0x01 앞, 0x02 오른쪽, 0x03 왼쪽, 0x04 뒤)
            return buf[6];
        case 0x02: // 컨트롤 모드 (수신 즉시 응답)
            return 0x02;
        case 0x03: // RGB
            return 0x0a;
        case 0x04: // Top(머리)
            return 0x0b;
        case 0x0b: // 도형 그리기
            return 0x0d;
        case 0x0c: // 정밀 제어
            return 0x0c;
        case 0x0d: // 멜로디
            return 0x0e;
        case 0x0e: // 라인맵 (실측 안 함 — 기존 분류값)
            return 0x0f;
        default:
            return null;
    }
}

