    send(message) {
        if (!this.isConnected()) {
            return;
        }
        this._parent.send(this._connectDevice.id, message);
    }

    // 파이어-앤-포겟 송신 (스로틀링만 적용)
    _sendFireAndForget(buf) {
        if (!this.isConnected()) return Promise.resolve();
        const elapsed = Date.now() - this._lastSendTime;
        if (elapsed < this._minSendInterval) {
            return new Promise((resolve) => {
                setTimeout(() => {
                    this._lastSendTime = Date.now();
                    this._lastSendWasAck = false;
                    this._noteUnawaitedAck(ackCodeOf(buf));
                    this.send(buf);
                    resolve();
                }, this._minSendInterval - elapsed);
            });
        }
        this._lastSendTime = Date.now();
        this._lastSendWasAck = false;
        this._noteUnawaitedAck(ackCodeOf(buf));
        this.send(buf);
        return Promise.resolve();
    }

    // 응답을 기다리지 않는 명령에도 로봇은 ACK 를 보낸다(정지·연속 이동 → 0x02 등).
    // 이 ACK 가 같은 코드를 기다리는 명령(맵 오른쪽 돌기 → 0x02)을 풀지 않도록 기록해 둔다.
    _noteUnawaitedAck(code) {
        if (code === null) return;
        this._unawaitedAcks.push({ code, expire: Date.now() + UNAWAITED_ACK_MS });
    }

    // ACK 코드를 기다리는 가장 오래된 명령을 완료 처리한다.
    // data[6] === 0xff (로봇이 명령을 거부) 도 대기는 풀어 블록이 멈추지 않게 한다.
    _resolvePending(code, data) {
        for (const [category, queue] of this._pendingCommands) {
            const idx = queue.findIndex((cmd) => cmd.code === code);
            if (idx < 0) continue;
            const cmd = queue.splice(idx, 1)[0];
            if (queue.length === 0) this._pendingCommands.delete(category);
            cmd.resolve(data);
            return;
        }
    }

    // ACK 대기 송신 (카테고리별 FIFO 큐 + 타임아웃)
    _sendWithAck(buf, category) {
        if (!this.isConnected()) return Promise.resolve();
        // 직전 송신이 ACK-대기였다면 응답 수신 시점에 펌웨어는 이미 idle →
        // 추가 스로틀 불필요. 직전이 파이어-앤-포겟인 경우에만 UART 버퍼
        // 보호를 위해 20ms 갭 확보.
        if (!this._lastSendWasAck) {
            const elapsed = Date.now() - this._lastSendTime;
            if (elapsed < this._minSendInterval) {
                return new Promise((resolve) => {
                    setTimeout(
                        () => resolve(this._sendWithAck(buf, category)),
                        this._minSendInterval - elapsed
                    );
                });
            }
        }
        return new Promise((resolve) => {
            const cmd = { resolve: null, timeout: null, code: ackCodeOf(buf) };
            cmd.resolve = (pkt) => {
                if (cmd.timeout !== null) {
                    clearTimeout(cmd.timeout);
                    cmd.timeout = null;
                }
                resolve(pkt);
            };

            // MUSIC 과 컨트롤 모드(0x02, 좌우 속도)는 "패킷 전송 완료 후 응답" 이라 짧은 타임아웃 유지.
            // 컨트롤 모드 ACK(0x02)는 응답을 기다리지 않는 정지·연속 이동과 코드가 같아,
            // 로봇이 그쪽 ACK 를 빠뜨리면 이 명령의 ACK 가 대신 소모될 수 있다 → 타임아웃으로 회복.
            // 나머지(맵보드/정밀/MOVE_HEAD/DRAW_SHAPE/LINE_TRACE)는
            // "동작 완료 후 응답" 이므로 타임아웃 없이 ACK 를 기다림.
            // 연결 끊김 / STOP 시 stopAll() 이 큐를 전부 resolve 하여 회복.
            if (category === RESPONSE_CATEGORIES.MUSIC || buf[5] === 0x02) {
                cmd.timeout = setTimeout(() => {
                    const queue = this._pendingCommands.get(category);
                    if (queue) {
                        const idx = queue.indexOf(cmd);
                        if (idx >= 0) queue.splice(idx, 1);
                        if (queue.length === 0)
                            this._pendingCommands.delete(category);
                    }
                    cmd.timeout = null;
                    // 늦게 오는 ACK(실측 약 550ms)가 다음 멜로디 대기를 풀지 않게 한다.
                    this._noteUnawaitedAck(cmd.code);
                    resolve();
                }, MUSIC_TIMEOUT_MS);
            }

            if (!this._pendingCommands.has(category)) {
                this._pendingCommands.set(category, []);
            }
            this._pendingCommands.get(category).push(cmd);

            this._lastSendTime = Date.now();
            this._lastSendWasAck = true;
            this.send(buf);
        });
    }

    stopAll() {
        // 대기 중 명령을 전부 resolve 한 뒤 큐 비우기
        for (const queue of this._pendingCommands.values()) {
            for (const cmd of queue) {
                cmd.resolve();
            }
        }
        this._pendingCommands.clear();
        this._unawaitedAcks = [];

        const sendData = this._stopMsg();
        this.send(sendData);
    }

