import classNames from 'classnames';
import {defineMessages, FormattedMessage, injectIntl, intlShape} from 'react-intl';
import PropTypes from 'prop-types';
import React from 'react';

import Box from '../box/box.jsx';
import Modal from '../../containers/modal.jsx';

import sharedMessages from '../../lib/shared-messages';

import styles from './load-from-url-modal.css';

const messages = defineMessages({
    urlInputLabel: {
        id: 'gui.loadFromUrlModal.inputLabel',
        defaultMessage: 'Project URL (.sb3)',
        description: 'Label above the URL text input in the Load from URL modal'
    },
    urlInputPlaceholder: {
        id: 'gui.loadFromUrlModal.inputPlaceholder',
        defaultMessage: 'https://example.com/project.sb3',
        description: 'Placeholder for the URL text input'
    },
    invalidUrl: {
        id: 'gui.loadFromUrlModal.invalidUrl',
        defaultMessage: 'Please enter a valid URL.',
        description: 'Error shown when the URL input is not a valid URL'
    },
    loading: {
        id: 'gui.loadFromUrlModal.loading',
        defaultMessage: 'Loading\u2026',
        description: 'Label on the Load button while the project is being fetched'
    }
});

const LoadFromUrlModalComponent = props => (
    <Modal
        className={styles.modalContent}
        contentLabel={props.intl.formatMessage(sharedMessages.loadFromUrlTitle)}
        shouldCloseOnOverlayClick={false}
        onRequestClose={props.onCancel}
    >
        <Box className={styles.body}>
            <Box className={styles.label}>
                <FormattedMessage {...messages.urlInputLabel} />
            </Box>
            <input
                autoFocus
                className={classNames(styles.urlTextInput, {
                    [styles.hasError]: Boolean(props.errorMessage)
                })}
                disabled={props.isLoading}
                placeholder={props.intl.formatMessage(messages.urlInputPlaceholder)}
                type="url"
                value={props.url}
                onChange={props.onChangeUrl}
                onKeyDown={props.onKeyDown}
            />
            <div className={styles.errorMessage}>
                {props.errorMessage || '\u00a0'}
            </div>
            <Box className={styles.buttonRow}>
                <button
                    className={styles.cancelButton}
                    disabled={props.isLoading}
                    onClick={props.onCancel}
                >
                    <FormattedMessage
                        defaultMessage="Cancel"
                        description="Button in Load from URL modal to cancel the dialog"
                        id="gui.loadFromUrlModal.cancel"
                    />
                </button>
                <button
                    className={styles.okButton}
                    disabled={props.isLoading || !props.url}
                    onClick={props.onLoad}
                >
                    {props.isLoading ? (
                        <FormattedMessage {...messages.loading} />
                    ) : (
                        <FormattedMessage
                            defaultMessage="Load"
                            description="Button in Load from URL modal to confirm the load"
                            id="gui.loadFromUrlModal.load"
                        />
                    )}
                </button>
            </Box>
        </Box>
    </Modal>
);

LoadFromUrlModalComponent.propTypes = {
    errorMessage: PropTypes.string,
    intl: intlShape.isRequired,
    isLoading: PropTypes.bool,
    onCancel: PropTypes.func.isRequired,
    onChangeUrl: PropTypes.func.isRequired,
    onKeyDown: PropTypes.func.isRequired,
    onLoad: PropTypes.func.isRequired,
    url: PropTypes.string.isRequired
};

export default injectIntl(LoadFromUrlModalComponent);
