/* eslint-disable */
// Web Serial API 기반 시리얼 어댑터.
// bleWebBluetooth.js 와 동일한 외부 인터페이스(connectPeripheral / write / startNotifications /
// disconnect / scan / stopScan / getDevice / isConnected 등)를 제공하여, 상위 확장(index.js)이
// 분기 없이 동일 콜백 경로(_onConnectLink, _onMessageLink, send)를 사용할 수 있도록 한다.
//
// 대상 하드웨어: USB-BLE 브릿지 동글(FTDI FT231X, VID=0x0403 PID=0x6015, baud=57600).
// 동글은 시리얼 UART ↔ BLE UART 를 투명(transparent)하게 매핑하므로 Kamibot 20바이트 패킷을
// 그대로 주고받는다. 기존 _onMessageLink 가 base64 문자열을 기대하므로, 수신 데이터는
// 20바이트 경계로 묶어 base64 인코딩 후 콜백에 넘긴다.

const Base64Util = require("../util/base64-util");

const KAMIBOT_PACKET_SIZE = 20;
const KAMIBOT_START_BYTE = 0x41; // 'A'
const KAMIBOT_END_BYTE = 0x5a; // 'Z'

class SERIALWEBSERIAL {
    /**
     * @param {Runtime} runtime
     * @param {string} extensionId
     * @param {object} peripheralOptions - { filters: [{ usbVendorId, usbProductId }], baudRate }
     * @param {function} connectCallback - 연결 성공 콜백 (address 전달)
     * @param {function} resetCallback - 리셋/연결 해제 콜백
     * @param {number} type - 0: Kamibot, 1: Bitblock (현재는 Kamibot 만 사용)
     */
    constructor(
        runtime,
        extensionId,
        peripheralOptions,
        connectCallback,
        resetCallback,
        type
    ) {
        this._runtime = runtime;
        this._extensionId = extensionId;
        this._peripheralOptions = peripheralOptions || {};
        this._connectCallback = connectCallback;
        this._resetCallback = resetCallback;
        this._type = type;

        this._availablePeripherals = {};
        this._devices = {};
        this._btDevices = {}; // SerialPort 보관용 (bleWebBluetooth 의 _btDevices 역할)

        this._port = null;
        this._reader = null;
        this._writer = null;
        this._connected = false;
        this._connecting = false;
        this._connectId = null;
        this._characteristicDidChangeCallback = null;
        this._discoverTimeoutID = null;
        this._stopScan = 0;
        this._rxBuffer = new Uint8Array(0);
        this._readLoopStopped = true;
        // read loop 가 완전히 종료(=reader 락 해제)되면 resolve 되는 프라미스.
        // _closePort 가 이걸 await 해서 releaseLock → port.close 순서를 보장한다(락-세이프 close).
        this._readLoopDone = null;
        this._disconnectHandler = null;

        // bleWebBluetooth 와 동일하게 write/open/close 동시성을 FIFO 로 직렬화
        this._opChain = Promise.resolve();

        // 유저 제스처(scan 버튼 클릭) 컨텍스트에서 즉시 피커 오픈
        this.requestPeripheral();
    }

    // ========== bleWebBluetooth 호환 인터페이스 ==========

    requestPeripheral() {
        if (typeof navigator === "undefined" || !navigator.serial) {
            console.error(
                "🔥 [serialWebSerial] Web Serial API not available. HTTPS/localhost + Chromium 필요."
            );
            this._handleRequestError(
                new Error("Web Serial API not available")
            );
            return;
        }

        this._availablePeripherals = {};
        this._stopScan = 0;

        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
        }
        this._discoverTimeoutID = setTimeout(
            this._handleDiscoverTimeout.bind(this),
            30000
        );

        const options = this._buildRequestPortOptions();

        navigator.serial
            .requestPort(options)
            .then((port) => this._handlePortPicked(port))
            .catch((err) => {
                if (this._discoverTimeoutID) {
                    clearTimeout(this._discoverTimeoutID);
                    this._discoverTimeoutID = null;
                }
                // NotFoundError: 사용자가 피커에서 취소
                if (err && err.name === "NotFoundError") {
                    this._runtime.emit(
                        this._runtime.constructor.PERIPHERAL_SCAN_TIMEOUT
                    );
                } else {
                    console.error(
                        "🔥 [serialWebSerial] requestPort error:",
                        err
                    );
                    this._handleRequestError(err);
                }
            });
    }

    // UI "새로고침" 버튼 대응
    scan() {
        console.log("🐲 [serialWebSerial] scan() — 시리얼 피커 재호출");

        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
            this._discoverTimeoutID = null;
        }

        this._availablePeripherals = {};
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_LIST_UPDATE,
            this._availablePeripherals
        );

        this.requestPeripheral();
    }

    stopScan() {
        this._stopScan = 1;
        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
            this._discoverTimeoutID = null;
        }
    }

    connectPeripheral(id) {
        // 중복 호출 방어 — bleWebBluetooth 와 동일한 패턴
        if (this._connected && this._connectId === id) {
            console.info(
                "🟡 [serialWebSerial] connectPeripheral: already connected, ignoring duplicate",
                id
            );
            return;
        }
        if (this._connecting && this._connectId === id) {
            console.info(
                "🟡 [serialWebSerial] connectPeripheral: already connecting, ignoring duplicate",
                id
            );
            return;
        }

        this._connectId = id;
        const port = this._btDevices[id];

        if (!port) {
            console.error(
                "🔥 [serialWebSerial] connectPeripheral: port not found for id:",
                id
            );
            this._handleRequestError(new Error("port not found"));
            return;
        }

        // 장치가 중간에 뽑힌 경우 disconnect 이벤트로 정리
        this._disconnectHandler = this._handlePortDisconnected.bind(this, id);
        if (typeof port.addEventListener === "function") {
            port.addEventListener("disconnect", this._disconnectHandler);
        }

        const baudRate =
            (this._peripheralOptions && this._peripheralOptions.baudRate) ||
            115200;

        this._connecting = true;
        this._enqueue(() => port.open({ baudRate }))
            .then(() => {
                this._port = port;
                this._connected = true;
                this._connecting = false;
                this._rxBuffer = new Uint8Array(0);

                // read loop 는 startNotifications 에서 기동 (bleWebBluetooth 대응)
                if (this._connectCallback) {
                    this._connectCallback(id);
                }
                this._runtime.emit(
                    this._runtime.constructor.PERIPHERAL_CONNECTED,
                    id
                );
            })
            .catch((err) => {
                this._connecting = false;
                console.error(
                    "🔥 [serialWebSerial] port.open error:",
                    err
                );
                this._handleRequestError(err);
            });
    }

    disconnect(/* address */) {
        const closingId = this._connectId;
        if (this._connected) {
            this._connected = false;
        }
        this._connecting = false;

        // read loop 종료 및 writer/reader 해제 → port.close 순서로 정리
        const closePromise = this._closePort().catch((err) => {
            console.warn(
                "[serialWebSerial] disconnect close error:",
                err && err.message
            );
        });

        // 이후 오퍼레이션이 닫힌 포트에 걸리지 않도록 체인 리셋
        this._opChain = closePromise;

        if (this._resetCallback) {
            this._resetCallback(closingId);
        }

        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
            this._discoverTimeoutID = null;
        }

        // 재연결 시 stale SerialPort 핸들을 재사용하지 않도록 캐시 맵 정리.
        this._btDevices = {};
        this._devices = {};
        this._availablePeripherals = {};
        this._connectId = null;

        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_DISCONNECTED,
            closingId
        );
    }

    isConnected() {
        return this._connected;
    }

    // bleWebBluetooth 와 동일한 FIFO 직렬화
    _enqueue(fn) {
        const next = this._opChain.then(fn, fn);
        this._opChain = next.catch(() => {});
        return next;
    }

    // 시리얼에는 characteristic 개념이 없으므로 service/char 인자는 무시.
    // Web Bluetooth 의 ch.startNotifications() 와 대응 — 여기서 실제 데이터 수신(read loop)을 시작한다.
    startNotifications(
        address,
        serviceId,
        characteristicId,
        onCharacteristicChanged = null
    ) {
        this._characteristicDidChangeCallback = onCharacteristicChanged;
        if (this._readLoopStopped && this._connected) {
            this._startReadLoop();
        }
        return Promise.resolve();
    }

    // read 도 notification 경로에 위임. bleWebBluetooth 호환.
    read(
        address,
        serviceId,
        characteristicId,
        optStartNotifications = false,
        onCharacteristicChanged = null
    ) {
        if (onCharacteristicChanged) {
            this._characteristicDidChangeCallback = onCharacteristicChanged;
        }
        return Promise.resolve(null);
    }

    write(
        address,
        serviceId,
        characteristicId,
        message,
        encoding = null,
        withResponse = null
    ) {
        return this._enqueue(() => {
            if (!this._connected || !this._port) {
                return Promise.reject(new Error("serial port not connected"));
            }
            let bytes;
            if (encoding === "base64") {
                bytes = Base64Util.base64ToUint8Array(message);
            } else if (message instanceof ArrayBuffer) {
                bytes = new Uint8Array(message);
            } else if (message instanceof Uint8Array) {
                bytes = message;
            } else if (typeof message === "string") {
                bytes = new TextEncoder().encode(message);
            } else {
                bytes = new Uint8Array(message);
            }

            const writable = this._port.writable;
            if (!writable) {
                return Promise.reject(new Error("serial writable stream unavailable"));
            }

            // 기존 writer 재사용, 없으면 획득. writable stream 은 동시에 한 writer 만 가질 수 있음.
            if (!this._writer) {
                // 공유 객체에 이전 세션의 leaked writer 락이 남아 있으면 getWriter 가 throw.
                // 조용히 실패하지 않도록 명시적 에러로 표면화.
                if (writable.locked) {
                    return Promise.reject(
                        new Error("serial writable stream locked (stale lock)")
                    );
                }
                this._writer = writable.getWriter();
            }
            return this._writer.write(bytes);
        }).catch((err) => {
            this._handleOperationError(err, "write");
        });
    }

    getDevice(pid) {
        return this._devices[pid];
    }

    // bleWebBluetooth 호환: 연결 성공 후 index.js 에서 호출. 시리얼 경로에서는 부가 처리 없음.
    setConnectDevice(/* device */) {
        // noop
    }

    setDisconnectDevice(/* device */) {
        this._devices = {};
    }

    // ========== 내부 헬퍼 ==========

    _buildRequestPortOptions() {
        const filters = [];
        if (
            this._peripheralOptions &&
            Array.isArray(this._peripheralOptions.filters)
        ) {
            for (const f of this._peripheralOptions.filters) {
                // navigator.serial.requestPort 는 { usbVendorId, usbProductId } 만 허용
                const filt = {};
                if (typeof f.usbVendorId === "number") {
                    filt.usbVendorId = f.usbVendorId;
                }
                if (typeof f.usbProductId === "number") {
                    filt.usbProductId = f.usbProductId;
                }
                if (Object.keys(filt).length > 0) {
                    filters.push(filt);
                }
            }
        }
        if (filters.length === 0) {
            // 필터 없으면 모든 시리얼 장치를 보여줌
            return {};
        }
        return { filters };
    }

    _handlePortPicked(port) {
        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
            this._discoverTimeoutID = null;
        }

        if (this._stopScan === 1) {
            return;
        }

        if (this._runtime.SCANNING_DEVICE != this._extensionId) {
            return;
        }

        let info = {};
        try {
            info = port.getInfo() || {};
        } catch (_) {
            info = {};
        }
        const vid =
            typeof info.usbVendorId === "number"
                ? info.usbVendorId.toString(16).padStart(4, "0")
                : "xxxx";
        const pid =
            typeof info.usbProductId === "number"
                ? info.usbProductId.toString(16).padStart(4, "0")
                : "xxxx";

        // SerialPort 는 영속 id 가 없다. 세션 범위 내에서 유일한 합성 id 를 생성.
        const peripheralId = `serial-${vid}-${pid}`;
        let displayName;
        if (this._type === 0) {
            displayName = `Kamibot Pi (USB ${vid}:${pid})`;
        } else if (this._type === 1) {
            displayName = `BitBlock MINI (USB ${vid}:${pid})`;
        } else {
            displayName = `Serial (USB ${vid}:${pid})`;
        }

        const peripheral = {
            name: displayName,
            rssi: -50,
            peripheralId: peripheralId,
            id: peripheralId,
            mac: "",
            isConnected: false,
            index: -1,
        };

        this._availablePeripherals[peripheralId] = peripheral;
        this._devices[peripheralId] = peripheral;
        this._btDevices[peripheralId] = port;

        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_LIST_UPDATE,
            this._availablePeripherals
        );
    }

    _startReadLoop() {
        if (!this._port || !this._port.readable) {
            console.warn("[serialWebSerial] readable stream unavailable");
            return;
        }
        // 공유 SerialPort 객체에 이전 세션의 leaked reader 락이 남아 있으면 새 reader 를
        // 얻을 수 없다. 조용히 얼어붙는 대신 연결 문제로 표면화한다(정상 close 라면 발생 안 함).
        if (this._port.readable.locked) {
            console.warn(
                "[serialWebSerial] readable stream already locked — 이전 세션 락 잔존, 재-arm 불가"
            );
            this.handleDisconnectError(
                new Error("serial readable stream already locked")
            );
            return;
        }

        // read loop 종료 신호용 프라미스(_closePort 가 await).
        let doneResolve;
        this._readLoopDone = new Promise((resolve) => {
            doneResolve = resolve;
        });
        this._readLoopStopped = false;

        try {
            this._reader = this._port.readable.getReader();
        } catch (err) {
            console.error(
                "[serialWebSerial] getReader 실패:",
                err && err.message
            );
            this._readLoopStopped = true;
            doneResolve();
            this.handleDisconnectError(err);
            return;
        }

        // reader 락 해제 + 정리를 한 곳에서 처리하고 _readLoopDone 을 resolve.
        const finish = () => {
            this._readLoopStopped = true;
            try {
                if (this._reader) this._reader.releaseLock();
            } catch (_) {}
            this._reader = null;
            doneResolve();
        };

        const pump = () => {
            if (!this._reader) {
                doneResolve();
                return;
            }
            this._reader
                .read()
                .then(({ value, done }) => {
                    if (done) {
                        finish();
                        // 스트림이 닫혔는데 우리가 연결 중이라고 믿고 있으면(의도치 않은 종료)
                        // 연결 끊김으로 표면화한다. 의도적 disconnect 는 이미 _connected=false 라
                        // handleDisconnectError 가 내부에서 즉시 early-return(멱등).
                        this.handleDisconnectError(
                            new Error("serial read stream closed")
                        );
                        return;
                    }
                    if (value && value.byteLength > 0) {
                        this._onIncomingBytes(value);
                    }
                    pump();
                })
                .catch((err) => {
                    finish();
                    // cancel(AbortError) 로 종료된 경우는 의도적 disconnect 이므로 정상.
                    // 그 외 read 오류(USB 히컵/버퍼 오버런 등)는 루프가 죽은 것이므로
                    // 조용히 방치하지 않고 연결 끊김으로 표면화한다.
                    if (err && err.name !== "AbortError") {
                        console.warn(
                            "[serialWebSerial] read loop error:",
                            err && err.message
                        );
                        this.handleDisconnectError(err);
                    }
                });
        };
        pump();
    }

    // 수신 바이트를 누적 버퍼에 붙이고 20바이트 Kamibot 패킷 단위로 분할 후 콜백 호출.
    // 경계가 틀어지면 START(0x41) 마커까지 버리고 재동기화한다.
    _onIncomingBytes(chunk) {
        const combined = new Uint8Array(
            this._rxBuffer.byteLength + chunk.byteLength
        );
        combined.set(this._rxBuffer, 0);
        combined.set(chunk, this._rxBuffer.byteLength);
        this._rxBuffer = combined;

        while (this._rxBuffer.byteLength >= KAMIBOT_PACKET_SIZE) {
            if (this._rxBuffer[0] !== KAMIBOT_START_BYTE) {
                // 재동기화: 다음 START 마커까지 버림. 없으면 전체 폐기.
                let syncAt = -1;
                for (let i = 1; i < this._rxBuffer.byteLength; i++) {
                    if (this._rxBuffer[i] === KAMIBOT_START_BYTE) {
                        syncAt = i;
                        break;
                    }
                }
                if (syncAt === -1) {
                    this._rxBuffer = new Uint8Array(0);
                    return;
                }
                this._rxBuffer = this._rxBuffer.slice(syncAt);
                continue;
            }

            if (
                this._rxBuffer[KAMIBOT_PACKET_SIZE - 1] !== KAMIBOT_END_BYTE
            ) {
                // END 마커 불일치 → 이 START 는 가짜. 1바이트 전진 후 재시도
                this._rxBuffer = this._rxBuffer.slice(1);
                continue;
            }

            const packet = this._rxBuffer.slice(0, KAMIBOT_PACKET_SIZE);
            this._rxBuffer = this._rxBuffer.slice(KAMIBOT_PACKET_SIZE);

            if (this._characteristicDidChangeCallback) {
                const base64 = Base64Util.uint8ArrayToBase64(packet);
                try {
                    this._characteristicDidChangeCallback(base64);
                } catch (err) {
                    console.warn(
                        "[serialWebSerial] onChanged callback threw:",
                        err && err.message
                    );
                }
            }
        }
    }

    // 락-세이프·결정적 정리: reader 취소 → read loop 종료(releaseLock) 대기 →
    // writer close+releaseLock → 리스너 제거 → port.close. 순서를 보장해야 공유
    // SerialPort 객체에 stuck 락/half-open 이 남지 않는다(다음 세션 getReader/open 실패 방지).
    _closePort() {
        const port = this._port;
        this._port = null;

        // 1) reader 취소. pump 의 catch(AbortError) 가 releaseLock 후 _readLoopDone 을 resolve.
        let readerDone = Promise.resolve();
        if (this._reader) {
            try {
                this._reader.cancel().catch(() => {});
            } catch (_) {}
            readerDone = this._readLoopDone || Promise.resolve();
        }

        return readerDone
            .catch(() => {})
            .then(() => {
                // 예외 경로로 락이 남아 있으면 마지막으로 한 번 더 해제 시도.
                if (this._reader) {
                    try {
                        this._reader.releaseLock();
                    } catch (_) {}
                    this._reader = null;
                }
                this._readLoopDone = null;

                // 2) writer: close 완료를 기다린 뒤 releaseLock(진행 중 releaseLock 은 throw).
                let writerDone = Promise.resolve();
                if (this._writer) {
                    const w = this._writer;
                    this._writer = null;
                    writerDone = Promise.resolve()
                        .then(() => w.close())
                        .catch(() => {})
                        .then(() => {
                            try {
                                w.releaseLock();
                            } catch (_) {}
                        });
                }
                return writerDone.catch(() => {});
            })
            .then(() => {
                if (!port) return;
                // 3) disconnect 리스너 제거.
                if (this._disconnectHandler) {
                    try {
                        port.removeEventListener(
                            "disconnect",
                            this._disconnectHandler
                        );
                    } catch (_) {}
                    this._disconnectHandler = null;
                }
                // 4) reader/writer 락이 모두 풀린 뒤라야 port.close 가 안전하다.
                return port.close().catch((err) => {
                    console.warn(
                        "[serialWebSerial] port.close 실패:",
                        err && err.message
                    );
                });
            });
    }

    _handlePortDisconnected(id /* , event */) {
        console.warn(
            `[serialWebSerial] port disconnect 이벤트 id=${id} connected=${this._connected}`
        );
        if (!this._connected) return;
        this._connected = false;

        // 물리 뽑힘/링크 손실 시에도 reader/writer 락을 확실히 해제하고 포트를 닫는다.
        // (공유 SerialPort 객체에 stuck 락이 남아 다음 세션 getReader/open 이 실패하는 것을 방지)
        this._closePort().catch((err) => {
            console.warn(
                "[serialWebSerial] disconnect(event) close error:",
                err && err.message
            );
        });
        this._connectId = null;

        if (this._resetCallback) {
            this._resetCallback(id);
        }
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_CONNECTION_LOST_ERROR,
            {
                message: "Scratch lost connection to",
                extensionId: this._extensionId,
            }
        );
    }

    handleDisconnectError(err) {
        console.warn(
            `[serialWebSerial] handleDisconnectError connected=${this._connected}`,
            err && err.name,
            err && err.message
        );
        if (!this._connected) return;
        if (this._resetCallback) {
            this._resetCallback(this._connectId);
        }
        this.disconnect();
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_CONNECTION_LOST_ERROR,
            {
                message: "Scratch lost connection to",
                extensionId: this._extensionId,
            }
        );
    }

    _handleOperationError(err, operation) {
        if (!err) return;
        const msg = (err && err.message) || String(err);
        const disconnected =
            !this._connected ||
            /port is closed/i.test(msg) ||
            /not connected/i.test(msg) ||
            /device has been lost/i.test(msg);

        if (disconnected) {
            this.handleDisconnectError(err);
            return;
        }
        console.warn(
            `[serialWebSerial] ${operation} error (연결 유지):`,
            (err && err.name) || err,
            msg
        );
    }

    _handleRequestError(/* err */) {
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_REQUEST_ERROR,
            {
                message: "Scratch lost connection to",
                extensionId: this._extensionId,
            }
        );
    }

    _handleDiscoverTimeout() {
        this._stopScan = 1;
        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
            this._discoverTimeoutID = null;
        }
        this._runtime.emit(this._runtime.constructor.PERIPHERAL_SCAN_TIMEOUT);
    }
}

module.exports = SERIALWEBSERIAL;
