    whenReceived(args) {
        if (!this.when_received) {
            return false;
        }

        if (this.label != args.LABEL) {
            return false;
        }
        // setTimeout(() => {
        //     this.when_received = false;
        // }, HAT_TIMEOUT);
        return true;
    }

    isReceived(args) {
        if (!this.when_received) {
            return false;
        }

        if (this.label != args.LABEL) {
            return false;
        }
        return true;
    }

    async createClassSprite(args) {
        const name = Cast.toString(args.LABEL);
        const sprite = this.runtime.getSpriteTargetByName(name);
        if (sprite) {
            // 스프라이트가 존재하면, 포함되어있는 코스튬을 데이터로 사용한다.
            const cnt = sprite.getCostumeCount();
            if (cnt == 1) {
                return;
            }
            this.counts[name] = cnt;
            sprite.firsttime = cnt;
            this.when_received_arr[name] = false;
            return;
        }

        const emptyItem = emptySprite(name, name, name);
        const vm = this.runtime.vm;
        try {
            await vm.addSprite(JSON.stringify(emptyItem));
        } catch (e) {
            console.error(e);
            // 실패하면 이후 "이미지 추가"가 모두 실패하므로, 로그 말하기 설정과 관계없이 알린다.
            const target = this.runtime.targets[1];
            if (target) {
                this.runtime.emit("SAY", target, "say", Message.say_class_create_failed[this.locale].replace("{name}", name));
            }
        }
    }

    addExample(args, util) {
        if (this.finishTraining) {
            this.targetSay(Message.say_cannot_add_trained[this.locale]);
            return;
        }

        const label = args.LABEL;
        console.log(`{addImage} label=${label}`);
        console.log(
            `{addImage} typeof =${typeof this.when_received_arr[label]}`
        );

        if (typeof this.when_received_arr[label] == "undefined") {
            console.log(`{addExample} add label receive => ${label}`);

            this.when_received_arr[label] = false;
        }

        const originalCanvas = this.runtime.renderer._gl.canvas;
        const frame = this._getFrame(
            originalCanvas.width,
            originalCanvas.height
        );

        console.log(`{addImage} FRAME : `, frame);
        if (!frame) {
            return "Camera error!";
        }

        // 코스츔에 추가
        const ret = this._addCostume(util, frame, label);
        if (!ret) {
            return "error";
        }
        // this._updateCounts(label);
        console.log(`{ ${label} }에 사진 추가 ${this.getCountByLabel({ LABEL: label })}`);
        this.targetSay(Message.say_image_added[this.locale].replace("{label}", label).replace("{count}", this.getCountByLabel({ LABEL: label })));

        return new Promise((resolve) => {
            setTimeout(() => {
                resolve();
            }, 100);
        });
    }

    // async _createURLSkin(frame) {
    //     const output = new Image();
    //     output.src = URL;
    //     output.crossOrigin = "anonymous";
    //     await output.decode();
    //     return renderer.createBitmapSkin(output);
