    setAvailablePeripheralsCb(peripheral, isUpdate, onUpdate) {
        if (onUpdate === true) {
            this._runtime.emit(
                this._runtime.constructor.PERIPHERAL_LIST_UPDATE,
                this._availablePeripherals
            );
        } else if (peripheral === undefined) {
            this._availablePeripherals = {};
        } else {
            // 0 kamibot //1 Sensor block //2 input block //3 output block //4 active block //5 iot block //6 application block
            // log.debug('👣 {setAvailablePeripheralsCb}', this._type);

            switch (this._type) {
                case 0: {
                    if (!peripheral.name.toLowerCase().startsWith("kami")) {
                        log.debug(
                            "NO KamiBot peripheral.name = " + peripheral.name
                        );
                        return;
                    }
                    break;
                }
                case 1: {
                    if (!peripheral.name.toLowerCase().startsWith("bitb")) {
                        log.debug(
                            "NO...BitBlock peripheral.name = " + peripheral.name
                        );
                        return;
                    }
                    break;
                }
                default: {
                    log.debug(
                        "I dont konow What type BLE -> this._type = " +
                            this._type
                    );
                }
            }

            // log.debug('1 => ', this._availablePeripherals);
            // ks.moon 현재 연결 로봇 이름에 표시하기
            // const deviceName = peripheral.name + (peripheral.isConnected ? '✔' : '');

            let mac = peripheral.peripheralId.toString(16).toUpperCase();
            log.error("@@@ mac address ->", mac);

            //80:65:99:D2:16:59
            //806599D21659
            // 세미콜론 없애기
            if (mac.indexOf(":") > 0) {
                mac = mac.replace(/:/g, "");
            }

            if (peripheral.name.toLowerCase().startsWith("bitblock")) {
                peripheral.name = "BitBlock MINI";
            }

            // rssi값 양수로 만들려고 100에서 더함.
            // let peripheralName = `BitBlock MINI (${mac.substr(8, 2)}:${mac.substr(10, 2)}, ${100 + params.rssi})`;
            let peripheralName = `${peripheral.name} (${mac.substr(
                8,
                2
            )}:${mac.substr(10, 2)})`;

            // OK peripheral
            // console.log('♥️♥️♥️ peripheral :', peripheral);
            let params = {
                // name : peripheral.name,
                name: peripheralName,
                rssi: peripheral.rssi,
                peripheralId: peripheral.peripheralId,
                isConnected: peripheral.isConnected,
                index: peripheral.index,
            };

            if (params) {
                if (params.peripheralId) {
                    if (Object.keys(this._availablePeripherals).length > 0) {
                        log.debug(
                            "💄 여러개 비트블록 =>",
                            this._availablePeripherals[
                                Object.keys(this._availablePeripherals)[0]
                            ].rssi,
                            " ? ",
                            params.rssi
                        );

                        // ks.moon - 0dBm에 가까울수록 신호가 강함
                        if (
                            this._availablePeripherals[
                                Object.keys(this._availablePeripherals)[0]
                            ].rssi < params.rssi
                        ) {
                            this._availablePeripherals = {};
                            this._availablePeripherals[params.peripheralId] =
                                params;
                        }
                    } else {
                        log.debug("💄 ONLY 비트블록 =>");
                        this._availablePeripherals[params.peripheralId] =
                            params;
                    }
                }
            }

            log.debug(
                "*************************************************************"
            );
            log.debug(
                "*** ✅✅✅ 연결할 디바이스  => ",
                this._availablePeripherals
            );
            log.debug(
                "*************************************************************"
            );

            if (isUpdate === true) {
                log.debug("💄 업데이트 ...........###");
                log.debug("💄 업데이트 ...........###");
                log.debug("💄 업데이트 ...........###");
                log.debug("💄 업데이트 ...........###");

                let device = {
                    name: peripheral.name,
                    rssi: peripheral.rssi,
                    // id : peripheral.peripheralId, ks.moon 연결 후 아이콘이 안변화는 문제가 있어서...
                    peripheralId: peripheral.peripheralId,
                    isConnected: false,
                    index: -1,
                };

                if (device) {
                    if (device.peripheralId) {
                        // this._devices[device.id] = device; // ks.moon 위의 아이콘이 안 변하는 문제 해결을 위해서..
                        this._devices[device.peripheralId] = device;
                    }
                }

                this._runtime.emit(
                    this._runtime.constructor.PERIPHERAL_LIST_UPDATE,
                    this._availablePeripherals
                );
            }
        }
    }

