    setServiceUUID(service1, service2, rxCh, txCh) {
        this._connectServiceID1 = service1;
        this._connectServiceID2 = service2;
        this._connectTxCharacteristicID = txCh;
        this._connectRxCharacteristicID = rxCh;
    }

    setServiceCharacteristic(service, rx, tx) {
        this._connectService = service;
        this._connectRxCharacteristic = rx;
        this._connectTxCharacteristic = tx;

        if (service.uuid.toLowerCase() === this._connectServiceID1) {
            this._useServiceID = 0;
        } else {
            this._useServiceID = 1;
        }
    }

    processConnect(address) {
        // log.debug("ble processConnect");

        let runtimeLet = this._runtime;
        let connectCallbackLet = this._connectCallback;
        let disconnectCallbackLet = this._disconnectCallback;

        //let connectIdLet = this._connectedId;
        let extensionIdLet = this._extensionId;

        let rxLet = this._connectRxCharacteristicID;
        let txLet = this._connectTxCharacteristicID;
        let serviceID1Let = this._connectServiceID1;
        let serviceID2Let = this._connectServiceID2;

        let service = {};
        let rxCh = {};
        let txCh = {};

        if (
            this._runtime.isMobile.Android() ||
            this._runtime.isMobile.iOS()
        ) {
            ble.connect(
                address,
                function (peripheralData) {
                    //log.debug('ble peripheralData:' + JSON.stringify(peripheralData));

                    var len = peripheralData.characteristics.length;
                    for (var i = 0; i < len; i++) {
                        //log.debug('ble peripheralData.characteristics[i].characteristic:' + peripheralData.characteristics[i].characteristic);
                        if (
                            peripheralData.characteristics[
                                i
                            ].characteristic.toLowerCase() === rxLet
                        ) {
                            rxCh.uuid = rxLet;
                        } else if (
                            peripheralData.characteristics[
                                i
                            ].characteristic.toLowerCase() === txLet
                        ) {
                            txCh.uuid = txLet;
                        }
                    }

                    var len = peripheralData.services.length;
                    for (var i = 0; i < len; i++) {
                        if (
                            peripheralData.services[i].toLowerCase() ===
                            serviceID1Let
                        ) {
                            service.uuid = serviceID1Let;
                        } else if (
                            peripheralData.services[i].toLowerCase() ===
                            serviceID2Let
                        ) {
                            service.uuid = serviceID2Let;
                        }
                    }
                    connectCallbackLet(address, service, rxCh, txCh);

                    setTimeout(() => {
                        runtimeLet.emit(
                            runtimeLet.constructor.PERIPHERAL_CONNECTED,
                            address
                        );
                    }, 100);
                },
                function () {
                    log.error("연결 실패! address:", address);
                    disconnectCallbackLet(address);

                    setTimeout(() => {
                        runtimeLet.emit(
                            runtimeLet.constructor.PERIPHERAL_DISCONNECTED,
                            address
                        );
                        runtimeLet.emit(
                            runtimeLet.constructor.PERIPHERAL_REQUEST_ERROR,
                            {
                                message: `Scratch lost connection to`,
                                extensionId: extensionIdLet,
                            }
                        );
                    }, 100);
                }
            );
        }
    }

    //ks.moon 디바이스 연결 화면에서 연결 버튼을 누르면 이곳이 실행이 되네...
    connectPeripheral(id) {
        let deviceLet = this._devices[id];

        // ks.moon OK peripheralId
        // log.info('{connectPeripheral} 디바이스 연결 id : ', id);
        // log.info('{connectPeripheral} deviceLet : ', deviceLet);

        if (this._discoverTimeoutID) {
            window.clearTimeout(this._discoverTimeoutID);

            ble.stopScan(
                function () {
                    this.processConnect(deviceLet.peripheralId);
                }.bind(this),
                function () {
                    //log.debug("ble stopScan failed");
                }
            );
        } else {
            // this.processConnect(deviceLet.id);
            this.processConnect(deviceLet.peripheralId);
        }
    }

    /**
     * Close the websocket.
     */
    disconnect(address) {
        console.log(
            "✅ @@@ {bleBitblock.js}-{disconnect} BLE disconnect: _connected = " +
                this._connected +
                " _connectId = " +
                this._connectedId
        );

        let deviceAddressLet = address;
        let disconnectCallbackLet = this._disconnectCallback;
        let runtimeLet = this._runtime;

        if (this._connected) {
            this._connected = false;
        }

        ble.disconnect(
            address,
            function () {
                //log.debug("ble disconnect success");
                disconnectCallbackLet(deviceAddressLet);
                setTimeout(() => {
                    runtimeLet.emit(
                        runtimeLet.constructor.PERIPHERAL_DISCONNECTED,
                        deviceAddressLet
                    );
                }, 100);
            },
            function () {
                //log.debug("ble disconnect fail");
                disconnectCallbackLet(deviceAddressLet);
                setTimeout(() => {
                    runtimeLet.emit(
                        runtimeLet.constructor.PERIPHERAL_DISCONNECTED,
                        deviceAddressLet
                    );
                }, 100);
            }
        );

        if (this._discoverTimeoutID) {
            window.clearTimeout(this._discoverTimeoutID);
        }
    }

