import bindAll from 'lodash.bindall';
import PropTypes from 'prop-types';
import React from 'react';
import {defineMessages, injectIntl, intlShape} from 'react-intl';
import {connect} from 'react-redux';
import VM from 'scratch-vm';
import {projectTitleInitialState} from '../reducers/project-title';
import downloadBlob from '../lib/download-blob';
import createBlocksPdf from '../lib/block-pdf';
import log from '../lib/log';

const messages = defineMessages({
    stage: {
        defaultMessage: 'Stage',
        description: 'Label for the stage in the stage selector',
        id: 'gui.stageSelector.stage'
    },
    noBlocks: {
        defaultMessage: 'There are no blocks to export.',
        description: 'Alert shown when exporting a PDF of a project without any blocks',
        id: 'gui.menuBar.exportPdfNoBlocks'
    },
    failed: {
        defaultMessage: 'Could not export the PDF.',
        description: 'Alert shown when exporting the blocks as a PDF fails',
        id: 'gui.menuBar.exportPdfFailed'
    }
});

/**
 * Passes a function to its child that downloads the block programs of the stage and every
 * sprite as a PDF, one sprite per page.
 *
 * <BlocksPdfDownloader>{(className, downloadPdf) => (
 *     <MyCoolComponent
 *         onClick={downloadPdf}
 *     />
 * )}</BlocksPdfDownloader>
 */
class BlocksPdfDownloader extends React.Component {
    constructor (props) {
        super(props);
        bindAll(this, [
            'downloadPdf'
        ]);
        this.exporting = false;
    }
    downloadPdf () {
        if (this.exporting) return;
        this.exporting = true;
        document.body.style.cursor = 'wait';

        const {intl} = this.props;
        // Let the menu close before the blocks are rendered, which blocks the page briefly.
        setTimeout(() => {
            Promise.resolve()
                .then(() => createBlocksPdf(this.props.vm, intl.formatMessage(messages.stage)))
                .then(pdf => {
                    if (pdf) {
                        downloadBlob(this.props.pdfFilename, pdf);
                    } else {
                        alert(intl.formatMessage(messages.noBlocks)); // eslint-disable-line no-alert
                    }
                })
                .catch(err => {
                    log.error(err);
                    alert(intl.formatMessage(messages.failed)); // eslint-disable-line no-alert
                })
                .then(() => {
                    this.exporting = false;
                    document.body.style.cursor = '';
                });
        }, 50);
    }

    render () {
        const {
            children
        } = this.props;
        return children(
            this.props.className,
            this.downloadPdf
        );
    }
}

const getPdfFilename = (curTitle, defaultTitle) => {
    let filenameTitle = curTitle;
    if (!filenameTitle || filenameTitle.length === 0) {
        filenameTitle = defaultTitle;
    }
    return `${filenameTitle.substring(0, 100)}.pdf`;
};

BlocksPdfDownloader.propTypes = {
    children: PropTypes.func,
    className: PropTypes.string,
    intl: intlShape.isRequired,
    pdfFilename: PropTypes.string,
    vm: PropTypes.instanceOf(VM).isRequired
};
BlocksPdfDownloader.defaultProps = {
    className: ''
};

const mapStateToProps = state => ({
    vm: state.scratchGui.vm,
    pdfFilename: getPdfFilename(state.scratchGui.projectTitle, projectTitleInitialState)
});

export default injectIntl(connect(
    mapStateToProps,
    () => ({}) // omit dispatch prop
)(BlocksPdfDownloader));
