import bindAll from "lodash.bindall";
import VM from "scratch-vm";
import PropTypes from "prop-types";
import React from "react";
import { injectIntl, intlShape, defineMessages } from "react-intl";

// import decksLibraryContent from '../lib/libraries/decks/index.jsx';
import tutorialTags from "../lib/libraries/tutorial-tags";

// import analytics from '../lib/analytics';

import TableComponent from "../components/table/table.jsx";

import { connect } from "react-redux";

import { closeTableLibrary } from "../reducers/modals";

// import {
//     activateDeck
// } from '../reducers/cards';

const messages = defineMessages({
    tableLibraryTitle: {
        defaultMessage: "View a Data-Table",
        description: "View a Data-Table",
        id: "gui.tableLibrary.tutorials",
    },
});

class TableLibrary extends React.PureComponent {
    constructor(props) {
        super(props);
        bindAll(this, ["handleItemSelect"]);
    }

    componentDidMount() {
        // 이벤트 핸들러 등록
        // console.error("@@@@@@@@@ TABLE-LIBRARY DIDMOUNT :");
        this.props.vm.on("TABLEDATA_UPDATE", this.handleItemSelect);
    }

    componentWillUnmount() {
        // 이벤트 핸들러 해제
        // console.error("🏆@@@@@@@@@ TABLE-LIBRARY UNMOUNT :");
        this.props.vm.removeListener("TABLEDATA_UPDATE", this.handleItemSelect);
    }

    handleItemSelect(data) {
        // console.error("🐹🐹🐹 {table-library.jsx}-{handleItemSelect}");
    }

    render() {
        console.error("TABLE-LIBRARY vm: ", this.props.vm);
        const tableData = this.props.vm.getTableLibraryData("table");

        console.error("☘️☘️☘️{table-library} TABLE-DATA :", tableData);
        console.error("☘️☘️☘️{table-library} typeof :", typeof tableData);

        let headers = [];
        let dataBody = [];
        let chartType = null;
        if (tableData.length > 2) {
            headers = tableData[0];
            dataBody = tableData[1];
            chartType = tableData[2];
        }

        if (!this.props.visible) return null;

        // let chartElement = ();
        // if (chartType == "dataclassification") {
        // }

        return (
            <TableComponent
                filterable
                headers={headers}
                data={dataBody}
                id="tableLibrary"
                tags={tutorialTags}
                title={this.props.intl.formatMessage(
                    messages.tableLibraryTitle
                )}
                visible={this.props.visible}
                chartType={chartType}
                onItemSelected={this.handleItemSelect}
                onRequestClose={this.props.onRequestClose}
            />
        );
    }
}

TableLibrary.propTypes = {
    intl: intlShape.isRequired,
    // onActivateDeck: PropTypes.func.isRequired,
    onRequestClose: PropTypes.func,
    projectId: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    visible: PropTypes.bool,
    vm: PropTypes.instanceOf(VM).isRequired,
};

const mapStateToProps = (state) => ({
    visible: state.scratchGui.modals.tableLibrary,
    projectId: state.scratchGui.projectState.projectId,
});

const mapDispatchToProps = (dispatch) => ({
    // onActivateDeck: id => dispatch(activateDeck(id)),
    onRequestClose: () => dispatch(closeTableLibrary()),
});

export default injectIntl(
    connect(mapStateToProps, mapDispatchToProps)(TableLibrary)
);
