/* eslint-disable */
const Runtime = require("../../engine/runtime");
const ArgumentType = require("../../extension-support/argument-type");
const BlockType = require("../../extension-support/block-type");
const Cast = require("../../util/cast");
const Video = require("../../io/video");
const formatMessage = require("format-message");

const LOGTAG = "*** PROJECT_DOWNLOAD ***";

// eslint-disable-next-line max-len
const blockIconURI =
    "data:image/png;base64,";

const {LOCALES: AvailableLocales, withFallback} = require("../common/l10n");
const Message = withFallback({
    extName: { ko: "프로젝트", en: "Project" },
    load_project: { ko: "프로젝트를 [URL]에서 불러오기", en: "load project from [URL]" },
});

class Scratch3ProjectBlocks {
    constructor(runtime) {
        this.runtime = runtime;
    } // constructor

    get EXTENSION_ID() {
        return "project";
    }

    get ONOFF_MENU() {
        return [
            {
                text: formatMessage({
                    id: "extension.menu.on",
                    default: "ON",
                    description: "ON",
                }),
                value: "1",
            },
            {
                text: formatMessage({
                    id: "extension.menu.off",
                    default: "OFF",
                    description: "OFF",
                }),
                value: "0",
            },
        ];
    }

    /**
     * 빨간 멈추기 버튼이 눌러졌을 때
     * @private.
     */
    PROJECT_STOP_ALL() {
        console.log(`{*** PROJECT_STOP_ALL ***}`);
        if (this.detectInteval) {
            clearInterval(this.detectInteval);
            this.detectInteval = null;
        }
        this.clearResult();
    }

    /**
     * 녹색 깃발 버튼이 눌러졌을 때
     * @private
     */
    startProject() {
        console.log(`{*** PROJECT_START ***}`);
    }

    _setLocale() {
        const locale = formatMessage.setup().locale;
        return AvailableLocales.includes(locale) ? locale : "en";
    }

    getInfo() {
        this.locale = this._setLocale();
        if (this.firstInstall) {
            this.firstInstall = false;
        }

        return {
            id: "project",
            name: Message.extName[this.locale],
            blockIconURI: blockIconURI,
            blocks: [
                {
                    opcode: "downloadProject",
                    blockType: BlockType.COMMAND,
                    text: Message.load_project[this.locale],
                    arguments: {
                        URL: {
                            type: ArgumentType.STRING,
                            defaultValue: "https://weniv.link/sn9Elr",
                        },
                    },
                },
            ],
            menus: {},
        };
    }

    _loadProject(url) {
        const vm = this.runtime.vm;
        console.error("VM :", vm);

        fetch(url)
            .then((r) => r.arrayBuffer())
            .then((buffer) => vm.loadProject(buffer))
            .then(() => {
                console.log("Done");
                // vm.greenFlag();
            })
            .catch((error) => {
                console.log("Error", error);
            });
    }

    async downloadProject(args, utils) {
        console.error("프로젝트 불러오기........");
        await this._loadProject("https://weniv.link/Fm8UeK");
    }

    toggleDebug(args) {
        this.enableLog = false;
        if (args.LOG_STATE === "1") {
            this.enableLog = true;
        }
    }

    _sleep(ms) {
        return new Promise((resolve) => setTimeout(resolve, ms));
    }

    targetSay(message) {
        if (!this.enableLog) {
            return;
        }

        const target = this.runtime.targets[1];
        if (target) {
            this.runtime.emit("SAY", this.runtime.targets[1], "say", message);
        }

        setTimeout(() => {
            if (target) {
                this.runtime.emit("SAY", this.runtime.targets[1], "say", "");
            }
        }, 1000);
    }
}

module.exports = Scratch3ProjectBlocks;
