class Scratch3TMSoundBlocks {
    constructor(runtime) {
        this.locale = this._setLocale();
        this.runtime = runtime;
        this.initialize();

        // recognizer 조작(start/stop/load/initialize)을 순서대로 실행하는 직렬 큐.
        // speech-commands의 listen()/stopListening()은 비동기(getUserMedia, AudioContext.close)라서
        // 이 큐 밖에서는 isListening()을 믿을 수 없다.
        this._queue = Promise.resolve();

        if (this.runtime.ioDevices) {
            this.runtime.on(Runtime.PROJECT_STOP_ALL, this.PROJECT_STOP_ALL.bind(this));
        }
    } // constructor

    initialize() {
        this.enableLog = true;
        this.recognizer = null;
        this.wordLabels = [];
        this.soundProbableLabels = [];
        this.intervalSec = 1;
        this.resultTimeout = null;
    }

    get EXTENSION_ID() {
        return "tmsound";
    }

    get ONOFF_MENU() {
        return [
            {
                text: formatMessage({
                    id: "extension.menu.on",
                    default: "ON",
                    description: "ON",
                }),
                value: "1",
            },
            {
                text: formatMessage({
                    id: "extension.menu.off",
                    default: "OFF",
                    description: "OFF",
                }),
                value: "0",
            },
        ];
    }

    /**
     * 빨간 멈추기 버튼이 눌러졌을 때 (녹색 깃발도 먼저 stopAll을 호출한다)
     * @private.
     */
    PROJECT_STOP_ALL() {
        console.debug(`{*** PROJECT_STOP_ALL ***}`);
        this.stopListening();
    }

    _setLocale() {
        const locale = formatMessage.setup().locale;
        return AvailableLocales.includes(locale) ? locale : "en";
    }

    getInfo() {
        this.locale = this._setLocale();
        return {
            id: "tmsound",
            name: Message.extName[this.locale],
            blockIconURI: blockIconURI,
            blocks: [
                {
                    opcode: "setSoundClassificationModelURL",
                    text: Message.loadModel[this.locale],
                    blockType: BlockType.COMMAND,
                    arguments: {
                        URL: {
                            type: ArgumentType.STRING,
                            defaultValue: "ATthvXSkt",
                        },
                    },
                },
                {
                    opcode: "toggleSoundClassification",
                    text: Message.toggleClassify[this.locale],
                    blockType: BlockType.COMMAND,
                    arguments: {
                        ONOFF: {
                            type: ArgumentType.STRING,
                            menu: "onoff",
                            defaultValue: "1",
                        },
                    },
                },
                {
                    opcode: "setSoundClassificationInterval",
                    text: Message.setInterval[this.locale],
                    blockType: BlockType.COMMAND,
                    arguments: {
                        CLASSIFICATION_INTERVAL: {
                            type: ArgumentType.STRING,
                            menu: "classification_interval_menu",
                            defaultValue: "1",
                        },
                    },
                },
                "---",
                {
                    opcode: "whenReceivedSoundLabel",
                    text: Message.whenSound[this.locale],
                    blockType: BlockType.HAT,
                    arguments: {
                        LABEL: {
                            type: ArgumentType.STRING,
                            menu: "sound_labels_menu",
                            defaultValue: ANY_LABEL,
                        },
                    },
                },
                {
                    opcode: "isSoundLabelDetected",
                    text: Message.isSound[this.locale],
                    blockType: BlockType.BOOLEAN,
                    arguments: {
                        LABEL: {
                            type: ArgumentType.STRING,
                            menu: "sound_labels_menu",
                            defaultValue: ANY_LABEL,
                        },
                    },
                },
                {
                    opcode: "getSoundLabel",
                    text: Message.soundLabel[this.locale],
                    blockType: BlockType.REPORTER,
                },
                {
                    opcode: "soundLabelConfidence",
                    text: Message.soundConfidence[this.locale],
                    blockType: BlockType.REPORTER,
                    disableMonitor: true,
                    arguments: {
                        LABEL: {
                            type: ArgumentType.STRING,
                            menu: "sound_labels_without_any_menu",
                            defaultValue: "",
                        },
                    },
                },
                "---",
                {
                    opcode: "initializeModel",
                    text: Message.resetModel[this.locale],
                    blockType: BlockType.COMMAND,
                },
                "---",
                {
                    opcode: "blockLine",
                    text: "[SEPARATOR_TEXT][SEPARATOR_IMAGE]",
                    arguments: {
                        SEPARATOR_TEXT: {
                            type: ArgumentType.STRING,
                            defaultValue: Message.sepDebug[this.locale],
                        },
                        SEPARATOR_IMAGE: {
                            type: ArgumentType.STRING,
                            defaultValue: "bitblock_block_icon.png",
                        },
                    },
                },
                {
                    opcode: "toggleDebug",
                    blockType: BlockType.COMMAND,
                    text: Message.toggleDebug[this.locale],
                    arguments: {
                        ONOFF_STATE: {
                            type: ArgumentType.NUMBER,
                            menu: "onoff",
                            defaultValue: 0,
                        },
                    },
                },
            ],
            menus: {
                sound_labels_menu: {
                    acceptReporters: true,
                    items: "getSoundLabelsMenu",
                },
                sound_labels_without_any_menu: {
                    acceptReporters: true,
                    items: "getSoundLabelsWithoutAnyMenu",
                },
                classification_interval_menu: {
                    acceptReporters: true,
                    items: [
                        { text: "1", value: "1" },
                        { text: "0.5", value: "0.5" },
                        { text: "0.2", value: "0.2" },
                        { text: "0.1", value: "0.1" },
                    ],
                },
                onoff: {
                    items: this.ONOFF_MENU,
                },
            },
        };
    }

    // --------------------------------------------------------------------------------
    // 메뉴
    // --------------------------------------------------------------------------------
    _labelsWithoutBackground() {
        return this.wordLabels.filter((label) => label !== BACKGROUND_NOISE);
    }

    getSoundLabelsMenu() {
        return [{ text: Message.anyLabel[this.locale], value: ANY_LABEL }, ...this._labelsWithoutBackground()];
    }

    getSoundLabelsWithoutAnyMenu() {
        return ["", ...this._labelsWithoutBackground()];
    }

    // --------------------------------------------------------------------------------
    // recognizer 제어 (모두 직렬 큐를 통과)
    // --------------------------------------------------------------------------------
    // 이전 작업이 완전히 끝난 뒤 fn을 실행한다. fn이 실패해도 큐는 계속 산다.
    _enqueue(fn) {
        this._queue = this._queue.then(fn).catch((err) => console.error(LOGTAG, err));
        return this._queue;
    }

    // 큐 안에서만 호출. 결과를 비우고, 스트리밍 중이면 마이크까지 해제한다.
    _stopNow() {
        clearTimeout(this.resultTimeout);
        this.soundProbableLabels = [];
        if (this.recognizer && this.recognizer.isListening()) {
            return this.recognizer.stopListening();
        }
    }

    setSoundClassificationModelURL(args) {
        return this.loadSoundClassificationModelFromURL(args.URL);
    }

    loadSoundClassificationModelFromURL(url) {
        const target = this.runtime.targets[1];
        if (target) {
            this.runtime.emit("SAY", target, "say", Message.sayDownloading[this.locale]);
        }

        return this._enqueue(() =>
            Promise.resolve(this._stopNow())
                .then(() => applyTfjsBackend(LOGTAG))
                .then(() => {
                    // 입력 형식: 모델 id("VQ9dhejr9"), 티처블머신 공유 링크(".../models/<id>/"),
                    // 또는 model.json이 있는 폴더의 https 직접 링크
                    url = Cast.toString(url).trim();
                    const shared = url.match(/\/models\/([^/]+)/);
                    if (shared) {
                        url = shared[1];
                    }
                    if (!url.startsWith("https://")) {
                        url = `https://storage.googleapis.com/tm-model/${url}/`;
                    } else if (!url.endsWith("/")) {
                        url = `${url}/`;
                    }
                    const modelURL = `${url}model.json?noCache=${new Date().getTime()}`;
                    const metadataURL = `${url}metadata.json?noCache=${new Date().getTime()}`;
                    console.log(LOGTAG, "modelURL :", modelURL);

                    // speechCommands는 <script> 태그로 읽어들임 (scratch-gui/src/playground/index.ejs)
                    const recognizer = speechCommands.create("BROWSER_FFT", undefined, modelURL, metadataURL);
                    return recognizer.ensureModelLoaded().then(() => {
                        // 이전 모델의 텐서를 해제한다 (재로딩 시 GPU 메모리 누적 방지).
                        if (this.recognizer && this.recognizer.model) {
                            this.recognizer.model.dispose();
                        }
                        this.recognizer = recognizer;
                        this.wordLabels = recognizer.wordLabels();
                        console.log(LOGTAG, "레이블이름:", this.wordLabels);
                        this.targetSay(Message.sayDownloaded[this.locale]);
                    });
                })
                .catch((error) => {
                    console.error(LOGTAG, error);
                    this.targetSay(Message.sayDownloadFailed[this.locale]);
                })
        );
    }

    startListening() {
        return this._enqueue(() => {
            if (!this.recognizer) {
                this.targetSay(Message.sayLoadFirst[this.locale]);
                return;
            }
            if (this.recognizer.isListening()) {
                return;
            }
            this.targetSay(Message.sayOn[this.locale]);
            return this.recognizer
                .listen(
                    (result) => {
                        // result.scores는 wordLabels()와 같은 순서
                        const scores = Array.from(result.scores);
                        this.soundProbableLabels = this.wordLabels.map((label, i) => ({
                            label: label,
                            confidence: scores[i],
                        }));
                        if (this.enableLog) {
                            console.log(LOGTAG, this.getSoundLabel());
                        }
                        // 같은 레이블이 연속 인식돼도 해트 블록이 매번 발화하도록 엣지 상태 리셋
                        const hatOpcode = `${this.EXTENSION_ID}_whenReceivedSoundLabel`;
                        this.runtime.allScriptsByOpcodeDo(hatOpcode, (script, target) => {
                            target.updateEdgeActivatedValue(script.blockId, false);
                        });
                        clearTimeout(this.resultTimeout);
                        this.resultTimeout = setTimeout(() => {
                            this.soundProbableLabels = [];
                        }, this.intervalSec * 1000);
                    },
                    {
                        probabilityThreshold: 0.7,
                    }
                )
                .catch((error) => {
                    console.error(LOGTAG, error);
                    this.targetSay(Message.sayNoMic[this.locale]);
                });
        });
    }

    stopListening() {
        return this._enqueue(() => this._stopNow());
    }

    // --------------------------------------------------------------------------------
    // 블록
    // --------------------------------------------------------------------------------
    toggleSoundClassification(args) {
        if (args.ONOFF === "1" || args.ONOFF === 1) {
            return this.startListening();
        }
        this.targetSay(Message.sayOff[this.locale]);
        return this.stopListening();
    }

    setSoundClassificationInterval(args) {
        // 0, 음수, NaN이면 결과가 즉시 지워져 인식이 조용히 죽으므로 기본값으로 되돌린다.
        const sec = Cast.toNumber(args.CLASSIFICATION_INTERVAL);
        this.intervalSec = sec > 0 ? sec : 1;
    }

    whenReceivedSoundLabel(args) {
        return this.isSoundLabelDetected(args);
    }

    isSoundLabelDetected(args) {
        const label = this.getSoundLabel();
        if (label === "") {
            return false;
        }
        if (args.LABEL === ANY_LABEL) {
            return true;
        }
        return label === args.LABEL;
    }

    getSoundLabel() {
        if (this.soundProbableLabels.length === 0) {
            return "";
        }
        let mostOne = this.soundProbableLabels[0];
        this.soundProbableLabels.forEach((clss) => {
            if (clss.confidence > mostOne.confidence) {
                mostOne = clss;
            }
        });
        return mostOne.label;
    }

    soundLabelConfidence(args) {
        if (args.LABEL === "") {
            return 0;
        }
        const found = this.soundProbableLabels.find((clss) => clss.label === args.LABEL);
        return found ? found.confidence * 100 : 0;
    }

    initializeModel() {
        return this._enqueue(() =>
            Promise.resolve(this._stopNow()).then(() => {
                this.initialize();
                this.targetSay(Message.sayReset[this.locale]);
            })
        );
    }

    toggleDebug(args) {
        this.enableLog = false;
        if (args.ONOFF_STATE === "1") {
            this.enableLog = true;
        }
    }

    targetSay(message) {
        if (!this.enableLog) {
            return;
        }

        const target = this.runtime.targets[1];
        if (target) {
            this.runtime.emit("SAY", this.runtime.targets[1], "say", message);
        }

        setTimeout(() => {
            if (target) {
                this.runtime.emit("SAY", this.runtime.targets[1], "say", "");
            }
        }, 1000);
    }
}

module.exports = Scratch3TMSoundBlocks;
