import bindAll from 'lodash.bindall';
import PropTypes from 'prop-types';
import React from 'react';
import {defineMessages, injectIntl, intlShape} from 'react-intl';
import {connect} from 'react-redux';

import LoadFromUrlModalComponent from '../components/load-from-url-modal/load-from-url-modal.jsx';
import {closeLoadFromUrlModal} from '../reducers/modals';
import sharedMessages from '../lib/shared-messages';

const messages = defineMessages({
    invalidUrl: {
        id: 'gui.loadFromUrlModal.invalidUrl',
        defaultMessage: 'Please enter a valid URL.',
        description: 'Error shown when the URL input is not a valid URL'
    }
});

class LoadFromUrlModal extends React.Component {
    constructor (props) {
        super(props);
        bindAll(this, [
            'handleChangeUrl',
            'handleCancel',
            'handleLoad',
            'handleKeyDown'
        ]);
        this.state = {
            url: '',
            errorMessage: '',
            isLoading: false
        };
    }

    isValidUrl (value) {
        try {
            const parsed = new URL(value);
            return parsed.protocol === 'http:' || parsed.protocol === 'https:';
        } catch (e) {
            return false;
        }
    }

    handleChangeUrl (e) {
        this.setState({url: e.target.value, errorMessage: ''});
    }

    handleCancel () {
        if (this.state.isLoading) return;
        this.props.onCloseModal();
    }

    handleLoad () {
        const {intl, onLoadFromUrl, projectChanged, userOwnsProject} = this.props;
        const url = this.state.url.trim();
        if (!this.isValidUrl(url)) {
            this.setState({errorMessage: intl.formatMessage(messages.invalidUrl)});
            return;
        }

        if (userOwnsProject || projectChanged) {
            const confirmed = window.confirm( // eslint-disable-line no-alert
                intl.formatMessage(sharedMessages.replaceProjectWarning)
            );
            if (!confirmed) return;
        }

        this.setState({isLoading: true, errorMessage: ''});
        Promise.resolve()
            .then(() => onLoadFromUrl(url))
            .then(() => {
                this.setState({isLoading: false, url: ''});
                this.props.onCloseModal();
            })
            .catch(err => {
                this.setState({
                    isLoading: false,
                    errorMessage: (err && err.message) || String(err)
                });
            });
    }

    handleKeyDown (e) {
        if (e.key === 'Enter') {
            e.preventDefault();
            this.handleLoad();
        } else if (e.key === 'Escape') {
            this.handleCancel();
        }
    }

    render () {
        return (
            <LoadFromUrlModalComponent
                errorMessage={this.state.errorMessage}
                isLoading={this.state.isLoading}
                url={this.state.url}
                onCancel={this.handleCancel}
                onChangeUrl={this.handleChangeUrl}
                onKeyDown={this.handleKeyDown}
                onLoad={this.handleLoad}
            />
        );
    }
}

LoadFromUrlModal.propTypes = {
    intl: intlShape.isRequired,
    onCloseModal: PropTypes.func.isRequired,
    onLoadFromUrl: PropTypes.func.isRequired,
    projectChanged: PropTypes.bool,
    userOwnsProject: PropTypes.bool
};

const mapStateToProps = state => ({
    projectChanged: state.scratchGui.projectChanged,
    userOwnsProject: true
});

const mapDispatchToProps = dispatch => ({
    onCloseModal: () => dispatch(closeLoadFromUrlModal())
});

export default injectIntl(
    connect(mapStateToProps, mapDispatchToProps)(LoadFromUrlModal)
);
