/**
 * AI 처리 장치(GPU/CPU) 설정. AI 확장 전체가 공통으로 쓴다.
 *  - MediaPipe Tasks: handsdetect, facemp, posemp, facemesh (util/vision-task-client.js)
 *  - TensorFlow.js:   tmimage, tmpose, tmsound, imageproject, icimage, faceapi (util/tfjs-backend.js)
 * GUI의 고급 설정 창(scratch-gui/src/components/advanced-settings-modal)도 이 모듈을 그대로 import 한다.
 *
 * 설정은 기기별이므로 프로젝트가 아니라 localStorage에 둔다.
 *  - bitblock.ai.delegate                   : 'auto' | 'gpu' | 'cpu'  (사용자 설정, 모든 AI 확장 공통, 기본 'auto')
 *  - bitblock.ai.delegate.resolved.<engine> : 'auto'일 때 엔진별 GPU 자동 점검 결과 {delegate, reason, ua, at}
 *                                             ua(브라우저/WebView 버전)가 바뀌면 무효로 보고 다시 점검한다.
 *  - bitblock.ai.delegate.last.<engine>     : 엔진별로 마지막에 모델을 만든 장치 {delegate, source, at} (설정 창 표시용)
 * 자동 점검을 엔진별로 하는 이유: 같은 기기에서도 엔진마다 GPU 동작이 다르다.
 * (Adreno 830: MediaPipe GPU 추론은 "검출 없음"만 반환하지만 TensorFlow.js WebGL은 정상)
 */
const SETTING_KEY = 'bitblock.ai.delegate';
const RESOLVED_KEY = 'bitblock.ai.delegate.resolved';
const LAST_KEY = 'bitblock.ai.delegate.last';

const Delegate = {
    AUTO: 'auto',
    GPU: 'gpu',
    CPU: 'cpu'
};

const Engine = {
    MEDIAPIPE: 'mediapipe',
    TFJS: 'tfjs'
};

const readJson = key => {
    try {
        const raw = window.localStorage.getItem(key);
        return raw ? JSON.parse(raw) : null;
    } catch (e) {
        return null;
    }
};

const writeJson = (key, value) => {
    try {
        window.localStorage.setItem(key, JSON.stringify(value));
    } catch (e) {
        // localStorage를 쓸 수 없는 환경에서는 저장 없이 동작한다.
    }
};

const removeKey = key => {
    try {
        window.localStorage.removeItem(key);
    } catch (e) {
        // localStorage를 쓸 수 없는 환경
    }
};

class AiDelegateSetting {
    static get Delegate () {
        return Delegate;
    }

    static get Engine () {
        return Engine;
    }

    /**
     * @return {string} 'auto' | 'gpu' | 'cpu'
     */
    static getSetting () {
        let value = null;
        try {
            value = window.localStorage.getItem(SETTING_KEY);
        } catch (e) {
            // 기본값 사용
        }
        return value === Delegate.GPU || value === Delegate.CPU ? value : Delegate.AUTO;
    }

    /**
     * @param {string} value 'auto' | 'gpu' | 'cpu'
     */
    static setSetting (value) {
        try {
            window.localStorage.setItem(SETTING_KEY, value);
        } catch (e) {
            // 저장할 수 없는 환경
        }
    }

    /**
     * 엔진의 자동 점검 결과. 현재 브라우저(WebView) 버전에서 점검한 것이 아니면 null.
     * @param {string} engine 'mediapipe' | 'tfjs'
     * @return {?{delegate: string, reason: string, ua: string, at: number}}
     */
    static getResolved (engine) {
        const resolved = readJson(`${RESOLVED_KEY}.${engine}`);
        if (!resolved || resolved.ua !== navigator.userAgent) return null;
        if (resolved.delegate !== Delegate.GPU && resolved.delegate !== Delegate.CPU) return null;
        return resolved;
    }

    static setResolved (engine, delegate, reason) {
        writeJson(`${RESOLVED_KEY}.${engine}`, {delegate, reason, ua: navigator.userAgent, at: Date.now()});
    }

    /** 모든 엔진의 자동 점검 결과를 지워 다음 모델 로딩 때 다시 점검하게 한다. */
    static clearResolved () {
        Object.values(Engine).forEach(engine => removeKey(`${RESOLVED_KEY}.${engine}`));
    }

    /**
     * @param {string} engine 'mediapipe' | 'tfjs'
     * @return {?{delegate: string, source: string, at: number}}
     */
    static getLast (engine) {
        return readJson(`${LAST_KEY}.${engine}`);
    }

    /**
     * @param {string} engine 'mediapipe' | 'tfjs'
     * @param {string} delegate 'gpu' | 'cpu'
     * @param {string} source 'setting' | 'auto' | 'auto-cached' | 'auto-fallback'
     */
    static setLast (engine, delegate, source) {
        writeJson(`${LAST_KEY}.${engine}`, {delegate, source, at: Date.now()});
    }
}

module.exports = AiDelegateSetting;
