/**
 * 데이터 수집(기록) 도우미 — 데이터 분류 / 데이터 예측 확장이 함께 쓴다.
 *
 * 스크래치 리스트를 학습 데이터 형식으로 다룬다.
 *   첫 항목  : 열 이름  "왼쪽,오른쪽,행동"
 *   이후 항목: 한 행    "512,130,좌회전"   (마지막 열이 라벨/결과값)
 * useDataFromList 가 이 형식을 그대로 읽는다.
 *
 * 리스트를 바꾸는 함수는 list._monitorUpToDate = false 까지 처리하고 {ok, error, ...} 를 돌려준다.
 * 오류 문구는 describeError 로 만든다.
 */
const ArgumentType = require('../extension-support/argument-type');
const BlockType = require('../extension-support/block-type');

// 스크래치 기본 리스트 블록과 같은 한도 (src/blocks/scratch3_data.js)
const LIST_ITEM_LIMIT = 200000;

const flattenDeep = value => {
    if (!Array.isArray(value)) return [value];
    return value.reduce((acc, item) => acc.concat(flattenDeep(item)), []);
};

const isEmpty = value => value === null || typeof value === 'undefined';

// 셀 하나: 문자열로 바꾸고, 셀 안의 쉼표는 공백으로(형식 보호)
const cleanCell = value => (isEmpty(value) ? '' : String(value)).replace(/,/g, ' ')
    .trim();

/**
 * 블록에 들어온 값을 셀 배열로 바꾼다.
 * "1,2" / [1, 2] / [["1,2"], 3] / 5 를 모두 받는다. 쉼표는 어디에 있든 구분자로 본다.
 * @param {*} value 블록 인자
 * @return {Array.<string>} 셀 배열 (값이 비어 있으면 빈 배열)
 */
const normalizeCells = value => {
    const parts = [];
    flattenDeep(value).forEach(item => {
        String(isEmpty(item) ? '' : item).split(',')
            .forEach(part => parts.push(part.trim()));
    });
    if (parts.length === 1 && parts[0] === '') return [];
    return parts;
};

// 리스트 항목 하나 → 셀 배열 (항목이 숫자이거나 배열이어도 처리)
const rowToCells = item => {
    if (Array.isArray(item)) return flattenDeep(item).map(cell => cleanCell(cell));
    return String(isEmpty(item) ? '' : item).split(',')
        .map(cell => cell.trim());
};

const markChanged = list => {
    list._monitorUpToDate = false;
};

const readHeader = list => {
    if (list.value.length === 0) return null;
    return rowToCells(list.value[0]);
};

const sameCells = (a, b) => a.length === b.length && a.every((cell, i) => cell === b[i]);

const isNumeric = text => text !== '' && isFinite(Number(text));

/**
 * 열 이름 줄을 준비한다.
 * 빈 리스트 → 열 이름을 넣는다 / 같은 열 이름 → 그대로 둔다(이어서 수집) / 그 밖 → 바꾸지 않고 오류.
 * @param {object} list 스크래치 리스트 변수
 * @param {*} columnsText "왼쪽,오른쪽,행동"
 * @return {object} {ok, created} 또는 {ok:false, error}
 */
const prepareHeader = (list, columnsText) => {
    const columns = normalizeCells(columnsText);
    if (columns.length < 2) return {ok: false, error: 'NEED_TWO_COLUMNS'};
    if (columns.some(name => name === '')) return {ok: false, error: 'EMPTY_COLUMN'};
    if (columns.some(name => isNumeric(name))) return {ok: false, error: 'NUMERIC_COLUMN'};
    if (new Set(columns).size !== columns.length) return {ok: false, error: 'DUPLICATE_COLUMN'};

    if (list.value.length === 0) {
        list.value.push(columns.join(','));
        markChanged(list);
        return {ok: true, created: true};
    }
    if (sameCells(readHeader(list), columns)) return {ok: true, created: false};
    return {ok: false, error: 'HEADER_MISMATCH'};
};

/**
 * 한 행을 기록한다. 마지막 열은 라벨(결과값).
 * @param {object} list 스크래치 리스트 변수
 * @param {*} values 입력값들 ("1,2" 또는 값 묶음 리포터 결과)
 * @param {*} label 라벨(결과값)
 * @return {object} {ok} 또는 {ok:false, error, expected, got}
 */
const appendRow = (list, values, label) => {
    const header = readHeader(list);
    if (!header) return {ok: false, error: 'NO_HEADER'};

    const cells = normalizeCells(values);
    const labelCell = cleanCell(Array.isArray(label) ? flattenDeep(label).join(' ') : label);
    if (labelCell === '') return {ok: false, error: 'EMPTY_LABEL'};
    if (cells.length !== header.length - 1) {
        return {ok: false, error: 'COLUMN_COUNT', expected: header.length - 1, got: cells.length};
    }
    if (cells.some(cell => cell === '')) return {ok: false, error: 'EMPTY_VALUE'};
    if (list.value.length >= LIST_ITEM_LIMIT) return {ok: false, error: 'LIST_FULL'};

    list.value.push(cells.concat(labelCell).join(','));
    markChanged(list);
    return {ok: true};
};

/**
 * 마지막 기록 한 줄을 지운다. 열 이름 줄은 남긴다.
 * @param {object} list 스크래치 리스트 변수
 * @return {object} {ok} 또는 {ok:false, error}
 */
const removeLastRow = list => {
    if (list.value.length <= 1) return {ok: false, error: 'NO_ROWS'};
    list.value.pop();
    markChanged(list);
    return {ok: true};
};

const countRows = list => Math.max(0, list.value.length - 1);

const labelOf = item => {
    const cells = rowToCells(item);
    return cells[cells.length - 1];
};

const countLabel = (list, label) => {
    const target = cleanCell(label);
    let count = 0;
    for (let i = 1; i < list.value.length; i++) {
        if (labelOf(list.value[i]) === target) count++;
    }
    return count;
};

// 모니터가 매 프레임 부르므로, 리스트가 그대로면 이전 결과를 쓴다.
const summaryCache = new WeakMap();

/**
 * 라벨별 개수 "직진:30, 좌회전:12" (처음 나온 순서).
 * @param {object} list 스크래치 리스트 변수
 * @return {string} 요약 문자열
 */
const labelSummary = list => {
    const length = list.value.length;
    const last = length > 0 ? String(list.value[length - 1]) : '';
    const cached = summaryCache.get(list);
    if (cached && cached.value === list.value && cached.length === length && cached.last === last) {
        return cached.text;
    }
    const counts = new Map();
    for (let i = 1; i < length; i++) {
        const label = labelOf(list.value[i]);
        counts.set(label, (counts.get(label) || 0) + 1);
    }
    const text = Array.from(counts, ([label, count]) => `${label}:${count}`).join(', ');
    summaryCache.set(list, {value: list.value, length, last, text});
    return text;
};

const toCsv = list => list.value.map(item => rowToCells(item).join(','))
    .join('\r\n');

/**
 * CSV 텍스트를 파일로 내려받게 한다. (엑셀에서 한글이 깨지지 않도록 BOM 포함)
 * @param {string} name 파일 이름(확장자 제외)
 * @param {string} text CSV 내용
 */
const downloadCsv = (name, text) => {
    if (typeof document === 'undefined') return;
    const safeName = (String(name).replace(/[\\/:*?"<>|]/g, '_')
        .trim() || 'data');
    const BOM = String.fromCharCode(0xFEFF);
    const blob = new Blob([BOM + text], {type: 'text/csv;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${safeName}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
};

