/**
 * 오류 결과를 사용자 문구로 바꾼다.
 * @param {object} result {error, expected, got}
 * @param {string} locale 'ko' | 'en'
 * @return {string} 문구
 */
const describeError = (result, locale) => {
    const entry = ERROR_MESSAGES[result.error];
    if (!entry) return String(result.error);
    return (entry[locale] || entry.en)
        .replace('{expected}', result.expected)
        .replace('{got}', result.got);
};

/**
 * "수집" 구역 블록 정의를 만든다. 두 확장이 문구만 바꿔 쓴다.
 * @param {object} texts 블록 문구와 기본값
 * @param {object} opts {summary: 라벨별 개수 블록 포함 여부}
 * @return {Array} getInfo().blocks 에 펼쳐 넣을 정의들
 */
const buildRecorderBlocks = (texts, opts = {}) => {
    const listArg = {type: ArgumentType.STRING, menu: 'lists'};
    const blocks = [
        '---',
        {
            opcode: 'blockLine',
            text: '[SEPARATOR_TEXT][SEPARATOR_IMAGE]',
            arguments: {
                SEPARATOR_TEXT: {type: ArgumentType.STRING, defaultValue: texts.separator},
                SEPARATOR_IMAGE: {type: ArgumentType.STRING, defaultValue: 'bitblock_block_icon.png'}
            }
        },
        {
            opcode: 'recordPrepare',
            blockType: BlockType.COMMAND,
            text: texts.prepare,
            arguments: {
                LIST: listArg,
                COLUMNS: {type: ArgumentType.STRING, defaultValue: texts.defaultColumns}
            }
        },
        {
            opcode: 'recordRow',
            blockType: BlockType.COMMAND,
            text: texts.row,
            arguments: {
                LIST: listArg,
                VALUES: {type: ArgumentType.STRING, defaultValue: texts.defaultValues},
                LABEL: {type: ArgumentType.STRING, defaultValue: texts.defaultLabel}
            }
        },
        {
            opcode: 'recordUndo',
            blockType: BlockType.COMMAND,
            text: texts.undo,
            arguments: {LIST: listArg}
        },
        {
            opcode: 'recordCount',
            blockType: BlockType.REPORTER,
            text: texts.count,
            arguments: {LIST: listArg}
        },
        {
            opcode: 'recordLabelCount',
            blockType: BlockType.REPORTER,
            text: texts.labelCount,
            arguments: {
                LIST: listArg,
                LABEL: {type: ArgumentType.STRING, defaultValue: texts.defaultLabel}
            }
        }
    ];
    if (opts.summary) {
        blocks.push({
            opcode: 'recordSummary',
            blockType: BlockType.REPORTER,
            text: texts.summary,
            arguments: {LIST: listArg}
        });
    }
    blocks.push({
        opcode: 'recordSaveCsv',
        blockType: BlockType.COMMAND,
        text: texts.saveCsv,
        arguments: {LIST: listArg}
    });
    return blocks;
};

