import getUserMedia from "get-user-media-promise";

// Single Setup For All Video Streams used by the GUI
// While VideoProvider uses a private _singleSetup
// property to ensure that each instance of a VideoProvider
// use the same setup, this ensures that all instances
// of VideoProviders use a single stream. This way, closing a camera modal
// does not affect the video on the stage, and a program running and disabling
// video on the stage will not affect the camera modal's video.
const requestStack = [];

let cameraIndex = 0;
let deviceId = null;
let modelName = null;

const getInputList = async () => {
    if (navigator.mediaDevices) {
        return (await navigator.mediaDevices.enumerateDevices()) || [];
    }
    return [];
};

const checkPermission = async () => {
    await navigator.permissions
        .query({ name: "camera" })
        .then(async (permission) => {
            // console.log('camera state->', permission.state);
            if (permission.state !== "granted") {
                await navigator.mediaDevices.getUserMedia({
                    audio: false,
                    video: true,
                });
            }
        })
        .catch(async (error) => {
            console.error("Got error :", error);
        });
};

const changeCamera = (idx) => {
    console.log("[gui camera.js]", "idx : ", idx);
    cameraIndex = idx;
};

const getDeviceID = async () => {
    await checkPermission();
    const inputList = await getInputList();

    const videoInputList = inputList
        .filter((input) => input.kind === "videoinput")
        .map((item) => [item.label, item.deviceId]);

    let deviceId = videoInputList[cameraIndex][1];
    return deviceId;
};

const getModelName = () => {
    return modelName;
};

