    _processReportPacket(packet) {
        this._sensors.switch = [packet[2], packet[3]];

        // 5, 6
        let al = packet[4]; // low byte
        let ah = packet[5]; // hight byte
        const light1 = (ah << 8) | al;

        // 6, 7
        al = packet[6];
        ah = packet[7];
        const light2 = (ah << 8) | al;

        this._sensors.lightSensor = [light1, light2];

        // 8, 9
        al = packet[8];
        ah = packet[9];
        const touch0 = (ah << 8) | al;

        // 10, 11
        al = packet[10];
        ah = packet[11];
        const touch1 = (ah << 8) | al;

        // 12, 13
        al = packet[12];
        ah = packet[13];
        const touch2 = (ah << 8) | al;

        this._sensors.touchSensor = [touch0, touch1, touch2];

        //  uint8_t v = (uint8_t)((_tl << 3) | (_tr << 2) | (_tu << 1) | _td);
        const p = packet[14];
        //  tl = (p >> 3 & 0x01);
        //  tr = (p >> 2 & 0x01);
        //  tu = (p >> 1 & 0x01);
        //  td = (p & 0x01);
        this._sensors.mpuSensor = [
            (p >> 3) & 0x01,
            (p >> 2) & 0x01,
            (p >> 1) & 0x01,
            p & 0x01,
        ];

        // 15, 16
        al = packet[15];
        ah = packet[16];
        this._sensors.mic = (ah << 8) | al;
    }

    _processReportPacket_2(packet) {
        this._sensors.switch = [packet[2], packet[3]];
        this._sensors.lightSensor = [packet[4], packet[5]];
        this._sensors.touchSensor = [packet[6], packet[7], packet[8]];

        let al = packet[9];
        let ah = packet[10];
        const angleX = (ah << 8) | al;

        al = packet[11];
        ah = packet[12];
        const angleY = (ah << 8) | al;

        //  uint8_t v = (uint8_t)((_tl << 3) | (_tr << 2) | (_tu << 1) | _td);
        const p = packet[13];
        //  tl = (p >> 3 & 0x01);
        //  tr = (p >> 2 & 0x01);
        //  tu = (p >> 1 & 0x01);
        //  td = (p & 0x01);
        this._sensors.mpuSensor = [
            (p >> 3) & 0x01,
            (p >> 2) & 0x01,
            (p >> 1) & 0x01,
            p & 0x01,
        ];

        al = packet[14];
        ah = packet[15];
        this._sensors.mic = (ah << 8) | al;
    }

