    _onMessageError(errorCode) {
        if (typeof errorCode === "object") {
            errorCode = JSON.stringify(errorCode, null, "  ");
        }
    }

    _toHexString(byteArray) {
        return Array.from(byteArray, (byte) => {
            return ("0" + (byte & 0xff).toString(16)).slice(-2);
        }).join("");
    }

    /**
     * Process the sensor data from the incoming BLE characteristic.
     * ks.moon BLE 데이터가 들어오는데 계속 들어온다...
     * @param {object} base64 - the incoming BLE data.
     * @private
     */
    _onMessage(data) {
        // 센서 리포트 패킷 (0xff 0x66) - 자발적 스트림
        if (data[0] == 0xff && data[1] == 0x66) {
            this._processReportPacket(data);
            return;
        }

        // 응답 없음 명령(INDEX=0)은 무시
        if (data[BBRETURN.INDEX] == 0) {
            return;
        }

        // 20260417 Map 기반 응답 매칭
        const receivedIndex = data[BBRETURN.INDEX];
        if (this._pendingCommands.has(receivedIndex)) {
            this._receivedPacket = data.slice(); // Uint8Array native memcpy
            const cmd = this._pendingCommands.get(receivedIndex);
            this._pendingCommands.delete(receivedIndex);
            cmd.resolve(data);
        }
        // 알 수 없는 인덱스는 조용히 무시 (타임아웃으로 이미 해제됐을 수 있음)
    }
