/**
 * 비트블록과 연결되는 인터페이스를 가지고 있다. 만약 여러대가 연결되어도 BitblockMini의 인스턴스는 한개만 만들어서
 * BitblockBle 를 여러개 인스턴스를 관리한다.
 */
// 한개의 인스턴스를 만들어서, 내부적으로 여러대의 Bitblock보드를 관리한다.
class BitblockMini {
    /**
     * Construct a MicroBit communication object.
     * @param {Runtime} runtime - the Scratch 3.0 runtime
     * @param {string} extensionId - the id of the extension
     */
    constructor(runtime, extensionId) {
        this._runtime = runtime;
        this._runtime.on("PROJECT_STOP_ALL", this.stopAll.bind(this));
        this._runtime.on("PROJECT_START", this.startProject.bind(this));
        this._runtime.on("PROJECT_RUN_START", this.runStartProject.bind(this));
        this._runtime.on("PROJECT_RUN_STOP", this.runStopProject.bind(this));
        this._runtime.registerPeripheralExtension(extensionId, this);
        this._bitBlockList = new Array();

        this._extensionId = extensionId;
        this._timeoutID = null;
        this._searchTimeoutID = null;

        this._service;

        this._onConnect = this._onConnect.bind(this);
        this._onConnectLink = this._onConnectLink.bind(this);
        this._onDisconnect = this._onDisconnect.bind(this);
        this._onMessage = this._onMessage.bind(this);
        this._onMessageLink = this._onMessageLink.bind(this);

        this._onMessageError = this._onMessageError.bind(this);
        this._onSetAvailablePeripheralsCallback =
            this._onSetAvailablePeripheralsCallback.bind(this);

        // 연결된 보드의 갯수
        this._connectCount = 0;

        // 프로젝트가 실행중인지를 판단
        this._isRunProject = 0;

        this._ble = null;
    }

    startProject() {
        console.info(`@@@ [Bitblock] start Project`);
    }

    runStartProject() {
        this._isRunProject = 1;
    }

    runStopProject() {
        this._isRunProject = 0;
    }

    /**
     * Called by the runtime when user wants to scan for a peripheral.
     */
    scan() {
        this._runtime.SCANNING_DEVICE = "bbcon";

        const hasWebSerial =
            typeof navigator !== "undefined" && !!navigator.serial;

        const readTransportPref = () => {
            try {
                const v = window.localStorage.getItem(
                    "bitblock.transport.bbcon"
                );
                if (v === "webserial" || v === "webbluetooth") return v;
            } catch (_) { /* ignore */ }
            // 디폴트: 모바일이면 WebBluetooth, 그 외 WebSerial 가능하면 WebSerial
            return !this._runtime.isMobile.Mobile() && hasWebSerial
                ? "webserial"
                : "webbluetooth";
        };
        const preferredTransport = readTransportPref();
        const useWebSerial =
            preferredTransport === "webserial" && hasWebSerial;

        if (this._ble) {
            this._ble.disconnect();
        }

        const BBCON_BLE_TYPE = 1;

        if (useWebSerial) {
            this._ble = new SERIAL_webserial_bbcon(
                this._runtime,
                this._extensionId,
                {
                    filters: [
                        { usbVendorId: 0x0403, usbProductId: 0x6015 },
                    ],
                    baudRate: 57600,
                },
                this._onConnectLink,
                this._onDisconnect,
                BBCON_BLE_TYPE
            );
        } else {
            this._ble = new BLE_webbluetooth(
                this._runtime,
                this._extensionId,
                {
                    filters: [{ services: [BLEUUID.service2] }],
                },
                this._onConnectLink,
                this._onDisconnect,
                BBCON_BLE_TYPE
            );
        }
    }

    scanStop() {
        if (this._ble) {
            if (typeof this._ble.stopScan === "function") {
                this._ble.stopScan();
            } else if (typeof this._ble.scanStop === "function") {
                this._ble.scanStop();
            }
        }
    }

    connectForTimer(id) {
        if (!this._ble) return;
        const INDEX = 0;
        const STATE = 2;
        this._bitBlockList[0] = new BitblockBle(
            this._runtime,
            this,
            this._ble.getDevice(id),
            INDEX,
            STATE
        );
        this._ble.connectPeripheral(id);
    }

    connect(id) {
        if (!this._ble) return;
        if (this._bitBlockList.length > 0) {
            if (this._bitBlockList[0] !== undefined) {
                if (this._bitBlockList[0].getConnectState() === 0) {
                    this._bitBlockList[0] = new BitblockBle(
                        this._runtime,
                        this,
                        this._ble.getDevice(id),
                        0,
                        2
                    );
                } else if (this._bitBlockList[0].getConnectState() === 1) {
                    this._bitBlockList[0].stopAll();
                    this._bitBlockList[0].reset();
                    this._bitBlockList[0].disconnect(
                        this._bitBlockList[0]._connectDevice.peripheralId
                    );
                    window.setTimeout(() => this.connectForTimer(id), 500);
                    return;
                }
            } else {
                this._bitBlockList[0] = new BitblockBle(
                    this._runtime,
                    this,
                    this._ble.getDevice(id),
                    0,
                    2
                );
            }
        } else {
            this._bitBlockList[0] = new BitblockBle(
                this._runtime,
                this,
                this._ble.getDevice(id),
                0,
                2
            );
        }
        this._ble.connectPeripheral(id);
    }

    disconnect() {
        if (this._bitBlockList.length > 0) {
            const boardBle = this._bitBlockList[0];
            if (boardBle) {
                boardBle.stopAll();
                const address = boardBle._connectDevice && boardBle._connectDevice.peripheralId;
                boardBle.reset();
                if (address) boardBle.disconnect(address);
            }
        }
    }

    // 20190910 moonlight 블루투스 연결 리스트 --
    getPeripheralList() {
        return this._bitBlockList;
    }

    startSearchDevice(index) {
        const bitblockBle = this.getDevice(index);
        if (bitblockBle == null || bitblockBle == undefined) {
            console.error("🍍🍍🍍 디바이스가 null 또는 undefined 입니다.");
        }
        bitblockBle.startSearchDevice();
    }

    clearPeripheral() {
        if (this._bitBlockList.length > 0) {
            if (this._bitBlockList[0] !== undefined) {
                if (this._bitBlockList[0].isConnected() === true) {
                    // this.disconnect(this._bitBlockList[0]._connectDevice.id);
                    this.disconnect(
                        this._bitBlockList[0]._connectDevice.peripheralId
                    );
                }
            }
        }
    }

    clearAllPeripheral() {
        if (this._bitBlockList.length > 0) {
            if (this._bitBlockList[0] !== undefined) {
                if (this._bitBlockList[0].isConnected() === true) {
                    const address =
                        this._bitBlockList[0]._connectDevice.peripheralId;
                    this.disconnect(
                        this._bitBlockList[0]._connectDevice.peripheralId
                    );
                    this._ble.setDisconnectDevice(this._ble.getDevice(address));
                }
            }
        }
    }

    /**
     * Reset all the state and timeout/interval ids.
     */
    reset() {
        if (this._timeoutID) {
            window.clearTimeout(this._timeoutID);
            this._timeoutID = null;
        }
    }

    isConnected() {

        let connected = false;
        if (this._bitBlockList[0]) {
            if (this._bitBlockList[0]._connectDevice == null) {
                // 일단 비우고 다시 해보자..
                this._bitBlockList = new Array();
                return connected;
            }

            if (!this._bitBlockList[0]._connectDevice) {
                // 일단 비우고 다시 해보자..디버깅 중..
                this._bitBlockList = new Array();
                return connected;
            }

            const address = this._bitBlockList[0]._connectDevice.peripheralId;
            if (address == undefined) {
                return connected;
            }

            if (this._ble) {
                const bitblockBle = this.getBitblockBle(address);
                if (bitblockBle !== null) {
                    connected = bitblockBle.isConnected();
                }
            }
        }
        return connected;
    }

    isConnectedPeripherals() {
        let connected = false;
        if (this._ble) {
            for (let i = 0; i < this._bitBlockList.length; i++) {
                if (this._bitBlockList[i] !== undefined) {
                    connected = this._bitBlockList[i].isConnected();
                    if (connected === true) {
                        break;
                    }
                }
            }
        }
        return connected;
    }

    // ks.moon 보드에 데이터를 보내는 함수
    send(address, message) {
        const bitblockBle = this.getBitblockBle(address);
        if (bitblockBle !== undefined) {
            if (!bitblockBle.isConnected()) {
                return;
            }

            // ----------------------------------------------------------------------------------------------------
            // console.log('✨✨✨✨✨✨✨✨✨✨ SEND SET-- this._runtime.doing  message[BBRETURN.INDEX]->', message[BBRETURN.INDEX]);
            // // moon -> 데이터를 send할 때, true,  onMessage에서 false
            // // 0은 stopALL과 같은 다른 스레드에서 실행되어서 다른 블록을 실행 못시키게 할 수 도 있다.
            // // 이벤트 블록은 스레득가 달라서 플러그 설정의 타이밍이 어렵다...
            // if(message[BBRETURN.INDEX] != 0) {
            //     this._runtime.doing = true;
            // }
            // ----------------------------------------------------------------------------------------------------

            const data = Base64Util.uint8ArrayToBase64(message);
            this._ble.write(
                address,
                BLEUUID.service2,
                BLEUUID.txChar,
                data,
                "base64",
                true
            );
        }
    }

    _onConnect(address, service, rxCh, txCh) {
        const bitblockBle = this.getBitblockBle(address);
        if (bitblockBle !== undefined) {
            this._connectCount = this._connectCount + 1;
            this._ble.getDevice(address).isConnected = true;
            this._ble.getDevice(address).index = bitblockBle.getConnectIndex();

            bitblockBle.setConnect(true);
            bitblockBle.setConnectDevice(this._ble.getDevice(address));

            this._ble.setConnectDevice(this._ble.getDevice(address));
            this._ble.read(
                BLEUUID.service2,
                BLEUUID.rxChar,
                true,
                this._onMessage
            );
            window.setTimeout(() => bitblockBle.setNotification(), 1300);
        } else {
            this.disconnect(address);
        }
    }

    _onConnectLink(address) {
        const bitblockBle = this.getBitblockBle(address);
        if (bitblockBle !== undefined) {
            this._connectCount = this._connectCount + 1;
            this._ble.getDevice(address).isConnected = true;
            this._ble.getDevice(address).index = bitblockBle.getConnectIndex();

            bitblockBle.setConnect(true);
            bitblockBle.setConnectDevice(this._ble.getDevice(address));

            this._ble.setConnectDevice(this._ble.getDevice(address));

            //moon 20240320
            this.scanStop();
            this._ble.startNotifications(
                address,
                BLEUUID.service2,
                BLEUUID.rxChar,
                this._onMessageLink
            );
        } else {
            this.disconnect(address);
        }
    }

    _onDisconnect(address) {

        if (this._bitBlockList.length > 0) {
            this._ble.setDisconnectDevice(this._ble.getDevice(address));

            // 클리어
            this._bitBlockList = new Array();
        }
    }

    _onSetAvailablePeripheralsCallback(peripheral, isUpdate, onUpdate) {
        if (this._ble !== undefined) {
            this._ble.setAvailablePeripheralsCb(peripheral, isUpdate, onUpdate);
        }
    }

    stopAll() {
        for (let i = 0; i < this._bitBlockList.length; i++) {
            if (this._bitBlockList[i] !== undefined) {
                this._bitBlockList[i].stopAll();
            }
        }
    }

    setService(address, service, rx, tx) {
        this._service = service;
        this._ble.setServiceCharacteristic(service, rx, tx);

        let useServiceID;
        if (service.uuid.toLowerCase() === BLEUUID.service2) {
            useServiceID = 0;
        } else {
            useServiceID = 1;
        }

        const bitblockBle = this.getBitblockBle(address);
        if (bitblockBle !== undefined) {
            bitblockBle.setService(service, rx, tx, useServiceID);
        }
    }

    setPriorityHigh(address) {
        this._ble.setPriorityHigh(address);
    }

    _onMessageError(errorCode) {
        if (typeof errorCode === "object") {
            errorCode = JSON.stringify(errorCode, null, "  ");
        }
    }

    _toHexString(byteArray) {
        return Array.from(byteArray, function (byte) {
            return ("0" + (byte & 0xff).toString(16)).slice(-2);
        }).join("");
    }

    /**
     * Process the sensor data from the incoming BLE characteristic.
     */
    _onMessage(result, address) {
        const data = Base64Util.base64ToUint8Array(result);
        for (let i = 0; i < this._bitBlockList.length; i++) {
            if (this._bitBlockList[i] !== undefined) {
                if (this._bitBlockList[i]._connected === true) {
                    this._bitBlockList[i]._onMessage(data);
                    break;
                }
            }
        }
    }

    _onMessageLink(result) {
        const data = Base64Util.base64ToUint8Array(result);
        for (let i = 0; i < this._bitBlockList.length; i++) {
            if (this._bitBlockList[i] !== undefined) {
                if (this._bitBlockList[i]._connected === true) {
                    this._bitBlockList[i]._onMessage(data);
                    break;
                }
            }
        }
    }

    // 인덱스의 BitblockBle 인스턴스를 리턴한다. BitblockBle는 연결된 보드이다.
    getDevice(index) {
        if (index != 0) {
            console.error(
                "----------------------------------------------------------------"
            );
            console.error(
                "✅ {BitblockMini} getDevice(index) : index가 0이 아니면 에러!!!"
            );
            console.error(
                "----------------------------------------------------------------"
            );
            return null;
        }

        let bitblockBle = null;
        if (this._bitBlockList.length > 0) {
            if (
                this._bitBlockList[0] != undefined &&
                this._bitBlockList[0] != null
            ) {
                bitblockBle = this._bitBlockList[0];
            }
        }
        if (bitblockBle == null) {
            // console.error(`💃🏾💃🏾💃🏾 {BitblockMini > getDvice} getDevice 연결된 보드가 없습니다.`);
        }
        return bitblockBle;
    }

    getBitblockBle(address) {
        let bitblockBle = null;
        if (this._bitBlockList.length > 0) {
            bitblockBle = this._bitBlockList[0];
        }
        return bitblockBle;
    }

    getConnectCount() {
        return 1;
    }
}

