    matrix_block(args) {
        return args.MATRIX;
    }

    get_ledColor(args, util) {
        const color = args.COLOR;
        return color;
    }

    get_rgbColor(args, util) {
        let red = MathUtil.clamp(Cast.toNumber(args.RED), 0, 255);
        let green = MathUtil.clamp(Cast.toNumber(args.GREEN), 0, 255);
        let blue = MathUtil.clamp(Cast.toNumber(args.BLUE), 0, 255);

        red = red.toString(16).toUpperCase();
        green = green.toString(16).toUpperCase();
        blue = blue.toString(16).toUpperCase();

        if (red.length == 1) {
            red = "0" + red;
        }
        if (green.length == 1) {
            green = "0" + green;
        }
        if (blue.length == 1) {
            blue = "0" + blue;
        }

        return `#${red}${green}${blue}`;
    }

    get_randomColor(args, util) {
        const letters = "0123456789ABCDEF";
        let color = "#";
        for (let i = 0; i < 6; i++) {
            color += letters[Math.floor(Math.random() * 16)];
        }
        return color;
    }

    display_bright(args, util) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve();
        } else {
            // 0 ~ 100사이 값
            let bright = MathUtil.clamp(Cast.toNumber(args.BRIGHT), 0, 100);

            bitblock.display_bright(bright);
        }
    }

    // 비트블록 디스플레이를 한 색상으로 모두 켜기
    display_color(args, util) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve();
        } else {
            const r = parseInt(args.COLOR.substring(1, 3), 16);
            const g = parseInt(args.COLOR.substring(3, 5), 16);
            const b = parseInt(args.COLOR.substring(5, 7), 16);

            bitblock.display_color(args.COLOR);
        }
    }

    // 비트브록의 디스플레이에 심볼을 표시한다.
    display_symbol(args, util) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve();
        } else {
            const symbol = Cast.toString(args.MATRIX).replace(/\s/g, "");
            const binaryGroups = [];
            // 문자열을 groupSize로 나눈 후, 각 그룹을 2진수로 변환하여 배열에 추가합니다.
            for (let i = 0; i < symbol.length; i += 5) {
                let group = symbol.substring(i, i + 5);
                let binary = parseInt(group, 2);
                binaryGroups.push(binary);
            }

            bitblock.display_symbol(binaryGroups, args.COLOR);
        }
    }

    deleteExtraChar(symbol) {
        symbol = Cast.toString(symbol).replace(/\s/g, "");
        symbol = symbol.replace(/[^01]/g, ""); // 0과 1 이외의 글자 삭제
        return symbol;
    }

    display_bit_string(args, util) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);

        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve();
        } else {
            let str1 = this.deleteExtraChar(args.BITSTR_1);
            str1 = str1.length > 5 ? str1.substring(0, 5) : str1;

            let str2 = this.deleteExtraChar(args.BITSTR_2);
            str2 = str2.length > 5 ? str2.substring(0, 5) : str2;

            let str3 = this.deleteExtraChar(args.BITSTR_3);
            str3 = str3.length > 5 ? str3.substring(0, 5) : str3;

            let str4 = this.deleteExtraChar(args.BITSTR_4);
            str4 = str4.length > 5 ? str4.substring(0, 5) : str4;

            let str5 = this.deleteExtraChar(args.BITSTR_5);
            str5 = str5.length > 5 ? str5.substring(0, 5) : str5;

            // let symbol = `${args.BITSTR_1}${args.BITSTR_2}${args.BITSTR_3}${args.BITSTR_4}${args.BITSTR_5}`
            // symbol = Cast.toString(symbol).replace(/\s/g, '');
            // symbol = symbol.replace(/[^01]/g, ''); // 0과 1 이외의 글자 삭제

            let symbol = `${str1}${str2}${str3}${str4}${str5}`;

            if (symbol.length < 25) {
                var zerosToAdd = 25 - symbol.length;
                symbol = symbol + "0".repeat(zerosToAdd);
            }

            const binaryGroups = [];
            // 문자열을 groupSize로 나눈 후, 각 그룹을 2진수로 변환하여 배열에 추가합니다.
            for (let i = 0; i < symbol.length; i += 5) {
                let group = symbol.substring(i, i + 5);
                let binary = parseInt(group, 2);
                binaryGroups.push(binary);
            }

            bitblock.display_symbol(binaryGroups, args.COLOR);

        }
    }

