    display_char(args, util) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);

        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve();
        } else {
            let c = args.CHAR.replace(/[^A-Za-z]/g, "");
            if (c.length < 1) {
                this.display_clear();
                return;
            }
            c = c.charAt(0).toUpperCase();
            if (c < "A" || c > "Z") {
                this.display_clear();
                return;
            }

            bitblock.display_char(c, args.COLOR);
        }
    }

    display_num(args, util) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve();
        } else {
            let num = args.NUM;
            if (typeof num === "string") {
                if (num.replace(/[^0-9]/g, "").length == 0) {
                    this.display_clear();
                    return;
                }
                num = Number(num.replace(/[^0-9]/g, "") % 10);
            }
            if (num > 9) {
                this.display_clear();
                return;
            }

            bitblock.display_num(num, args.COLOR);
        }
    }

    display_value(args, util) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve();
        } else {
            let val = args.VALUE;
            if (typeof val === "number") {
                val = val.toString();
            }
            val = val.trim();
            //영문,숫자,콤마,스페이스 이외는 삭제
            val = val.replace(/[^A-Za-z0-9., ]/g, "");
            if (val.length == 0) {
                return;
            }

            const MAX_LEN = 4;
            if (val.length > MAX_LEN) {
                this._targetSay(Message.maxDisplayChars[this.locale].replace("{MAX}", MAX_LEN));
                val = val.substring(0, MAX_LEN); // 또는 str.substring(0, 10);
            }

            // val 문자열을 아스키코드 값으로 바꾼다.
            const arr = Array.from(val, (ch) => ch.charCodeAt(0));
            bitblock.display_value(arr, args.COLOR);
        }
    }

