    read_joystick(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve(0);
        } 
        return bitblock.read_joystic()
        .then(packet => {
            if (packet) {
                // 하드웨어가 보낸 패킷에서 값을 추출하는 부분입니다. 패킷 구조에 따라 인덱스와 비트 연산을 조정해야 할 수 있습니다.
                const x_axis = (packet[BBRETURN.DATA4] << 8) | packet[BBRETURN.DATA3];
                const y_axis = (packet[BBRETURN.DATA2] << 8) | packet[BBRETURN.DATA1];

                const centerX = 500;
                const centerY = 500;
                const deadZone = 150;
                const dx = x_axis - centerX;
                const dy = y_axis - centerY;

                if (Math.abs(dx) <= deadZone && Math.abs(dy) <= deadZone) {
                    return 0;
                } else {
                    if (Math.abs(dx) > Math.abs(dy)) {
                        // 수평 방향이 더 큰 경우
                        if (dx > 0) {
                            return 2; // 오른쪽
                        } else {
                            return 4; // 왼쪽
                        }
                    } else {
                        // 수직 방향이 더 큰 경우
                        if (dy < 0) {
                            return 1; // 위쪽 (y가 작을수록 위쪽)
                        } else {
                            return 3; // 아래쪽
                        }
                    }
                }
            }
            return 0;
        });
    }

    joystick_button(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve(0);
        } else {
            const pin = Cast.toNumber(args.PIN);
            return bitblock.digital_read(pin)
            .then(packet => {
                if (packet) {
                    return packet[BBRETURN.DATA1];
                }
                return 0;
            });
        }
    }
    multi_switch(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve(0);
        } else {
            const pin = Cast.toNumber(args.PIN);
            return bitblock.analog_read(pin)
            .then(packet => {
                if (packet) {
                    const al = packet[BBRETURN.DATA1]; // low byte
                    const ah = packet[BBRETURN.DATA2]; // hight byte
                    const val = (ah << 8) | al;
                    if( val > 1000) {
                        return 1;
                    } else if (val > 600) {
                        return 4;
                    } else if (val > 300) {
                        return 2;
                    } else if (val > 100) {
                        return 3;
                    } else {
                        return 0;
                    } 
                }
                return 0;
            });
        }
    }

    func_map(args) {
        if (
            args.VALUE1 == "" ||
            args.VALUE2 == "" ||
            args.VALUE3 == "" ||
            args.VALUE4 == "" ||
            args.VALUE5 == ""
        ) {
            return 0;
        }

        let val1 = Cast.toNumber(args.VALUE1);
        let val2 = Cast.toNumber(args.VALUE2);
        let val3 = Cast.toNumber(args.VALUE3);
        let val4 = Cast.toNumber(args.VALUE4);
        let val5 = Cast.toNumber(args.VALUE5);

        if (val1 >= val3) {
            val1 = val3;
        }

        return MathUtil.scale(val1, val2, val3, val4, val5).toFixed(3);
    }

    func_random(args) {
        if (args.MIN == "" || args.MAX == "") {
            return 0;
        }

        const min = Cast.toNumber(args.MIN);
        const max = Cast.toNumber(args.MAX);
        return Math.floor(Math.random() * (max - min + 1) + min);
    }

    func_value1_or_value2(args) {
        const cond = Cast.toBoolean(args.CONDITION);

        const value_1 = args.VALUE1;
        const value_2 = args.VALUE2;
        return cond ? value_1 : value_2;
    }

    get_firmware_version(args) {
        const bitblock = this._peripheral.getDevice(DEFAULT_DEVICE);
        if (bitblock == null || bitblock === undefined) {
            return Promise.resolve(0);
        } else {
            return bitblock.get_firmware_version();
        }
    }

    _targetSay(message) {
        if (!this.enableLog) {
            return;
        }

        const target = this.runtime.targets[1];
        if (target) {
            this.runtime.emit("SAY", this.runtime.targets[1], "say", message);
        }

        setTimeout(() => {
            if (target) {
                this.runtime.emit("SAY", this.runtime.targets[1], "say", "");
            }
        }, 1000);
    }

    _setLocale() {
        const locale = formatMessage.setup().locale;
        return AvailableLocales.includes(locale) ? locale : "en";
    }
