    // "[LIST]을(를) 학습 데이터로 설정",
    useDataFromList(args, utils) {
        // TargetID 얻기
        const list = this._getVarObjectFromName(args.LIST, utils, "list");
        if (!list) {
            this.objList = null;
            return false;
        }

        this.objList = list;

        if (list.value.length == 0) {
            // 리스트에 데이터가 없는 경우
            return false;
        }

        if (!Array.isArray(list.value[0])) {
            this.headers = list.value[0].split(",");
            this.dataBody = list.value.slice(1).map((item, index) =>
                item.split(",").map((data) => {
                    if (this.isNumber(data)) {
                        return parseFloat(data);
                    } else {
                        return data;
                    }
                })
            );
        } else {
            this.headers = list.value[0];
            this.dataBody = list.value.slice(1);
        }

        // console.error("HEADER : ", this.headers);
        // console.error("BODY : ", this.dataBody);

        // ---------- 데이터 보디 처리 ----------------
        // 데이터 처리
        const tempBody = [];
        for (let i = 0; i < this.dataBody.length; i++) {
            const obj = {};
            for (let j = 0; j < this.headers.length; j++) {
                obj[this.headers[j]] = this.dataBody[i][j];
            }
            tempBody.push(obj);
        }
        // ----------헤더 처리 ----------------
        const tempHeader = this.headers.map((item) => {
            return { text: item, value: item };
        });
        // const tempObj = { header : tempHeader, databody : tempBody};
        const tempObj = [tempHeader, tempBody, "dataclassification"]; // HEADER, DATABODY

        // 🍀데이터를 runtime을 통해서 gui쪽으로 건넴...
        this.runtime.setTableLibraryData("dataclassification", tempObj);

        // 🍀데이터프레임 만듬.
        this.dataFrame = new DataFrame(this.dataBody, this.headers);
        this.dataFrame.show(); // For DEBUG

        this.targetSay(Message.msg_train_data_set[this.locale]);
    }

    // dataframe-js - {csv} https://www.npmjs.com/package/dataframe-js
    // LokiJS - {json}
    // sql - {alasql}

    // CSV 를 직접 받아 Blob 으로 넘긴다. DataFrame.fromCSV(url) 은 요청이 실패하면(CORS, 404) 내부에서
    // null.includes 예외가 나고 Promise 가 영원히 끝나지 않아 블록이 멈췄다. 여기서는 실패가 reject 로 전파된다.
    async _insertDataToDataframe(url) {
        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`HTTP ${response.status} ${url}`);
        }
        const csvBlob = new Blob([await response.text()], { type: "text/csv" });
        return DataFrame.fromCSV(csvBlob).then((df) => {
            // NA값 처리 (빈 셀은 null 로 올 수 있다)
            const cols = df.listColumns();
            const filtered_df = df.filter((row) => {
                for (const col of cols) {
                    const raw = row.get(col);
                    const val = typeof raw === "undefined" || raw === null ? "" : String(raw).trim()
                        .toUpperCase();
                    if (["NAN", "NA", "NULL", ""].includes(val)) {
                        return false;
                    }
                }
                return true;
            });

            // headerr
            this.headers = filtered_df.listColumns();
            //data body
            this.dataBody = filtered_df.toArray();
        });
    }

    // 예전 프로젝트에 저장된 단축 주소를 새 주소로 바꾼다. 모르는 주소는 그대로.
    _resolveDatasetUrl(url) {
        const trimmed = Cast.toString(url).trim();
        const key = trimmed.replace(/^https?:\/\//, "");
        return LEGACY_DATASET_URLS[key] || trimmed;
    }

