    doRFClassifier() {
        let inputDf = this.dataFrame.select(...this.inputHeader);
        // console.log(LOGTAG, "*** input df...count=>", inputDf.count());
        // inputDf.show();

        let outputDf = this.dataFrame.select(this.outputHeader[0]);
        // console.log(LOGTAG, "*** output df...outputDf=>", outputDf.count());
        // outputDf.show();

        const inputArr = inputDf
            .toArray()
            .map((elem) => lodash.map(elem, (x) => Cast.toNumber(x)));
        // const outputArr = outputDf.toArray().flat(Infinity);
        const outputArr = outputDf
            .toArray()
            .flat(Infinity)
            .map((elem) => this.targetClasses.indexOf(elem)); // 클래스를 숫자 index로 바꿈...

        // 트리 회귀의 경우
        const options = {
            gainFunction: "gini",
            maxDepth: 10,
            minNumSamples: 3,
        };

        this.nn = new DecisionTreeClassifier(options);
        this.nn.train(inputArr, outputArr);

        // console.log("🍅🍅🍅 this.nn : ", this.nn);
    }

    predict(args, utils) {
        this.doClassification(args, utils);
    }

    doClassification(args, utils) {
        let prediction = 0;
        if (!this.nn) {
            this.targetSay(Message.msg_model_not_ready[this.locale]);
            return;
        }

        // "3.5" / "3.5,1.2" / 값 묶음 리포터 / 숫자 리포터를 모두 받는다.
        // (예전에는 쉼표 문자열이 0 으로, 숫자 리포터는 무시되어 엉뚱한 예측이 나왔다)
        const xvalue = DataRecorder.normalizeCells(args.XVALUE).map((v) =>
            Cast.toNumber(v)
        );
        if (xvalue.length !== this.inputHeader.length) {
            this._warn(
                DataRecorder.describeError(
                    {
                        error: "PREDICT_COUNT",
                        expected: this.inputHeader.length,
                        got: xvalue.length,
                    },
                    this.locale
                ),
                utils
            );
            return;
        }
        prediction = this.nn.predict([xvalue]);

        if (typeof prediction === "object") {
            prediction = prediction[0];
        }
        prediction = parseInt(prediction);

        this.when_received = true;
        this.predictionValue = [xvalue, this.targetClasses[prediction]];

        this.targetSay(`${Message.msg_result[this.locale]} = ${this.predictionValue[1]}`);
        console.log(LOGTAG, "분류 => ", this.predictionValue);
    }

