    // 로그 말하기(enableLog)를 꺼도 보이는 경고. 블록을 실행한 스프라이트가 말한다.
    _warn(message, utils) {
        const self = utils && utils.target;
        const target =
            self && !self.isStage ? self : this.runtime.targets[1];
        console.warn(LOGTAG, message);
        if (!target) return;
        this.runtime.emit("SAY", target, "say", message);
        setTimeout(() => this.runtime.emit("SAY", target, "say", ""), 2000);
    }

    _recorderList(args, utils) {
        const list = this._getVarObjectFromName(args.LIST, utils, "list");
        if (!list) {
            this._warn(
                DataRecorder.describeError({ error: "NO_LIST" }, this.locale),
                utils
            );
        }
        return list;
    }

    _recorderResult(result, utils) {
        if (!result.ok) {
            this._warn(DataRecorder.describeError(result, this.locale), utils);
        }
    }

    recordPrepare(args, utils) {
        const list = this._recorderList(args, utils);
        if (!list) return;
        this._recorderResult(
            DataRecorder.prepareHeader(list, args.COLUMNS),
            utils
        );
    }

    recordRow(args, utils) {
        const list = this._recorderList(args, utils);
        if (!list) return;
        this._recorderResult(
            DataRecorder.appendRow(list, args.VALUES, args.LABEL),
            utils
        );
    }

    recordUndo(args, utils) {
        const list = this._recorderList(args, utils);
        if (!list) return;
        this._recorderResult(DataRecorder.removeLastRow(list), utils);
    }

