    HEADER_LIST_MENU() {
        let items = [""];
        if (this.headers.length > 0) {
            items = items.concat(this.headers);
        }
        return items;
    }

    get LIST_ITEM_LIMIT() {
        return 200000;
    }

    _sleep(ms) {
        return new Promise((resolve) => setTimeout(resolve, ms));
    }

    setLocale() {
        let ret = "en";
        const locale = formatMessage.setup().locale;
        if (AvailableLocales.includes(locale)) {
            ret = locale;
        }
        return ret;
    }

    targetSay(message) {
        if (!this.enableLog) {
            return;
        }

        const target = this.runtime.targets[1];
        if (target) {
            this.runtime.emit("SAY", this.runtime.targets[1], "say", message);
        }

        setTimeout(() => {
            if (target) {
                this.runtime.emit("SAY", this.runtime.targets[1], "say", "");
            }
        }, 1000);
    }

