/* eslint-disable no-warning-comments */
const JSONRPCWebSocket = require('../util/rpc-socket');
// const ScratchLinkWebSocket = 'ws://localhost:30110/arduino/serial';
// const ScratchLinkWebSocket = 'ws://localhost:30110/kamibot/serial';  //30110
// const ScratchLinkWebSocket = 'ws://localhost:30307/kamilink/serial'; // 30307
const LINK_WEBSOCKET = 'ws://localhost:30307/'; // 30307
// const log = require('../util/log');

class SERIAL extends JSONRPCWebSocket {

    /**
     * A BT peripheral socket object.  It handles connecting, over web sockets, to
     * BT peripherals, and reading and writing data to them.
     * @param {Runtime} runtime - the Runtime for sending/receiving GUI update events.
     * @param {string} extensionId - the id of the extension using this socket.
     * @param {object} peripheralOptions - the list of options for peripheral discovery.
     * @param {object} connectCallback - a callback for connection.
     * @param {object} disconnectCallback - a callback for disconnection.
     * @param {object} messageCallback - a callback for message sending.
     */
    constructor (runtime, extensionId, peripheralOptions, connectCallback, disconnectCallback = null, messageCallback) {
        const ws = new WebSocket(`${LINK_WEBSOCKET}${extensionId}`);
        super(ws);
        this._ws = ws;
        this._ws.onopen = this.requestPeripheral.bind(this); // only call request peripheral after socket opens
        this._ws.onerror = this._handleRequestError.bind(this, 'ws onerror');
        this._ws.onclose = this.handleDisconnectError.bind(this, 'ws onclose');

        this._availablePeripherals = {};
        this._connectCallback = connectCallback;
        this._connected = false;
        this._characteristicDidChangeCallback = null;
        this._disconnectCallback = disconnectCallback;
        this._discoverTimeoutID = null;
        this._extensionId = extensionId;
        this._peripheralOptions = peripheralOptions;
        this._messageCallback = messageCallback;
        this._runtime = runtime;
    }


    /**
     * Request connection to the peripheral.
     * If the web socket is not yet open, request when the socket promise resolves.
     * 스크래치 물음표 연결 버튼 클릭.
     * 0 CONNECTING : 소켓이 생성되었다. 연결이 아직 열려 있지 않다.
     * 1 OPEN : 연결이 열려 있고, 통신할 준비가 되었다.
     * 2 CLOSING : 연결이 닫히는 중이다.
     * 3 CLOSED : 연결이 닫혔거나 열 수 없었다.
     */
    requestPeripheral () {
        console.log(`{serial} 1_requestPeripheral: readyState=>${this._ws.readyState}`);

        // 1:OPEN:연결이 수립되어 데이터가 오고갈 수 있는 상태입니다.
        if (this._ws.readyState === 1) { // is this needed since it's only called on ws.onopen?
            this._availablePeripherals = {};
            if (this._discoverTimeoutID) {
                window.clearTimeout(this._discoverTimeoutID);
            }

            this._discoverTimeoutID = window.setTimeout(this._handleDiscoverTimeout.bind(this), 15000);

            console.error(`{serial} 2_requestPeripheral: discover: option:${JSON.stringify(this._peripheralOptions)}`);

            this.sendRemoteRequest('discover', this._peripheralOptions)
                .catch(err => this._handleRequestError(err));
        }
    }


    /**
     * Try connecting to the input peripheral id, and then call the connect
     * callback if connection is successful.
     * @param {number} id - the id of the peripheral to connect to
     */
    connectPeripheral (id, extensionId) {
        // log.info(`serial->connectPeripheral:id:${id}`);

        this.sendRemoteRequest('connect', {peripheralId: id, extensionId: extensionId})
            .then(() => {
                this._connected = true;

                this._runtime.emit(this._runtime.constructor.PERIPHERAL_CONNECTED);
                this._connectCallback();
            })
            .catch(e => {
                this._handleRequestError(e);
            });
    }

    /**
     * Close the websocket.
     */
    disconnect (extensionId) {
        if (!this._connected) return;
        this._ws.close();
        this._connected = false;
        if (this._discoverTimeoutID) {
            window.clearTimeout(this._discoverTimeoutID);
        }
        this._runtime.emit(this._runtime.constructor.PERIPHERAL_DISCONNECTED);
    }

    /**
     * @return {bool} whether the peripheral is connected.
     */
    isConnected () {
        return this._connected;
    }

    sendMessage (options) {
        return this.sendRemoteRequest('send', options)
            .catch(err => {
                this.handleDisconnectError(err);
            });
    }

    getCountOfRequest () {
        const length = Object.keys(this._openRequests).length;
        return length;
    }

    // 스크래치에서 빨간색 버튼이 눌러지면 호출
    clear () {
        if (this._openRequests) {
            this._openRequests = {};
        }
    }

    /**
     * Handle a received call from the socket.
     * @param {string} method - a received method label.
     * @param {object} params - a received list of parameters.
     * @return {object} - optional return value.
     */
    didReceiveCall (method, params) {
        // log.info(`{serial} :didReceiveCall => method=${method} params=${JSON.stringify(params)}`);

        // TODO: Add peripheral 'undiscover' handling
        switch (method) {
        case 'didDiscoverPeripheral':
            // {"name":"BBC micro:bit [tetiz]", "rssi": -27, "peripheralId":241069154164473 }
            this._availablePeripherals[params.peripheralId] = params;
            this._runtime.emit(
                this._runtime.constructor.PERIPHERAL_LIST_UPDATE,
                this._availablePeripherals
            );
            if (this._discoverTimeoutID) {
                window.clearTimeout(this._discoverTimeoutID);
            }
            break;
        case 'didReceiveMessage':
            this._messageCallback(params);
            break;
        default:
            return 'nah';
        }
    }

    /**
     * Handle an error resulting from losing connection to a peripheral.
     *
     * This could be due to:
     * - battery depletion
     * - going out of bluetooth range
     * - being powered down
     *
     * Disconnect the socket, and if the extension using this socket has a
     * disconnect callback, call it. Finally, emit an error to the runtime.
     */
    handleDisconnectError (/* e */) {
        // log.error(`BT error: ${JSON.stringify(e)}`);

        if (!this._connected) return;

        // TODO: Fix branching by splitting up cleanup/disconnect in extension
        if (this._disconnectCallback) {
            this._disconnectCallback(); // must call disconnect()
        } else {
            this.disconnect();
        }

        this._runtime.emit(this._runtime.constructor.PERIPHERAL_CONNECTION_LOST_ERROR, {
            message: `Scratch lost connection to`,
            extensionId: this._extensionId
        });
    }

    _handleRequestError (/* e */) {
        // log.error(`BT error: ${JSON.stringify(e)}`);

        this._runtime.emit(this._runtime.constructor.PERIPHERAL_REQUEST_ERROR, {
            message: `Scratch lost connection to`,
            extensionId: this._extensionId
        });
    }

    _handleDiscoverTimeout () {
        if (this._discoverTimeoutID) {
            window.clearTimeout(this._discoverTimeoutID);
        }
        this._runtime.emit(this._runtime.constructor.PERIPHERAL_SCAN_TIMEOUT);
    }

}

module.exports = SERIAL;
