import bindAll from 'lodash.bindall';
import PropTypes from 'prop-types';
import React from 'react';
import {connect} from 'react-redux';
import VM from 'scratch-vm';

import DisconnectConfirmModalComponent from '../components/disconnect-confirm-modal/disconnect-confirm-modal.jsx';
import {closeDisconnectConfirmModal} from '../reducers/modals';

class DisconnectConfirmModal extends React.Component {
    constructor (props) {
        super(props);
        bindAll(this, [
            'handleCancel',
            'handleConfirm'
        ]);
    }

    handleCancel () {
        this.props.onCloseModal();
    }

    handleConfirm () {
        try {
            this.props.vm.disconnectPeripheral(this.props.extensionId);
        } finally {
            this.props.onCloseModal();
        }
    }

    render () {
        return (
            <DisconnectConfirmModalComponent
                onCancel={this.handleCancel}
                onConfirm={this.handleConfirm}
            />
        );
    }
}

DisconnectConfirmModal.propTypes = {
    extensionId: PropTypes.string,
    onCloseModal: PropTypes.func.isRequired,
    vm: PropTypes.instanceOf(VM).isRequired
};

const mapStateToProps = state => ({
    extensionId: state.scratchGui.connectionModal.extensionId
});

const mapDispatchToProps = dispatch => ({
    onCloseModal: () => dispatch(closeDisconnectConfirmModal())
});

export default connect(mapStateToProps, mapDispatchToProps)(DisconnectConfirmModal);
