// Scratch의 ConnectionModal(스캐닝/연결 중/연결됨 스텝)을 우회한다.
// 브라우저 네이티브 BLE 피커에서 사용자가 장치를 선택하면 즉시 연결하고,
// 성공/실패/취소 모두 UI 전환 없이 편집기 상태 그대로 유지.
//
// 주의: 이 함수는 반드시 user gesture 콜스택(click 핸들러 등)에서 동기 호출해야 한다.
// Web Bluetooth requestDevice가 user activation을 요구한다.
const webBluetoothDirectConnect = function (vm, extensionId) {
    if (vm.getPeripheralIsConnected(extensionId)) {
        return;
    }

    let settled = false;
    const onListUpdate = peripherals => {
        const ids = Object.keys(peripherals || {});
        if (ids.length === 0) return;
        vm.removeListener('PERIPHERAL_LIST_UPDATE', onListUpdate);
        vm.connectPeripheral(extensionId, ids[0]);
    };
    const onConnected = () => {
        if (settled) return;
        settled = true;
        cleanup();
    };
    const onFailure = () => {
        if (settled) return;
        settled = true;
        cleanup();
        try {
            vm.disconnectPeripheral(extensionId);
        } catch (e) {
            // 이미 정리된 상태
        }
    };
    const cleanup = () => {
        vm.removeListener('PERIPHERAL_LIST_UPDATE', onListUpdate);
        vm.removeListener('PERIPHERAL_CONNECTED', onConnected);
        vm.removeListener('PERIPHERAL_SCAN_TIMEOUT', onFailure);
        vm.removeListener('PERIPHERAL_REQUEST_ERROR', onFailure);
        vm.removeListener('PERIPHERAL_CONNECTION_LOST_ERROR', onFailure);
    };

    vm.on('PERIPHERAL_LIST_UPDATE', onListUpdate);
    vm.on('PERIPHERAL_CONNECTED', onConnected);
    vm.on('PERIPHERAL_SCAN_TIMEOUT', onFailure);
    vm.on('PERIPHERAL_REQUEST_ERROR', onFailure);
    vm.on('PERIPHERAL_CONNECTION_LOST_ERROR', onFailure);

    vm.scanForPeripheral(extensionId);
};

export default webBluetoothDirectConnect;
