    mqttConnServer(host, options, user, pass) {
        console.error("@@ MQTT BROKER : ", host);
        console.error("@@ OPTION : ", options);

        return new Promise((resolve, reject) => {
            if (this.client) {
                this.client.end();
            }

            let client = null;
            if (Object.keys(options).length === 0) {
                console.error("NO Option!!!  host :", host);
                client = mqtt.connect(host);
            } else {
                console.log("with option : ", options);
                client = mqtt.connect(host, options);
            }

            client.retryCnt = 0;
            this.client = client;

            this.client.on("message", (topic, message) => {
                // message is Buffer
                // console.log(topic, message);
                // this.mqttTopicData = message.toString('utf-8');
                if (!this.mqttTopicData) {
                    this.mqttTopicData = {};
                }
                // this.mqttTopicData  = `${topic}:${message.toString('utf-8')}`;
                // this.mqttTopicData[topic] = message.toString("utf-8");

                const decodedString = decodeURIComponent(message);
                // console.log('DECODED STRING:', decodedString); // {"key":"온도센서","data":"36.5"}
                const parsedObject = JSON.parse(decodedString);

                this.mqttTopicData[parsedObject.key] = parsedObject.data;

                // console.log("this->", this);
                // console.log("[on.message]", this.mqttTopicData);

                // setTimeout(((topic) => {
                //     console.error('@@@ TIMEOUT : topic:', topic);
                //     this.mqttTopicData[topic] = null;
                // })(topic), 10000); //300

                setTimeout(() => {
                    // topic은 계속 유지하고 있는것 같네..
                    this.mqttTopicData[parsedObject.key] = null;
                }, 300); //
            });

            this.client.on("close", function (a) {
                console.log("connection closed!" + a);
                this.mqttTopicData = {};
            });

            this.client.on("end", () => {
                console.log("mqtt end");
                this.connected = false;
                this.mqttTopicData = {};
                this.targetSay(Message.msg_disconnected[this.locale]);
            });

            this.client.on("error", (e) => {
                console.log("mqtt err", e);
                this.connected = false;
                this.targetSay(Message.msg_error[this.locale]);
            });

            this.client.on("connect", (connack) => {
                client.retryCnt = 0;
                this.connected = true;
                console.log("*** connected! ***");
                this.targetSay(Message.msg_server_connected[this.locale]);
                resolve();
            });

            this.client.on("reconnect", () => {
                client.retryCnt++;
                if (client.retryCnt > 3) {
                    client.end();
                    reject("error: time out");
                }
            });
        });
    }

