import classNames from "classnames";
import bindAll from "lodash.bindall";
import PropTypes from "prop-types";
import React, { useState, useEffect } from "react";
import { defineMessages, FormattedMessage, injectIntl, intlShape } from "react-intl";

import Box from "../box/box.jsx";

import Paper from "@material-ui/core/Paper";
import { makeStyles } from "@material-ui/core/styles";
import TableContainer from "@material-ui/core/TableContainer";
import InputLabel from "@material-ui/core/InputLabel";
import MenuItem from "@material-ui/core/MenuItem";
import FormControl from "@material-ui/core/FormControl";
import Select from "@material-ui/core/Select";

import FormControlLabel from "@material-ui/core/FormControlLabel";
import Checkbox from "@material-ui/core/Checkbox";

import * as _ from "underscore";

// 참고 : https://codesandbox.io/s/chartjs-scatter-jkf5f?file=/src/App.js:2510-2517

import { Scatter } from "react-chartjs-2";
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Title,
    Tooltip,
    Legend,
} from "chart.js";

ChartJS.register(
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    // Title,
    Tooltip,
    Legend
);

import styles from "./scatter-compo.css";

const BORDER_COLOSRS = [
    "rgb(124, 0, 254)",
    "rgb(93, 63, 211)",
    "rgb(36, 113, 163)",
    "rgb(26, 188, 156)",
    "rgb(241, 196, 15)",
    "rgb(231, 76, 60)",
    "rgb(33, 47, 60)",
    "rgb(215, 189, 226)",
    "rgb(195, 155, 211)",
    "rgb(230, 176, 170)",
];
const BACKGROUND_COLORS = [
    "rgba(124, 0, 254, 0.5)",
    "rgba(93, 63, 211, 0.5)",
    "rgba(36, 113, 163, 0.5)",
    "rgba(26, 188, 156, 0.5)",
    "rgba(241, 196, 15, 0.5)",
    "rgba(231, 76, 60, 0.5)",
    "rgba(33, 47, 60, 0.5)",
    "rgba(215, 189, 226, 0.5)",
    "rgba(195, 155, 211, 0.5)",
    "rgba(230, 176, 170, 0.5)",
];

const useStyles = makeStyles((theme) => ({
    chart: {
        width: "80%",
        marginTop: "0",
        // backgroundColor: 'red'
    },
    formControl: {
        margin: theme.spacing(2),
        minWidth: 200,
    },
    selectEmpty: {
        marginTop: theme.spacing(2),
    },
}));

const chartOptions = {
    responsive: true,
    // aspectRatio: 1,
    plugins: {
        legend: {
            position: "top",
        },
        title: {
            display: false,
            text: "Chart.js Scatter Plot",
        },
    },
};

const emptyData = {
    labels: [],
    datasets: [],
};

// {
//     label:"Step By Pedro",
//     data:[3000, 5000,4500, 6000, 8000, 7000, 9000],
//     borderColor: 'rgb(255, 99, 132)', //그래프 선 color
//     backgroundColor: 'rgba(255, 99, 132, 0.5)', //마우스 호버시 나타나는 분류네모 표시 bg
// }

function ScatterPlot(props) {
    const classes = useStyles();
    const [rows, setRows] = useState(props.data);
    const [headers, setHeaders] = useState(props.headers);
    const [xaxis, setXaxis] = React.useState("");
    const [yaxis, setYaxis] = React.useState("");
    const [label, setLabel] = React.useState("");
    const [chartData, setChartData] = React.useState(emptyData);
    const [sorted, setSorted] = React.useState(true);

    useEffect(() => {
        if (xaxis == "" || yaxis == "" || label == "") {
            return;
        }

        // 객체 DEEP COPY
        let sortedData = [...rows];
        if (sorted) {
            sortedData = sortedData.sort((a, b) => {
                if (isNaN(a[xaxis]) || isNaN(b[xaxis])) {
                    if (a[xaxis] < b[xaxis]) {
                        return -1;
                    }
                } else {
                    if (Number(a[xaxis]) < Number(b[xaxis])) {
                        return -1;
                    }
                }
            });
        }

        const xAxisValue = sortedData.map((item) => item[xaxis]);
        const yAxisValue = sortedData.map((item) => item[yaxis]);
        const targetVal = sortedData.map((item) => item[label]);

        let uniqueTarget = [...new Set(targetVal)];

        const arrData = [];
        for (let i = 0; i < uniqueTarget.length; i++) {
            const elems = [];

            for (let j = 0; j < targetVal.length; j++) {
                if (uniqueTarget[i] == targetVal[j]) {
                    elems.push({
                        x: xAxisValue[j],
                        y: yAxisValue[j],
                        label: uniqueTarget[i],
                    });
                }
            }

            arrData.push(elems);
        }
        const datasetsArr = [];

        for (let i = 0; i < uniqueTarget.length; i++) {
            const c = _.random(0, BORDER_COLOSRS.length);

            datasetsArr.push({
                label: uniqueTarget[i], // 레이블명
                borderColor: BORDER_COLOSRS[c],
                backgroundColor: BACKGROUND_COLORS[c],
                pointRadius: 10,
                data: arrData[i],
            });
        }

        const objectData = {
            labels: xAxisValue,
            datasets: datasetsArr,
        };
        setChartData(objectData);
    }, [xaxis, yaxis, label, sorted]);

    const handleXAxisChange = (event) => {
        setXaxis(event.target.value);
    };

    const handleYAxisChange = (event) => {
        setYaxis(event.target.value);
    };

    const handleLabelChange = (event) => {
        setLabel(event.target.value);
    };

    const handleCheckChange = (event) => {
        setSorted(!sorted);
    };

    return (
        <>
            <TableContainer component={Paper} className={classes.chart}>
                <Scatter options={chartOptions} data={chartData} />

                <Box className={styles.selectContainer}>
                    <FormControl
                        variant="outlined"
                        size="small"
                        className={classes.formControl}
                    >
                        <InputLabel id="xaxis-select-outlined-label">
                            <FormattedMessage defaultMessage="X axis" description="Chart axis selector label" id="gui.dataTable.chart.xAxis" />
                        </InputLabel>
                        <Select
                            labelId="xaxis-select-outlined-label"
                            id="xaxis-select-outlined"
                            value={xaxis}
                            onChange={handleXAxisChange}
                            label="x_axis"
                        >
                            <MenuItem value="">
                                <em>None</em>
                            </MenuItem>
                            {headers.map((header, index) => (
                                <MenuItem key={index} value={header.value}>
                                    {header.value}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <FormControl
                        variant="outlined"
                        size="small"
                        className={classes.formControl}
                    >
                        <InputLabel id="yaxis-select-outlined-label">
                            <FormattedMessage defaultMessage="Y axis" description="Chart axis selector label" id="gui.dataTable.chart.yAxis" />
                        </InputLabel>
                        <Select
                            labelId="yaxis-select-outlined-label"
                            id="yaxis-select-outlined"
                            value={yaxis}
                            onChange={handleYAxisChange}
                            label="y_axis"
                        >
                            <MenuItem value="">
                                <em>None</em>
                            </MenuItem>
                            {headers.map((header, index) => (
                                <MenuItem key={index} value={header.value}>
                                    {header.value}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <FormControl
                        variant="outlined"
                        size="small"
                        className={classes.formControl}
                    >
                        <InputLabel id="yaxis-select-outlined-label">
                            <FormattedMessage defaultMessage="Label" description="Chart label (class) selector" id="gui.dataTable.chart.label" />
                        </InputLabel>
                        <Select
                            labelId="label-select-outlined-label"
                            id="label-select-outlined"
                            value={label}
                            onChange={handleLabelChange}
                            label="label"
                        >
                            <MenuItem value="">
                                <em>None</em>
                            </MenuItem>
                            {headers.map((header, index) => (
                                <MenuItem key={index} value={header.value}>
                                    {header.value}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    {/* 여백 */}
                    <Box className={styles.fr}></Box>
                    {/* checkbox */}
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={sorted}
                                onChange={handleCheckChange}
                                name="sortCheck"
                                color="primary"
                            />
                        }
                        label={<FormattedMessage defaultMessage="Sort by X axis" description="Checkbox to sort chart by X axis" id="gui.dataTable.chart.sortXAxis" />}
                    />
                </Box>
            </TableContainer>
        </>
    );
}

export default ScatterPlot;
