    // async
    async detectFace() {
        if (!this.faceModel) {
            this._targetSay(Message.FormFaceMSG_error_loading[this.locale]);
            return;
        }
        // 이전 검출이 끝나지 않았으면 건너뛴다(Worker에 요청이 쌓이지 않게).
        if (this._detectInFlight) return;

        this._detectInFlight = true;
        try {
            // 고급 설정에서 AI 처리 장치를 바꿨으면 모델을 다시 만든다.
            if (this.faceModel.isSettingChanged()) {
                await this.loadFaceModel();
                if (!this.faceModel) return;
            }

            const originalCanvas = this.runtime.renderer._gl.canvas;
            // 현재 캠버스 크기의 이미지프레임을 얻는다.
            const frame = this._getFrame(
                originalCanvas.offsetWidth,
                originalCanvas.offsetHeight
            );
            if (!frame) return; // 카메라가 꺼져 있으면 프레임이 없다.
            this.onResults(await this.faceModel.detect(frame));
        } catch (e) {
            console.error(LOGTAG, "얼굴 검출 실패", e);
        } finally {
            this._detectInFlight = false;
        }
    }

    clearResult(args) {
        this.rawLandmarks = [];
        this.faceLandMarks = [];
        this.boundingBox = [];
        this.isDetected = false;

        const hatOpcode = "facemesh_whenDetectedFace";
        this.runtime.allScriptsByOpcodeDo(hatOpcode, (script, target) => {
            target.updateEdgeActivatedValue(script.blockId, false);
        });
    }

    toggleDrawLandmarks(args) {
        this.enableDrawLandmarks = false;
        if (args.ONOFF === "1") {
            this.enableDrawLandmarks = true;
            // console.log(`${LOGTAG} ENABLE DRAW : ${this.enableDrawLandmarks}`);
        }
    }

    setLocale() {
        const locale = formatMessage.setup().locale;
        if (AvailableLocales.includes(locale)) {
            return locale;
        }
        return "en";
    }
