const FCM_SUPPORTED_VERSION = 1;

function decodeFcm(arrayBuffer) {
    const bytes = new Uint8Array(arrayBuffer);
    for (let i = 0; i < 4; i++) {
        if (bytes[i] !== FCM_MAGIC[i]) throw new Error("Invalid .fcm file");
    }
    const view = new DataView(arrayBuffer);
    const version = view.getUint8(4);
    if (version !== FCM_SUPPORTED_VERSION) {
        console.warn(LOGTAG, `unsupported .fcm version: ${version} (expected ${FCM_SUPPORTED_VERSION})`);
    }
    const dataLen = view.getUint32(13, false);
    const encoded = bytes.slice(17, 17 + dataLen);
    const decoded = new Uint8Array(encoded.length);
    for (let i = 0; i < encoded.length; i++) {
        decoded[i] = encoded[i] ^ FCM_XOR_KEY[i % FCM_XOR_KEY.length];
    }
    return JSON.parse(new TextDecoder().decode(decoded));
}

// ── libsvm-js (svm-rbf 알고리즘 런타임) ─────────────────────────────────
// libsvm-js 의 기본 entry (wasm.js) 는 런타임에 libsvm.wasm 을 fetch 로 로드하고
// libsvm.load().then(...) 으로 비동기 exports 를 만든다. 웹팩 번들 내부의 wasm 경로
// 해석이 실패하면 emscripten 초기화가 중단되어 `libsvm.load is not a function` 을 던진다.
// asm.js entry 는 메모리 이미지를 data URI 로 inline 하기 때문에 fetch 가 필요 없고
// require 시점에 동기적으로 SVM 클래스를 돌려준다 → svm-rbf 분기만 쓰는 이 확장에서는
// asm.js 쪽이 더 안정적이다.
let _svmLib = null;
function ensureSVMLib() {
    if (_svmLib) return _svmLib;
    // eslint-disable-next-line global-require
    _svmLib = require("libsvm-js/asm");
    return _svmLib;
}

// ── 분류기 공용 헬퍼 (참조: D:/wk_app/classifyme/src/classicClassifiers.js 포팅) ──
// 4개 알고리즘(rf / svm-rbf / mlp / softmax)에 대한 역직렬화 + 예측을 단일 진입점으로.
// `tf`는 scratch-gui index.ejs 에서 주입되는 전역(window.tf)을 그대로 사용.

function _buildSoftmax(tfjs, inputDim, nClasses) {
    const m = tfjs.sequential();
    m.add(tfjs.layers.dense({
        units: nClasses,
        activation: "softmax",
        inputShape: [inputDim],
    }));
    return m;
}

function _buildMLP(tfjs, inputDim, nClasses) {
    // 참조 classicClassifiers.js:131-140 — inputDim>256 이면 [128,64], 아니면 [64,32]
    const h1 = inputDim > 256 ? 128 : 64;
    const h2 = inputDim > 256 ? 64 : 32;
    const m = tfjs.sequential();
    m.add(tfjs.layers.dense({ units: h1, activation: "relu", inputShape: [inputDim] }));
    m.add(tfjs.layers.dense({ units: h2, activation: "relu" }));
    m.add(tfjs.layers.dense({ units: nClasses, activation: "softmax" }));
    return m;
}

// 참조 classicClassifiers.js:220-241 deserializeModel 포팅
// 반환: { classifier, kind, dispose } — kind ∈ {'rf','svm','mlp','softmax'}
async function deserializeClassifier(algorithm, serialized, inputDim, nClasses) {
    if (algorithm === "random-forest") {
        const classifier = RandomForestClassifier.load(serialized.data);
        return { classifier, kind: "rf", dispose: () => {} };
    }
    if (algorithm === "svm-rbf") {
        const SVM = ensureSVMLib();
        const classifier = SVM.load(serialized.data);
        return { classifier, kind: "svm", dispose: () => {} };
    }
    if (algorithm === "mlp" || algorithm === "softmax") {
        const model = algorithm === "mlp"
            ? _buildMLP(tf, inputDim, nClasses)
            : _buildSoftmax(tf, inputDim, nClasses);
        const tensors = serialized.weights.map((w) =>
            tf.tensor(w.data, w.shape, w.dtype)
        );
        model.setWeights(tensors);
        tensors.forEach((t) => t.dispose());
        return {
            classifier: model,
            kind: algorithm,
            dispose: () => {
                if (model && typeof model.dispose === "function") model.dispose();
            },
        };
    }
    throw new Error(`Unknown algorithm: ${algorithm}`);
}

// 참조 classicClassifiers.js predictRF/SVM/MLP/Softmax 포팅
// 항상 Promise<number[]> (길이 nClasses) 반환
async function predictProbabilities(kind, classifier, featureVec, nClasses) {
    if (kind === "rf") {
        const pv = classifier.predictionValues([featureVec]);
        const treePreds = pv.getRow(0);
        const votes = new Array(nClasses).fill(0);
        for (const v of treePreds) {
            if (v >= 0 && v < nClasses) votes[v]++;
        }
        const total = votes.reduce((a, b) => a + b, 0);
        return total > 0 ? votes.map((v) => v / total) : votes;
    }
    if (kind === "svm") {
        const out = new Array(nClasses).fill(0);
        const { estimates } = classifier.predictOneProbability(featureVec);
        for (const { label, probability } of estimates) {
            const idx = Number(label);
            if (idx >= 0 && idx < nClasses) out[idx] = probability;
        }
        return out;
    }
    if (kind === "mlp" || kind === "softmax") {
        const xs = tf.tensor2d([featureVec]);
        const out = classifier.predict(xs);
        const data = await out.data();
        xs.dispose();
        out.dispose();
        const arr = new Array(nClasses);
        for (let i = 0; i < nClasses; i++) arr[i] = data[i];
        return arr;
    }
    throw new Error(`Unknown classifier kind: ${kind}`);
}

