const JSONRPC = require("../util/jsonrpc");
const BLE_EX = require("./bleLinkEx");

class BLELINK extends JSONRPC {
    /**
     * A BLE peripheral socket object.  It handles connecting, over web sockets, to
     * BLE peripherals, and reading and writing data to them.
     * @param {Runtime} runtime - the Runtime for sending/receiving GUI update events.
     * @param {string} extensionId - the id of the extension using this socket.
     * @param {object} peripheralOptions - the list of options for peripheral discovery.
     * @param {object} connectCallback - a callback for connection.
     * @param {object} resetCallback - a callback for resetting extension state.
     */
    constructor(
        runtime,
        extensionId,
        peripheralOptions,
        connectCallback,
        resetCallback,
        type
    ) {
        super();

        this._socket = runtime.getScratchLinkSocket("BLE");
        this._socket.setOnOpen(this.requestPeripheral.bind(this));
        this._socket.setOnClose(this.handleDisconnectError.bind(this));
        this._socket.setOnError(this._handleRequestError.bind(this));
        this._socket.setHandleMessage(this._handleMessage.bind(this));

        this._sendMessage = this._socket.sendMessage.bind(this._socket);

        this._availablePeripherals = {};
        this._connectCallback = connectCallback;
        this._connected = false;
        this._characteristicDidChangeCallback = null;
        this._resetCallback = resetCallback;
        this._discoverTimeoutID = null;
        this._extensionId = extensionId;
        this._peripheralOptions = peripheralOptions;
        this._runtime = runtime;
        this._connectId = null;
        this._connectDeviceList = new Array();
        this._devices = {};

        // this._connectDevice;
        this._type = type; //0 Kamibot //1 Bitblock
        this._socket.open();
        this._stopScan = 0;

        // 디버그 중 ...
        this._bleSocketCount = 0;
        this._bleIsConnectList = new Array();
        this._bleSocketList = new Array();
    }

    /**
     * Request connection to the peripheral.
     * If the web socket is not yet open, request when the socket promise resolves.
     */
    // 스크래치 링크의 소켓이 Open되면 자동으로 실행된다.
    requestPeripheral() {
        console.log("🌌🌌🌌 {bleLink}-{requestPeripheral}");

        // 스캔 리퀘스트 전에 초기화 해두는 거임?
        this._availablePeripherals = {};

        if (this._discoverTimeoutID) {
            window.clearTimeout(this._discoverTimeoutID);
        }
        this._stopScan = 0;

        // 디바이스를 찾지못하면 실행될 타이아웃
        this._discoverTimeoutID = window.setTimeout(
            this._handleDiscoverTimeout.bind(this),
            5000
        ); // 15000 -> 10000 -> 5000으로 변경

        this.sendRemoteRequest("discover", this._peripheralOptions).catch(
            (e) => {
                this._handleRequestError(e);
            }
        );
    }

    // 연결화면에서 "새로고침" 버튼 누르면 실행되는 함수
    // BitblockMini의 scan()함수에서
    scan() {
        console.log("🐲🐲🐲 [bleLink.js] {scan()함수 실행} ...");

        if (this._discoverTimeoutID) {
            window.clearTimeout(this._discoverTimeoutID);
        }

        this._availablePeripherals = {};
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_LIST_UPDATE,
            this._availablePeripherals
        );

        this._discoverTimeoutID = window.setTimeout(
            this._handleDiscoverTimeout.bind(this),
            10000
        ); // 15000 -> 10000으로 변경

        this._stopScan = 0;
        this.sendRemoteRequest("discover", this._peripheralOptions).catch(
            (e) => {
                this._handleRequestError(e);
            }
        );
    }

    stopScan() {
        this._stopScan = 1;
    }

    /**
     * Try connecting to the input peripheral id, and then call the connect
     * callback if connection is successful.
     * @param {number} id - the id of the peripheral to connect to
     */
    connectPeripheral(id) {
        this._connectId = id;

        //F412FA8E9EE5
        let mac = id.toString(16).toUpperCase();
        if (mac.indexOf(":") > 0) {
            mac = mac.replace(/:/g, "");
        }

        this.sendRemoteRequest("connect", { peripheralId: id })
            .then(() => {
                this._connected = true;
                this._connectCallback(id);
                this._runtime.emit(
                    this._runtime.constructor.PERIPHERAL_CONNECTED,
                    id
                );
            })
            .catch((e) => {
                this._handleRequestError(e);
            });
    }

    /**
     * Close the websocket.
     */
    disconnect(address) {
        if (this._connected) {
            this._connected = false;
        }

        if (this._socket.isOpen()) {
            this._socket.close();
        }

        if (this._resetCallback) {
            this._resetCallback(this._connectId);
        }

        if (this._discoverTimeoutID) {
            window.clearTimeout(this._discoverTimeoutID);
        }
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_DISCONNECTED,
            this._connectId
        );
    }

    /**
     * @return {bool} whether the peripheral is connected.
     */
    isConnected() {
        // console.error('bleLink isConnected : ', this._connected);
        return this._connected;
    }

    startNotifications(
        address,
        serviceId,
        characteristicId,
        onCharacteristicChanged = null
    ) {
        console.info("{bleLink}-{startNotifications} serviceId : ", serviceId);

        const params = {
            serviceId,
            characteristicId,
        };

        this._characteristicDidChangeCallback = onCharacteristicChanged;
        return this.sendRemoteRequest("startNotifications", params).catch(
            (err) => {
                this.handleDisconnectError(err);
            }
        );
    }

    read(
        address,
        serviceId,
        characteristicId,
        optStartNotifications = false,
        onCharacteristicChanged = null
    ) {
        console.log("👣👣👣 [bleLink read] address : ", address);

        const params = {
            serviceId,
            characteristicId,
        };
        if (optStartNotifications) {
            params.startNotifications = true;
        }
        if (onCharacteristicChanged) {
            this._characteristicDidChangeCallback = onCharacteristicChanged;
        }

        return this.sendRemoteRequest("read", params).catch((e) => {
            this.handleDisconnectError(e);
        });
    }

    write(
        address,
        serviceId,
        characteristicId,
        message,
        encoding = null,
        withResponse = null
    ) {
        const params = { serviceId, characteristicId, message };
        if (encoding) {
            params.encoding = encoding;
        }
        if (withResponse !== null) {
            params.withResponse = withResponse;
        }

        return this.sendRemoteRequest("write", params).catch((e) => {
            this.handleDisconnectError(e);
        });
    }

    /**
     * Handle a received call from the socket.
     * @param {string} method - a received method label.
     * @param {object} params - a received list of parameters.
     * @return {object} - optional return value.
     */
    didReceiveCall(method, params) {
        switch (method) {
            case "didDiscoverPeripheral":
                // 20240321 블투 연결을 해도 계속 찾는것은 무슨 이유일까?

                console.log("{bleLink.js}-{didReceiveCall} params:", params);

                if (this._stopScan === 1) {
                    return;
                }

                if (this._runtime.SCANNING_DEVICE != this._extensionId) {
                    // 현재 스캔하고 있지않은 디바이스는 검색이 되더라도 리스트 업데이트를 안함!!!
                    return;
                }

                if (params.rssi < -80) {
                    // rssi가 -80보다 작은값을 가지면 건너뜀
                    return;
                }

                //0 kamibot //1 bitblock
                switch (this._type) {
                    case 0:
                        if (!params.name.toLowerCase().startsWith("kami")) {
                            console.log("Not Kamibot  : " + params.name);
                            return;
                        }
                        break;
                    case 1:
                        if (
                            !params.name === "" &&
                            !params.name.toLowerCase().startsWith("bitb")
                        ) {
                            console.log("Not Bitblock : " + params.name);
                            return;
                        }
                        break;
                    default: {
                        return;
                    }
                }

                //F412FA8E9EE5
                let mac = params.peripheralId.toString(16).toUpperCase();
                if (mac.indexOf(":") > 0) {
                    mac = mac.replace(/:/g, "");
                }

                // 왠지 비트블록 보드의 이름이 스크래치링크에서 공백 '' 으로 리턴되서 임시방편으로 넣는다.
                if (
                    params.name === "" ||
                    params.name.toLowerCase().startsWith("bitb")
                ) {
                    params.name = `BitBlock MINI (${mac.substr(
                        8,
                        2
                    )}:${mac.substr(10, 2)})`;
                    params.mac = `${mac.substr(0, 2)}:${mac.substr(
                        2,
                        2
                    )}:${mac.substr(4, 2)}:${mac.substr(6, 2)}:${mac.substr(
                        8,
                        2
                    )}:${mac.substr(10, 2)})`;
                } else if (params.name.toLowerCase().startsWith("kamibot")) {
                    params.name = `${params.name} (${mac.substr(
                        8,
                        2
                    )}:${mac.substr(10, 2)})`;
                    params.mac = `${mac.substr(0, 2)}:${mac.substr(
                        2,
                        2
                    )}:${mac.substr(4, 2)}:${mac.substr(6, 2)}:${mac.substr(
                        8,
                        2
                    )}:${mac.substr(10, 2)})`;
                }

                var peripheral = {
                    name: params.name,
                    rssi: params.rssi,
                    peripheralId: params.peripheralId,
                    mac: params.mac,
                    isConnected: false,
                    index: -1,
                };
                this._availablePeripherals[peripheral.peripheralId] =
                    peripheral;
                this._devices[peripheral.peripheralId] = peripheral;

                let sortedPeripherals = Object.values(
                    this._availablePeripherals
                );
                sortedPeripherals.sort((a, b) => {
                    return b.rssi - a.rssi;
                });

                this._availablePeripherals = {};
                if (Object.keys(sortedPeripherals).length > 0) {
                    this._availablePeripherals[
                        sortedPeripherals[0].peripheralId
                    ] = sortedPeripherals[0];
                }

                this._runtime.emit(
                    this._runtime.constructor.PERIPHERAL_LIST_UPDATE,
                    this._availablePeripherals
                );

                if (this._discoverTimeoutID) {
                    window.clearTimeout(this._discoverTimeoutID);
                }
                break;
            case "userDidPickPeripheral":
                this._availablePeripherals[params.peripheralId] = params;
                this._runtime.emit(
                    this._runtime.constructor.USER_PICKED_PERIPHERAL,
                    this._availablePeripherals
                );
                if (this._discoverTimeoutID) {
                    window.clearTimeout(this._discoverTimeoutID);
                }
                break;
            case "userDidPickPeripheral":
                this._availablePeripherals[params.peripheralId] = params;
                this._runtime.emit(
                    this._runtime.constructor.USER_PICKED_PERIPHERAL,
                    this._availablePeripherals
                );
                if (this._discoverTimeoutID) {
                    window.clearTimeout(this._discoverTimeoutID);
                }
                break;
            case "characteristicDidChange":
                if (this._characteristicDidChangeCallback) {
                    this._characteristicDidChangeCallback(params.message);
                }
                break;
            case "ping":
                return 42;
        }
    }

    // 스크래치 링크의 소켓이 Close되면 자동으로 호출된다.
    handleDisconnectError(/* e */) {
        if (!this._connected) {
            return;
        }
        if (this._resetCallback) {
            this._resetCallback(this._connectId);
        }
        this.disconnect();
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_CONNECTION_LOST_ERROR,
            {
                message: `Scratch lost connection to`,
                extensionId: this._extensionId,
            }
        );
    }

    _handleConnectError() {
        this.disconnect();

        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_CONNECTION_LOST_ERROR,
            {
                message: `Scratch lost connection to`,
                extensionId: this._extensionId,
            }
        );
    }

    _handleRequestError(e) {
        this._runtime.emit(this._runtime.constructor.PERIPHERAL_REQUEST_ERROR, {
            message: `Scratch lost connection to`,
            extensionId: this._extensionId,
        });
    }

    _handleDiscoverTimeout() {
        this._stopScan = 1;
        if (this._discoverTimeoutID) {
            window.clearTimeout(this._discoverTimeoutID);
        }
        this._runtime.emit(this._runtime.constructor.PERIPHERAL_SCAN_TIMEOUT);
    }

    getDevice(pid) {
        const deviceLet = this._devices[pid];
        return deviceLet;
    }

    setConnectDevice(device) {
        this._connectDeviceList[device.index] = device;
        var paramsTest = {
            name: device.name,
            rssi: device.rssi,
            peripheralId: device.id,
            isConnected: device.isConnected,
            index: device.index,
        };

        this._availablePeripherals[paramsTest.peripheralId] = paramsTest;

        if (typeof this._availablePeripherals === "object") {
            console.log(
                "setConnectDevice this._availablePeripherals = " +
                    JSON.stringify(this._availablePeripherals, null, "  ")
            );
        }

        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_LIST_UPDATE,
            this._availablePeripherals
        );
    }

    setDisconnectDevice(device) {
        this._devices = {};
    }
}

module.exports = BLELINK;
