    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    _deleteCanvas() {
        const element = document.getElementById(CANVAS_ID);
        if (element) {
            element.parentNode.removeChild(element);
        }
    }

    _addCanvas(width, height) {
        const canvas = document.createElement("canvas");
        canvas.setAttribute("id", CANVAS_ID);
        canvas.width = width;
        canvas.height = height;
        canvas.style.position = "absolute";
        canvas.style.top = "0";
        canvas.style.left = "0";
        // 2026-03-17 마우스, 터치이벤트 통과하기 
        canvas.style.pointerEvents = 'none';
        canvas.style.zIndex = '100';
        canvas.style.touchAction = 'none';

        // 추가 
        const originalCanvas = this.runtime.renderer._gl.canvas;
        originalCanvas.parentElement.style.position = "relative";
        originalCanvas.parentElement.append(canvas);

        return canvas;
    }

    _clearCanvas() {
        const canvas = document.getElementById(CANVAS_ID);
        if (canvas) {
            // 20250322 willReadFrequently 추가 
            const ctx = canvas.getContext('2d' , { willReadFrequently: true });
            ctx.clearRect(0, 0, canvas.width, canvas.height);
        }
    }

    // 20250226 clearRct함수를 적용하기 
    _getCanvas(width, height) {
        let canvas = document.getElementById(CANVAS_ID);
        if(canvas) {
            if(width == canvas.width) {
                const ctx = canvas.getContext('2d', { willReadFrequently: true });
                ctx.clearRect(0, 0, width, height);
            } else {
                this._deleteCanvas();
                canvas = this._addCanvas(width, height);
            }
            
        } else {
            canvas = this._addCanvas(width, height);
        }
        return canvas;
    }

    _drawMark(location, width, height) {
        const originalCanvas = this.runtime.renderer._gl.canvas;
        const STROKE_STYLE = "#00FF00";
        originalCanvas.parentElement.style.position = "relative";

        const poseCanvas = this._getCanvas(
            originalCanvas.offsetWidth,
            originalCanvas.offsetHeight
        );
        const ctx = poseCanvas.getContext("2d", { willReadFrequently: true });
        ctx.strokeStyle = STROKE_STYLE;
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(location.topLeftCorner.x, location.topLeftCorner.y);
        ctx.lineTo(location.topRightCorner.x, location.topRightCorner.y);
        ctx.lineTo(location.bottomRightCorner.x, location.bottomRightCorner.y);
        ctx.lineTo(location.bottomLeftCorner.x, location.bottomLeftCorner.y);
        ctx.lineTo(location.topLeftCorner.x, location.topLeftCorner.y);
        ctx.stroke();
        ctx.closePath();

        // this._deleteCanvas();
        // originalCanvas.parentElement.append(poseCanvas);

        if (this.detectTimeout) {
            clearTimeout(this.detectTimeout);
        }

        this.detectTimeout = setTimeout(() => {
            this._clearCanvas();
            this.clearResult();
        }, 200);
    }

    _clearMark() {
        this._deleteCanvas();
    }

    _decodeBinaryData(binaryData) {
        const encode = encoding.detect(binaryData);
        if (encode === "UTF16") {
            return new TextDecoder("utf-16").decode(
                Uint16Array.from(binaryData).buffer
            );
        }

        try {
            return new TextDecoder(encode).decode(
                Uint8Array.from(binaryData).buffer
            );
        } catch (e) {
            return "";
        }
    }

    _targetSay(message, off = true) {
        if (this.runtime.targets[1]) {
            this.runtime.emit("SAY", this.runtime.targets[1], "say", message);

            if (off) {
                setTimeout(() => {
                    this.runtime.emit(
                        "SAY",
                        this.runtime.targets[1],
                        "say",
                        ""
                    );
                }, 800);
            }
        }
    }
