    qrStart(args, util) {
        console.error("QR-START !!!");

        const originalCanvas = this.runtime.renderer._gl.canvas;
        // 현재 캠버스 크기의 이미지프레임을 얻는다.
        const frame = this._getFrame(
            originalCanvas.offsetWidth,
            originalCanvas.offsetHeight
        );

        const width = originalCanvas.offsetWidth;
        const height = originalCanvas.offsetHeight;

        const code = jsQR(frame, width, height, {
            inversionAttempts: "attemptBoth",
        });

        console.error("CODE :", code);

        if (code) {
            const delimiter = code.binaryData.indexOf(0); // NULL index
            if (delimiter !== -1) {
                code.binaryData = code.binaryData.slice(0, delimiter);
            }
            this._data = this._decodeBinaryData(code.binaryData);
            this._binaryData = code.binaryData;
            this._drawMark(code.location, width, height);

            console.error(this._data);
            console.error(code.location);

            return this._data;
        } else {
            this._clearCanvas();
            this.clearResult();
            return "";
        }
    }

    arucoStart(args, util) {
        
		const originalCanvas = this.runtime.renderer._gl.canvas;
        const width = originalCanvas.offsetWidth;
        const height = originalCanvas.offsetHeight;

        // 현재 캠버스 크기의 이미지프레임을 얻는다.
        const canvasElement = this._getImageCanvas(
            originalCanvas.offsetWidth,
            originalCanvas.offsetHeight
        );
        let context = canvasElement.getContext("2d", { willReadFrequently: true });
        let imageData = context.getImageData(0, 0, width, height);

        

        const detector = new AR.Detector();
        const markers = detector.detect(imageData);
        console.error("MARKER :", markers);

        if(markers.length > 0) {
            this._drawArucoMark(markers[0].corners, width, height);
            return markers[0].id;
        } else {
            this._clearCanvas();
            return "";
        }
    }

    _drawArucoMark(corners, width, height) {
        const originalCanvas = this.runtime.renderer._gl.canvas;
        const STROKE_STYLE = "#00FF00";
        originalCanvas.parentElement.style.position = "relative";

        const poseCanvas = this._getCanvas(
            originalCanvas.offsetWidth,
            originalCanvas.offsetHeight
        );
        // willReadFrequently 추가 
        const ctx = poseCanvas.getContext("2d", { willReadFrequently: true });
        ctx.save();

        ctx.strokeStyle = STROKE_STYLE;
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(corners[0].x, corners[0].y);
        ctx.lineTo(corners[1].x, corners[1].y);
        ctx.lineTo(corners[2].x, corners[2].y);
        ctx.lineTo(corners[3].x, corners[3].y);
        ctx.lineTo(corners[0].x, corners[0].y);
        ctx.stroke();
        ctx.closePath();

        ctx.restore();
        // this._deleteCanvas();
        // originalCanvas.parentElement.append(poseCanvas);

        if (this.detectTimeout) {
            clearTimeout(this.detectTimeout);
        }

        this.detectTimeout = setTimeout(() => {
            this._clearCanvas();
        }, 200);
    }
    

    clearResult() {
        this._data = "";
        this._binaryData = null;
        this._clearMark();
    }

    // qrSetInterval (args, util){
    //     this._interval = args.INTERVAL * 1000;
    // }

    // qrScanning (args, util){
