const ENGINES = [
    {engine: Engine.MEDIAPIPE, label: 'engineMediapipe'},
    {engine: Engine.TFJS, label: 'engineTfjs'}
];

const REASON_MESSAGE = {
    'gpu-ok': 'reasonGpuOk',
    'gpu-no-detection': 'reasonGpuNoDetection',
    'gpu-mismatch': 'reasonGpuMismatch',
    'gpu-error': 'reasonGpuError',
    'gpu-init-error': 'reasonGpuError'
};

class AdvancedSettingsModal extends React.Component {
    constructor (props) {
        super(props);
        bindAll(this, [
            'handleChangeDelegate',
            'handleRecheck',
            't'
        ]);
        this.state = {
            delegate: AiDelegateSetting.getSetting(),
            recheckRequested: false
        };
    }
    t (key) {
        const LOCALES = ['ko', 'en', 'ja', 'ja-Hira', 'zh-cn', 'zh-tw', 'es', 'fr', 'ru', 'id', 'ms', 'th', 'vi'];
        const locale = LOCALES.includes(this.props.intl.locale) ? this.props.intl.locale : 'en';
        return Message[key][locale];
    }
    handleChangeDelegate (e) {
        AiDelegateSetting.setSetting(e.target.value);
        this.setState({delegate: e.target.value});
    }
    handleRecheck () {
        AiDelegateSetting.clearResolved();
        this.setState({recheckRequested: true});
    }
    hasResolved () {
        return ENGINES.some(({engine}) => AiDelegateSetting.getResolved(engine));
    }
    // 엔진별: 마지막으로 모델을 만든 장치와(자동이면) 점검 결과
    renderStatus () {
        const lines = ENGINES.map(({engine, label}) => {
            const last = AiDelegateSetting.getLast(engine);
            let text = this.t('notLoaded');
            if (last) {
                const source = last.source === 'setting' ? this.t('sourceSetting') : this.t('sourceAuto');
                text = `${last.delegate.toUpperCase()} (${source})`;
                const resolved = AiDelegateSetting.getResolved(engine);
                if (last.source !== 'setting' && resolved && REASON_MESSAGE[resolved.reason]) {
                    text += ` – ${this.t(REASON_MESSAGE[resolved.reason])}`;
                }
            }
            return `${this.t(label)}: ${text}`;
        });
        if (this.state.recheckRequested) lines.push(this.t('recheckDone'));
        return lines.map(line => (
            <div key={line}>{line}</div>
        ));
    }
    render () {
        return (
            <ReactModal
                isOpen
                className={styles.modalContent}
                contentLabel={this.t('title')}
                overlayClassName={styles.modalOverlay}
                onRequestClose={this.props.onRequestClose}
            >
                <div dir={this.props.isRtl ? 'rtl' : 'ltr'}>
                    <Box className={styles.header}>{this.t('title')}</Box>
                    <Box className={styles.body}>
                        <div className={styles.sectionTitle}>{this.t('delegateTitle')}</div>
                        <div className={styles.description}>{this.t('delegateDescription')}</div>
                        {DELEGATES.map(value => (
                            <label
                                className={styles.option}
                                key={value}
                            >
                                <input
                                    checked={this.state.delegate === value}
                                    name="ai-delegate"
                                    type="radio"
                                    value={value}
                                    onChange={this.handleChangeDelegate}
                                />
                                <span className={styles.optionText}>
                                    <span className={styles.optionLabel}>{this.t(value)}</span>
                                    <span className={styles.optionHint}>{this.t(`${value}Hint`)}</span>
                                </span>
                            </label>
                        ))}
                        <div className={styles.status}>{this.renderStatus()}</div>
                        <div className={styles.description}>{this.t('applyNote')}</div>
                        <Box className={styles.buttonRow}>
                            {this.state.delegate === Delegate.AUTO && this.hasResolved() ? (
                                <button
                                    className={styles.secondaryButton}
                                    onClick={this.handleRecheck}
                                >
                                    {this.t('recheck')}
                                </button>
                            ) : null}
                            <button
                                className={styles.primaryButton}
                                onClick={this.props.onRequestClose}
                            >
                                {this.t('close')}
                            </button>
                        </Box>
                    </Box>
                </div>
            </ReactModal>
        );
    }
}

AdvancedSettingsModal.propTypes = {
    intl: intlShape.isRequired,
    isRtl: PropTypes.bool,
    onRequestClose: PropTypes.func.isRequired
};

export default injectIntl(AdvancedSettingsModal);
