/**
 * MediaPipe Tasks(vision) 클라이언트 — handsdetect, facemp, posemp, facemesh 가 함께 쓴다.
 * 추론은 static/workers/vision-task-worker.js (Worker)에서 하고, 결과는 구버전 @mediapipe/* 솔루션의
 * onResults 형식으로 바꿔 돌려준다. 그래서 확장의 좌표 계산과 그리기 코드는 그대로 쓸 수 있다.
 *
 * 구버전 솔루션(@mediapipe/hands 등)은 GPU 추론만 지원해서 일부 GPU(Adreno 830 등)에서 아무것도 검출하지 못한다.
 * 어떤 장치로 추론할지는 고급 설정의 AI 처리 장치(util/ai-delegate-setting.js)를 따른다.
 */
const AiDelegateSetting = require('./ai-delegate-setting');

// static 의 Worker·tasks-vision·모델 파일을 바꾸면 이 값을 올린다. Worker가 같은 쿼리를 라이브러리·wasm·모델 URL에도
// 붙이므로, 웹 배포 후 브라우저가 이전 파일을 캐시에서 계속 쓰지 않는다.
const ASSET_VERSION = '0.10.35-1';
const WORKER_URL = `./static/workers/vision-task-worker.js?v=${ASSET_VERSION}`;
const {Delegate, Engine} = AiDelegateSetting;

// Tasks는 손/얼굴 랜드마크에 visibility: 0 을 넣는다. @mediapipe/drawing_utils는 visibility < 0.5인
// 점과 선을 그리지 않으므로, 구버전처럼 visibility 없이 x, y, z만 넘긴다.
// (포즈는 visibility에 실제 값이 들어오고 구버전도 그 값을 썼으므로 그대로 둔다.)
const xyz = points => points.map(p => ({x: p.x, y: p.y, z: p.z}));

// Tasks의 손 구분(Left/Right)은 같은 거울모드 프레임에서 구버전(@mediapipe/hands)과 반대로 나온다.
// handsdetect의 엄지 판정은 구버전 값 기준이므로 바꿔서 넘긴다. (오른손 주먹이 "손가락 1"로 세어지던 문제)
const LEGACY_HANDEDNESS = {Left: 'Right', Right: 'Left'};

/** 구버전 onResults 형식으로 변환 */
const toLegacyResults = {
    // @mediapipe/hands
    hand: ({result}) => ({
        multiHandLandmarks: result.landmarks.map(xyz),
        multiHandedness: result.handedness.map(categories => ({
            index: categories[0].index,
            score: categories[0].score,
            label: LEGACY_HANDEDNESS[categories[0].categoryName] || categories[0].categoryName
        }))
    }),
    // @mediapipe/face_detection — boundingBox: 픽셀(origin) → 정규화(center), keypoints → landmarks
    face_detector: ({result, width, height}) => ({
        detections: result.detections.map(detection => {
            const box = detection.boundingBox;
            return {
                boundingBox: {
                    xCenter: (box.originX + (box.width / 2)) / width,
                    yCenter: (box.originY + (box.height / 2)) / height,
                    width: box.width / width,
                    height: box.height / height,
                    rotation: 0
                },
                landmarks: detection.keypoints.map(p => ({x: p.x, y: p.y}))
            };
        })
    }),
    // @mediapipe/pose
    pose: ({result}) => ({
        poseLandmarks: result.landmarks[0] || [],
        poseWorldLandmarks: (result.worldLandmarks && result.worldLandmarks[0]) || []
    }),
    // @mediapipe/face_mesh (refineLandmarks: true 와 같은 478점)
    face_landmarker: ({result}) => ({
        multiFaceLandmarks: result.faceLandmarks.map(xyz)
    })
};

class VisionTaskClient {
    /**
     * @param {string} task 'hand' | 'face_detector' | 'pose' | 'face_landmarker'
     */
    constructor (task) {
        this.task = task;
        this._worker = null;
        this._seq = 0;
        this._pending = new Map();
        /** 'gpu' | 'cpu' — init() 성공 후 설정 */
        this.delegate = null;
        /** 모델을 만들 때의 설정 ('auto' | 'gpu' | 'cpu') */
        this.setting = null;
    }

    /**
     * 고급 설정의 AI 처리 장치에 맞춰 모델을 만든다.
     * 'auto'는 손이 있는 내장 이미지로 MediaPipe GPU 추론을 점검해 손을 찾으면 GPU, 못 찾으면 CPU를 쓴다.
     * 점검 결과는 기기에 저장해 모든 MediaPipe 확장이 함께 쓰고, 브라우저(WebView) 버전이 바뀔 때만 다시 점검한다.
     * @param {string} task 'hand' | 'face_detector' | 'pose' | 'face_landmarker'
     * @param {string} logTag 콘솔 로그 접두어
     * @return {Promise<VisionTaskClient>} 실패하면 reject
     */
    static async create (task, logTag) {
        const setting = AiDelegateSetting.getSetting();
        const client = new VisionTaskClient(task);
        try {
            const {delegate, source} = await client._resolveDelegate(setting, logTag);
            try {
                await client._init(delegate);
                AiDelegateSetting.setLast(Engine.MEDIAPIPE, delegate, source);
            } catch (e) {
                // 자동 선택한 GPU를 만들 수 없으면 CPU로 내려간다. 설정으로 고정한 GPU는 실패로 둔다.
                if (delegate !== Delegate.GPU || source === 'setting') throw e;
                console.error(logTag, 'GPU 모델 생성 실패, CPU로 전환', e);
                await client._init(Delegate.CPU);
                AiDelegateSetting.setResolved(Engine.MEDIAPIPE, Delegate.CPU, 'gpu-init-error');
                AiDelegateSetting.setLast(Engine.MEDIAPIPE, Delegate.CPU, 'auto-fallback');
            }
            client.setting = setting;
            console.error(logTag, '모델 로딩 완료', task, client.delegate, `setting=${setting}`);
            return client;
        } catch (e) {
            client.close();
            throw e;
        }
    }

    /**
     * 고급 설정이 모델을 만들 때와 달라졌는지 (달라졌으면 확장이 모델을 다시 만든다)
     * @return {boolean}
     */
    isSettingChanged () {
        return this.setting !== AiDelegateSetting.getSetting();
    }

    async _resolveDelegate (setting, logTag) {
        if (setting !== Delegate.AUTO) {
            return {delegate: setting, source: 'setting'};
        }

        const resolved = AiDelegateSetting.getResolved(Engine.MEDIAPIPE);
        if (resolved) {
            return {delegate: resolved.delegate, source: 'auto-cached'};
        }

        let delegate = Delegate.CPU;
        let reason = 'gpu-no-detection';
        try {
            if (await this._selfTestGpu()) {
                delegate = Delegate.GPU;
                reason = 'gpu-ok';
            }
        } catch (e) {
            reason = 'gpu-error';
            console.error(logTag, 'GPU 점검 실패', e);
        }
        AiDelegateSetting.setResolved(Engine.MEDIAPIPE, delegate, reason);
        console.error(logTag, 'AI 처리 장치 자동 선택', delegate, reason);
        return {delegate, source: 'auto'};
    }

    _ensureWorker () {
        if (this._worker) return this._worker;
        this._worker = new Worker(WORKER_URL);
        this._worker.onmessage = ev => {
            const reply = ev.data;
            const pending = this._pending.get(reply.id);
            if (!pending) return;
            this._pending.delete(reply.id);
            if (reply.ok) pending.resolve(reply);
            else pending.reject(new Error(reply.error));
        };
        this._worker.onerror = ev => {
            this._rejectAll(new Error(`vision task worker error: ${ev.message || 'unknown'}`));
        };
        return this._worker;
    }

    _rejectAll (error) {
        for (const pending of this._pending.values()) pending.reject(error);
        this._pending.clear();
    }

    _request (message, transfer = []) {
        const worker = this._ensureWorker();
        const id = ++this._seq;
        return new Promise((resolve, reject) => {
            this._pending.set(id, {resolve, reject});
            worker.postMessage(Object.assign({id}, message), transfer);
        });
    }

    _selfTestGpu () {
        return this._request({type: 'selftest'}).then(reply => reply.detected);
    }

    _init (delegate) {
        return this._request({type: 'init', task: this.task, delegate: delegate.toUpperCase()}).then(() => {
            this.delegate = delegate;
        });
    }

    /**
     * @param {HTMLCanvasElement} frame 카메라 프레임
     * @return {Promise<object>} 구버전 @mediapipe/* onResults 형식의 결과
     */
    detect (frame) {
        return createImageBitmap(frame)
            .then(bitmap => this._request({type: 'detect', bitmap}, [bitmap]))
            .then(reply => toLegacyResults[this.task](reply));
    }

    close () {
        if (!this._worker) return;
        this._worker.terminate();
        this._worker = null;
        this._rejectAll(new Error('vision task closed'));
    }
}

module.exports = VisionTaskClient;
