    _getImageDimensions(dataURI) {
        return new Promise((resolve, reject) => {
            // 이미지 객체 생성
            const img = new Image();

            // 이미지 로드 완료 시 크기 반환
            img.onload = () => {
                resolve({ width: img.width, height: img.height });
            };

            // 로드 실패 시 에러 반환
            img.onerror = (error) => {
                reject(new Error("Invalid image Data URI"));
            };

            // Data URI를 이미지 소스로 설정
            img.src = dataURI;
        });
    }

    _getImageDataFromDataURI(dataURI) {
        return new Promise((resolve, reject) => {
            // Image 객체 생성
            const img = new Image();

            // 이미지 로드 성공 시 처리
            img.onload = () => {
                // Canvas 생성
                const canvas = document.createElement("canvas");
                // 20250322 willReadFrequently 추가 
                const ctx = canvas.getContext("2d", { willReadFrequently: true });

                // Canvas 크기를 이미지 크기로 설정
                canvas.width = img.width;
                canvas.height = img.height;

                // Canvas에 이미지 그리기
                ctx.drawImage(img, 0, 0);

                // ImageData 얻기
                const imageData = ctx.getImageData(
                    0,
                    0,
                    canvas.width,
                    canvas.height
                );

                // ImageData 반환
                resolve(imageData);
            };

            // 이미지 로드 실패 시 에러 처리
            img.onerror = () =>
                reject(new Error("Failed to load image from Data URI"));

            // Data URI를 Image 객체에 로드
            img.src = dataURI;
        });
    }

    async _createCostume(sprite, name, images) {
        for (let idx = 0; idx < images.length; idx++) {
            const nameClazz = `@${name}_${idx}`;
            console.log(`Index ${idx}: ${nameClazz}`);

            const imageData = await this._getImageDataFromDataURI(images[idx]);

            console.error("------ COSTUMES -----------");
            const costumes = sprite.getCostumes();
            let lengthOfCostumes = costumes.length;

            const originalCostume = costumes[lengthOfCostumes - 1];

            console.error("*** originalCostume *** ", originalCostume);

            const clone = Object.assign({}, originalCostume);
            clone.size = [imageData.width, imageData.height];

            const storage = this.runtime.storage;
            clone.asset = storage.createAsset(
                storage.AssetType.ImageBitmap,
                storage.DataFormat.PNG,
                this.runtime.v2BitmapAdapter.convertDataURIToBinary(
                    images[idx]
                ),
                null,
                true // generate md5
            );
            clone.rotationCenterX = 180;
            clone.rotationCenterY = 180;

            clone.dataFormat = storage.DataFormat.PNG;
            clone.assetId = clone.asset.assetId;
            clone.md5 = `${clone.assetId}.${clone.dataFormat}`;

            clone.skinId = this.runtime.renderer.createBitmapSkin(imageData);
            clone.name = nameClazz;

            sprite.addCostume(clone, lengthOfCostumes + 1);
            // sprite.setCostume(originalCostume + 1);
            // sprite.renameCostume(lengthOfCostumes + 1, nameClazz);

            this.runtime.requestTargetsUpdate2(sprite);
            console.error("clone ->", clone);
        }
    }

