    clearTrainSprite(args, utils) {
        // console.error("utils : ", utils);

        const target = this.runtime.getTargetById(utils.target.id);

        if (!target) {
            // 스프라이트가 없다면..
            this.targetSay(Message.sayNoSprite[this.locale]);
            return false;
        }

        const costumes = target.getCostumes();
        // console.error("target : ", target);
        // console.error("costumes : ", costumes);

        const names = [];

        for (let i = 0; i < costumes.length; i++) {
            names.push(costumes[i].name);
        }

        for (let i = 0; i < names.length; i++) {
            if (names[i].startsWith("@")) {
                const costumeIndex = target.getCostumeIndexByName(names[i]);
                if (costumeIndex < 0) return;
                target.deleteCostume(costumeIndex);
            }
        }

        this.targetSay(Message.sayDeletedAll[this.locale]);
    }

    // Uint8Array를 DataURL로
    _uint8ArrayToDataURI(uint8Array, mimeType = "image/png") {
        return new Promise((resolve, reject) => {
            try {
                // Uint8Array를 Blob으로 변환
                const blob = new Blob([uint8Array], { type: mimeType });

                // FileReader를 사용해 Blob을 DataURI로 변환
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result); // DataURI 반환
                reader.onerror = reject; // 에러 처리

                reader.readAsDataURL(blob);
            } catch (error) {
                reject(error); // 변환 실패 시 에러 처리
            }
        });
    }

    async restoreTrainSprite(args, utils) {
        const target = utils.target;

        if (!target) {
            // 스프라이트가 없다면..
            this.targetSay(Message.sayNoSprite[this.locale]);
            return false;
        }

        const costumes = target.getCostumes();
        // console.error("target : ", target);

        // 클래스 추출
        const classSet = new Set();

        for (let i = 0; i < costumes.length; i++) {
            if (costumes[i].name.startsWith("@")) {
                costumes[i].name.split("_")[0].substring(1);
                classSet.add(costumes[i].name.split("_")[0].substring(1));
            }
        }

        const imageMetadata = [...classSet];
        // console.error("imageMetadata :", imageMetadata);

        const captureSamples = [];
        for (let i = 0; i < imageMetadata.length; i++) {
            captureSamples.push([]);
        }
        // console.error("captureSamples :", captureSamples);

        for (let i = 0; i < costumes.length; i++) {
            if (costumes[i].name.startsWith("@")) {
                const dURI = await this._uint8ArrayToDataURI(
                    costumes[i].asset.data
                );
                // console.error("DATA URI :", dURI);

                const c = costumes[i].name.split("_")[0].substring(1);
                // console.error("c :", c);

                const idx = imageMetadata.indexOf(c);
                // console.error("idx :", idx);

                // console.error("captureSamples[idx] :", captureSamples[idx]);
                // console.error("typeof :", typeof captureSamples[idx]);

                captureSamples[idx].push(dURI);
            }
        }

        // 데이터가 저장되어 있을 경우에만 동작한다.
        if (imageMetadata.length > 0) {
            this.imageMetadata = imageMetadata;
            this.captureSamples = captureSamples;
            this.featureExtractor = null;
            this.imageClassifier = null;

            this.runtime.setTMImageData([
                "image-model",
                this.imageMetadata,
                this.captureSamples,
                this.featureExtractor,
                this.imageClassifier,
            ]);

            this.targetSay(Message.sayRestored[this.locale]);

            this.clearTrainSprite(args, utils);
            // console.error("*** captureSamples *** :", captureSamples);
        } else {
            this.targetSay(Message.sayNoSaved[this.locale]);
        }

        this.targetSay(Message.sayImagesLoaded[this.locale]);

    }

