    async doClassify(args) {
        if (this._classifyInFlight) {
            const blockedElapsed = Date.now() - this._lastClassifyStartedAt;
            const blockedWait = this._classifyMinIntervalMs - blockedElapsed;
            if (blockedWait > 0) await this._sleep(blockedWait);
            return;
        }
        this._classifyInFlight = true;

        try {
            const elapsed = Date.now() - this._lastClassifyStartedAt;
            const wait = this._classifyMinIntervalMs - elapsed;
            if (wait > 0) await this._sleep(wait);
            this._lastClassifyStartedAt = Date.now();

            if (this.imageClassifier == null || this.featureExtractor == null) {
                return false;
            }

            const frame = this._getFrame(360, 360);
            if (!frame) { // 카메라가 꺼져 있으면 프레임이 없다 → 이전 결과를 지운다.
                this.clearResult();
                return;
            }

            const result = await (async () => {
                let classificationResult;

                const squeezedFeatures = tf.tidy(() => {
                    const tensor = tf.browser.fromPixels(frame)
                        .resizeNearestNeighbor([224, 224])
                        .toFloat()
                        .div(127.5)
                        .sub(1)
                        .expandDims(0);

                    const features = this.featureExtractor.predict(tensor);
                    return features.squeeze();
                });

                try {
                    classificationResult = await this.imageClassifier.predictClass(squeezedFeatures);
                } finally {
                    squeezedFeatures.dispose();
                }

                return classificationResult;
            })();

            this._isImageClassifying = true;
            this.confidence = result.confidences[result.label];
            this.label = this.imageMetadata[result.label];
        } catch (e) {
            console.error(LOGTAG, "분류 실패", e);
            this.clearResult();
        } finally {
            this._classifyInFlight = false;
        }
    }

    setContinuousClassify(args) {
        const on = args.ONOFF === "1" || args.ONOFF === 1;

        if (this._classifyInterval) {
            clearInterval(this._classifyInterval);
            this._classifyInterval = null;
        }

        if (!on) return;

        if (this.imageClassifier == null || this.featureExtractor == null) {
            this.targetSay(Message.sayLoadFirst[this.locale]);
            return;
        }

        this._classifyInterval = setInterval(() => {
            this.doClassify();
        }, this._classifyMinIntervalMs);
    }



