import computedStyleToInlineStyle from 'computed-style-to-inline-style';
import ScratchBlocks from 'scratch-blocks';

const SVG_NS = 'http://www.w3.org/2000/svg';
const XML_NS = 'http://www.w3.org/XML/1998/namespace';

// Properties set from CSS rules in scratch-blocks that must be inlined so the
// cloned SVG looks the same once it is rendered as a standalone image.
const INLINE_STYLE_PROPERTIES = [
    'display',
    'fill',
    'fill-opacity',
    'font-family',
    'font-size',
    'font-style',
    'font-weight',
    'opacity',
    'stroke',
    'stroke-linecap',
    'stroke-linejoin',
    'stroke-opacity',
    'stroke-width'
];

// Space left around each script, in workspace pixels.
const SCRIPT_PADDING = 8;

let measureContext = null;
const getMeasureContext = () => {
    if (!measureContext) {
        measureContext = document.createElement('canvas').getContext('2d');
    }
    return measureContext;
};

/**
 * Break text into lines that fit within maxWidth, preferring to break at spaces.
 * @param {string} text the text to wrap
 * @param {string} font a CSS font shorthand used to measure the text
 * @param {number} maxWidth the maximum line width in pixels
 * @return {Array.<string>} the wrapped lines
 */
const wrapText = (text, font, maxWidth) => {
    const ctx = getMeasureContext();
    ctx.font = font;
    const lines = [];
    text.split('\n').forEach(paragraph => {
        let line = '';
        Array.from(paragraph).forEach(ch => {
            const next = line + ch;
            if (line && ctx.measureText(next).width > maxWidth) {
                const lastSpace = line.lastIndexOf(' ');
                if (lastSpace > 0 && ch !== ' ') {
                    lines.push(line.slice(0, lastSpace));
                    line = line.slice(lastSpace + 1) + ch;
                } else {
                    lines.push(line);
                    line = ch === ' ' ? '' : ch;
                }
            } else {
                line = next;
            }
        });
        lines.push(line);
    });
    return lines;
};

/**
 * Comments edit their text in a <textarea> inside a <foreignObject>. Its value is not part of
 * the markup and foreignObject does not render reliably in an SVG image, so draw the text as
 * plain SVG <text> instead.
 * @param {SVGForeignObjectElement} foreignObject the original element, still in the document
 * @return {?SVGTextElement} the replacement, or null if the editor is hidden
 */
const foreignObjectToText = foreignObject => {
    const textarea = foreignObject.querySelector('textarea');
    if (!textarea || window.getComputedStyle(foreignObject).display === 'none') return null;

    const style = window.getComputedStyle(textarea);
    const px = value => parseFloat(value) || 0;
    const fontSize = px(style.fontSize) || 12;
    const lineHeight = px(style.lineHeight) || fontSize * 1.2;
    const left = px(style.marginLeft) + px(style.paddingLeft) + px(style.borderLeftWidth);
    const right = px(style.marginRight) + px(style.paddingRight) + px(style.borderRightWidth);
    const top = px(style.marginTop) + px(style.paddingTop) + px(style.borderTopWidth);
    const bottom = px(style.marginBottom) + px(style.paddingBottom) + px(style.borderBottomWidth);
    const x = px(foreignObject.getAttribute('x'));
    const y = px(foreignObject.getAttribute('y'));
    const width = px(foreignObject.getAttribute('width'));
    const height = px(foreignObject.getAttribute('height'));

    const font = `${style.fontStyle} ${style.fontWeight} ${fontSize}px ${style.fontFamily}`;
    const maxLines = Math.max(1, Math.floor((height - top - bottom) / lineHeight));
    const lines = wrapText(textarea.value, font, width - left - right).slice(0, maxLines);

    const text = document.createElementNS(SVG_NS, 'text');
    text.setAttributeNS(XML_NS, 'xml:space', 'preserve');
    text.setAttribute('style', `fill: ${style.color}; font-family: ${style.fontFamily}; ` +
        `font-size: ${fontSize}px; font-weight: ${style.fontWeight}; font-style: ${style.fontStyle};`);
    if (foreignObject.getAttribute('transform')) {
        text.setAttribute('transform', foreignObject.getAttribute('transform'));
    }
    const baselineOffset = ((lineHeight - fontSize) / 2) + (fontSize * 0.85);
    lines.forEach((line, i) => {
        const tspan = document.createElementNS(SVG_NS, 'tspan');
        tspan.setAttribute('x', x + left);
        tspan.setAttribute('y', y + top + baselineOffset + (i * lineHeight));
        tspan.textContent = line;
        text.appendChild(tspan);
    });
    return text;
};

/**
 * Clone an element of the offscreen workspace for printing.
 * @param {Element} element an SVG group in the offscreen workspace
 * @return {Element} a deep clone with comment editors replaced by SVG text
 */
const cloneForPrint = element => {
    const clone = element.cloneNode(true);
    const originals = element.querySelectorAll('foreignObject');
    const clones = clone.querySelectorAll('foreignObject');
    for (let i = 0; i < originals.length; i++) {
        const replacement = foreignObjectToText(originals[i]);
        if (replacement) {
            clones[i].parentNode.replaceChild(replacement, clones[i]);
        } else {
            clones[i].parentNode.removeChild(clones[i]);
        }
    }
    return clone;
};

/**
 * Collect each script of the loaded workspace: a top block stack with the comments attached to
 * its blocks, or a workspace comment. Ordered top to bottom, as they appear in the workspace.
 * @param {Blockly.WorkspaceSvg} workspace the offscreen workspace
 * @return {Array.<{elements: Array.<Element>, x: number, y: number}>} the scripts
 */
const getScriptElements = workspace => {
    const scripts = workspace.getTopBlocks(false).map(block => {
        const elements = [block.getSvgRoot()];
        block.getDescendants(false).forEach(descendant => {
            const bubble = descendant.comment && descendant.comment.bubble_;
            if (bubble && bubble.bubbleGroup_) elements.push(bubble.bubbleGroup_);
        });
        return Object.assign({elements}, block.getRelativeToSurfaceXY());
    });
    workspace.getTopComments(false)
        .filter(comment => !(comment instanceof ScratchBlocks.ScratchBlockComment))
        .forEach(comment => {
            scripts.push(Object.assign({elements: [comment.getSvgRoot()]}, comment.getRelativeToSurfaceXY()));
        });
    return scripts.sort((a, b) => (a.y - b.y) || (a.x - b.x));
};

/**
 * Render the scripts of each target in a hidden scratch-blocks workspace and clone them into
 * standalone SVG elements. The user's workspace, the VM and the undo stack are not touched.
 * Runs synchronously so nothing else can use ScratchBlocks while the main workspace is swapped.
 * @param {Array.<{name: string, xml: string}>} targets workspace XML of each target to render
 * @return {Array.<{name: string, scripts: Array.<{svg: SVGSVGElement, x: number, y: number,
 *     width: number, height: number}>}>} cloned scripts, in workspace coordinates
 */
const renderTargetScripts = targets => {
    const previousMainWorkspace = ScratchBlocks.mainWorkspace;
    const container = document.createElement('div');
    container.style.cssText = 'position: absolute; left: -10000px; top: 0; ' +
        'width: 2000px; height: 2000px; overflow: hidden; pointer-events: none;';
    document.body.appendChild(container);

    let workspace = null;
    ScratchBlocks.Events.disable();
    try {
        // Blockly.Css.inject replaces the page's scratch-blocks stylesheet on every inject, and
        // `css: false` would leave it empty. With the same media path it is rebuilt unchanged.
        workspace = ScratchBlocks.inject(container, {
            comments: true,
            media: previousMainWorkspace.options.pathToMedia,
            rtl: previousMainWorkspace.RTL,
            scrollbars: true,
            sounds: false,
            toolbox: '<xml style="display: none"></xml>',
            trashcan: false,
            zoom: {controls: false, wheel: false, startScale: 1}
        });

        // Measures the cloned scripts; must be in the document for getBBox().
        const measureSvg = document.createElementNS(SVG_NS, 'svg');
        container.appendChild(measureSvg);

        return targets.map(({name, xml}) => {
            ScratchBlocks.Xml.clearWorkspaceAndLoadFromXml(ScratchBlocks.Xml.textToDom(xml), workspace);
            // Block comments open on a timer after loading; open them now so they are included.
            workspace.getAllBlocks().forEach(block => {
                if (block.comment && block.comment.setVisible) block.comment.setVisible(true);
            });
            [workspace.getCanvas(), workspace.getBubbleCanvas()].forEach(canvas => {
                computedStyleToInlineStyle(canvas, {
                    recursive: true,
                    properties: INLINE_STYLE_PROPERTIES
                });
            });

            const scripts = getScriptElements(workspace).map(({elements}) => {
                const group = document.createElementNS(SVG_NS, 'g');
                elements.forEach(element => group.appendChild(cloneForPrint(element)));
                measureSvg.appendChild(group);
                const box = group.getBBox();
                measureSvg.removeChild(group);

                const svg = document.createElementNS(SVG_NS, 'svg');
                svg.appendChild(group);
                return {
                    svg,
                    x: box.x - SCRIPT_PADDING,
                    y: box.y - SCRIPT_PADDING,
                    width: box.width + (2 * SCRIPT_PADDING),
                    height: box.height + (2 * SCRIPT_PADDING)
                };
            });
            return {name, scripts};
        });
    } finally {
        if (workspace) workspace.dispose();
        document.body.removeChild(container);
        ScratchBlocks.mainWorkspace = previousMainWorkspace;
        ScratchBlocks.Events.enable();
    }
};

export default renderTargetScripts;
