const KEY = "bitblock.camera.swapRedBlue";

const VALUES = {
    ON: "on",
    OFF: "off",
};

// 일부 기기(예: Lenovo TB371FC + Chrome)는 카메라 영상의 빨강/파랑 채널이 뒤바뀌어 들어온다.
// 기기를 자동 판별할 수 없어(데스크톱 모드에서는 모델명이 비어 있음) 디폴트는 끔.
// VideoProvider.getFrame 이 매 프레임 읽으므로 localStorage 대신 모듈 변수에 캐시한다.
let cached = null;

const getCameraSwapRedBlue = () => {
    if (cached === null) {
        cached = false;
        try {
            cached = window.localStorage.getItem(KEY) === VALUES.ON;
        } catch (_) {
            /* private mode / SecurityError */
        }
    }
    return cached;
};

const setCameraSwapRedBlue = (enabled) => {
    cached = !!enabled;
    try {
        window.localStorage.setItem(KEY, cached ? VALUES.ON : VALUES.OFF);
    } catch (_) {
        /* ignore */
    }
};

export {
    getCameraSwapRedBlue,
    setCameraSwapRedBlue,
    KEY as CAMERA_SWAP_RED_BLUE_KEY,
};
