    setLocale() {
        let ret = "en";
        const locale = formatMessage.setup().locale;
        if (AvailableLocales.includes(locale)) {
            ret = locale;
        }
        return ret;
    }

    targetSay(message) {
        if (!this.enableLog) {
            return;
        }

        const target = this.runtime.targets[1];
        if (target) {
            this.runtime.emit("SAY", this.runtime.targets[1], "say", message);
        }

        setTimeout(() => {
            if (target) {
                this.runtime.emit("SAY", this.runtime.targets[1], "say", "");
            }
        }, 1000);
    }

