const ArgumentType = require("../../extension-support/argument-type");
const BlockType = require("../../extension-support/block-type");
const Cast = require("../../util/cast");

const fetchWithTimeout = require("../../util/fetch-with-timeout");
const languageNames = require("scratch-translate-extension-languages");
const formatMessage = require("format-message");

const blockIconURI =
    "data:image/png;base64,";

const {LOCALES: AvailableLocales, withFallback} = require("../common/l10n");
const Message = withFallback({
    ws_connect: { ko: "웹소켓 연결하기[URL]", en: "connect WebSocket [URL]" },
});

class Scratch3JSONBlocks {
    constructor(runtime) {
        this._runtime = runtime;
    }

    _setLocale() {
        const locale = formatMessage.setup().locale;
        return AvailableLocales.includes(locale) ? locale : "en";
    }

    getInfo() {
        this.locale = this._setLocale();
        return {
            id: "jsonfunc",
            name: "JSON",
            blockIconURI: blockIconURI,
            showStatusButton: false,
            color1: "#0FBD8C",
            color2: "#0C946E",
            blocks: [
                {
                    opcode: "commandConnect",
                    text: Message.ws_connect[this.locale],
                    blockType: BlockType.COMMAND,
                    arguments: {
                        URL: {
                            type: ArgumentType.STRING,
                            defaultValue: "ws://localhost:8000/",
                            // defaultValue: "wss://echoserver.redman13.repl.co",
                        },
                    },
                },
            ], // blocks
            menus: {}, // menus
        };
    } // getInfo()

    commandConnect(args) {}
}

module.exports = Scratch3JSONBlocks;
