import renderTargetScripts from './offscreen-workspace';
import {getPrintableTargets, getTargetXml} from './target-xml';
import {inlineImages, renderSvgRegion} from './svg-to-canvas';

// jsPDF is self-hosted in static/lib and loaded on first use: its UMD build has optional
// require() calls (canvg, html2canvas, dompurify) that webpack 4 cannot resolve.
const JSPDF_URL = './static/lib/jspdf-2.5.1/jspdf.umd.min.js';

// A4 portrait, drawn at 200 dpi.
const PAGE_WIDTH_MM = 210;
const PAGE_HEIGHT_MM = 297;
const PX_PER_MM = 200 / 25.4;
const mm = value => Math.round(value * PX_PER_MM);
const PAGE_WIDTH = mm(PAGE_WIDTH_MM);
const PAGE_HEIGHT = mm(PAGE_HEIGHT_MM);
const MARGIN = mm(12);
const HEADER_HEIGHT = mm(14);
const FOOTER_HEIGHT = mm(8);
const SCRIPT_GAP = mm(5);
const CONTENT_TOP = MARGIN + HEADER_HEIGHT;
const CONTENT_BOTTOM = PAGE_HEIGHT - MARGIN - FOOTER_HEIGHT;
const CONTENT_WIDTH = PAGE_WIDTH - (2 * MARGIN);
const CONTENT_HEIGHT = CONTENT_BOTTOM - CONTENT_TOP;
// Page pixels per workspace pixel: one workspace pixel prints as 0.22 mm.
const BLOCK_SCALE = 0.22 * PX_PER_MM;
const FONT_FAMILY = '"Helvetica Neue", Helvetica, Arial, sans-serif';

let jsPdfPromise = null;
const loadJsPdf = () => {
    if (!jsPdfPromise) {
        jsPdfPromise = new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = JSPDF_URL;
            script.onload = () => resolve(window.jspdf.jsPDF);
            script.onerror = () => {
                jsPdfPromise = null;
                document.head.removeChild(script);
                reject(new Error(`Could not load ${JSPDF_URL}`));
            };
            document.head.appendChild(script);
        });
    }
    return jsPdfPromise;
};

/**
 * Lay the scripts out on pages. Each target starts on a new page; scripts are stacked top to
 * bottom and move to the next page when they do not fit. A script taller than a whole page is
 * split across pages. Scripts wider than the page are scaled down to fit.
 * @param {Array.<{name: string, scripts: Array}>} sections rendered scripts of each target
 * @return {Array.<{title: string, slices: Array}>} pages, each with the script regions to draw
 */
const layoutPages = sections => {
    const pages = [];
    sections.forEach(({name, scripts}) => {
        let page = null;
        let pageCount = 0;
        let y = CONTENT_TOP;
        const newPage = () => {
            pageCount++;
            page = {title: pageCount === 1 ? name : `${name} (${pageCount})`, slices: []};
            pages.push(page);
            y = CONTENT_TOP;
        };
        const addSlice = (script, scale, sourceY, sourceHeight) => {
            page.slices.push({
                script,
                scale,
                region: {x: script.x, y: sourceY, width: script.width, height: sourceHeight},
                left: MARGIN,
                top: y
            });
            y += Math.ceil(sourceHeight * scale) + SCRIPT_GAP;
        };

        newPage();
        scripts.forEach(script => {
            const scale = Math.min(BLOCK_SCALE, CONTENT_WIDTH / script.width);
            const height = script.height * scale;
            if (height <= CONTENT_HEIGHT) {
                if (page.slices.length > 0 && y + height > CONTENT_BOTTOM) newPage();
                addSlice(script, scale, script.y, script.height);
                return;
            }
            const sliceHeight = Math.floor(CONTENT_HEIGHT / scale);
            for (let offset = 0; offset < script.height; offset += sliceHeight) {
                if (page.slices.length > 0) newPage();
                addSlice(script, scale, script.y + offset, Math.min(sliceHeight, script.height - offset));
            }
        });
    });
    return pages;
};

/**
 * Draw one page: the target name, its script regions and the page number.
 * @param {{title: string, slices: Array}} page the page layout
 * @param {number} pageNumber 1-based page number
 * @param {number} pageCount total number of pages
 * @return {Promise.<HTMLCanvasElement>} the drawn page
 */
const drawPage = (page, pageNumber, pageCount) => {
    const canvas = document.createElement('canvas');
    canvas.width = PAGE_WIDTH;
    canvas.height = PAGE_HEIGHT;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, PAGE_WIDTH, PAGE_HEIGHT);

    ctx.fillStyle = '#575e75';
    ctx.textBaseline = 'alphabetic';
    ctx.font = `bold ${mm(6)}px ${FONT_FAMILY}`;
    ctx.fillText(page.title, MARGIN, MARGIN + mm(7), CONTENT_WIDTH);
    ctx.fillRect(MARGIN, MARGIN + mm(10), CONTENT_WIDTH, mm(0.3));

    ctx.font = `${mm(3.5)}px ${FONT_FAMILY}`;
    ctx.textAlign = 'center';
    ctx.fillText(`${pageNumber} / ${pageCount}`, PAGE_WIDTH / 2, PAGE_HEIGHT - MARGIN);

    return page.slices.reduce((previous, slice) => previous
        .then(() => renderSvgRegion(slice.script.svg, slice.region, slice.scale))
        .then(image => ctx.drawImage(image, slice.left, slice.top)), Promise.resolve())
        .then(() => canvas);
};

/**
 * Create a PDF of the block programs of the stage and every sprite, one target per page
 * (or more pages when its scripts do not fit). Targets without scripts are skipped.
 * @param {VirtualMachine} vm the VM instance
 * @param {string} stageName name to print for the stage
 * @return {Promise.<?Blob>} the PDF, or null when the project has no blocks
 */
const createBlocksPdf = (vm, stageName) => {
    const targets = getPrintableTargets(vm);
    if (targets.length === 0) return Promise.resolve(null);

    const sections = renderTargetScripts(targets.map(target => ({
        name: target.isStage ? stageName : target.getName(),
        xml: getTargetXml(vm, target)
    })));
    const imageCache = new Map();
    const allScripts = sections.reduce((all, section) => all.concat(section.scripts), []);

    return Promise.all([
        loadJsPdf(),
        Promise.all(allScripts.map(script => inlineImages(script.svg, imageCache)))
    ]).then(([JsPdf]) => {
        const pages = layoutPages(sections);
        const pdf = new JsPdf({orientation: 'portrait', unit: 'mm', format: 'a4', compress: true});
        return pages.reduce((previous, page, index) => previous
            .then(() => drawPage(page, index + 1, pages.length))
            .then(canvas => {
                if (index > 0) pdf.addPage();
                pdf.addImage(canvas, 'PNG', 0, 0, PAGE_WIDTH_MM, PAGE_HEIGHT_MM, `page${index}`, 'FAST');
            }), Promise.resolve())
            .then(() => pdf.output('blob'));
    });
};

export default createBlocksPdf;
