const XLINK_NS = 'http://www.w3.org/1999/xlink';

const readAsDataUrl = blob => new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(blob);
});

/**
 * An SVG drawn as an image cannot load external files, so replace every <image> URL
 * (dropdown arrows, block icons and other scratch-blocks media) with a data URI.
 * @param {SVGSVGElement} svg the SVG to modify in place
 * @param {Map.<string, Promise.<?string>>} cache data URIs by URL, shared between calls
 * @return {Promise} resolves when all images are inlined
 */
const inlineImages = (svg, cache) => Promise.all(Array.from(svg.querySelectorAll('image')).map(image => {
    const href = image.getAttributeNS(XLINK_NS, 'href') || image.getAttribute('href');
    if (!href || href.startsWith('data:')) return Promise.resolve();
    if (!cache.has(href)) {
        cache.set(href, fetch(href)
            .then(response => {
                if (!response.ok) throw new Error(`${response.status} ${href}`);
                return response.blob();
            })
            .then(readAsDataUrl)
            .catch(() => null));
    }
    return cache.get(href).then(dataUrl => {
        if (dataUrl) {
            image.setAttributeNS(XLINK_NS, 'xlink:href', dataUrl);
        } else {
            image.parentNode.removeChild(image);
        }
    });
}));

/**
 * Rasterize a region of an SVG.
 * @param {SVGSVGElement} svg the SVG, with its images already inlined
 * @param {{x: number, y: number, width: number, height: number}} region the area to draw,
 *     in the SVG's user units
 * @param {number} scale canvas pixels per SVG user unit
 * @return {Promise.<HTMLCanvasElement>} the rendered region
 */
const renderSvgRegion = (svg, region, scale) => new Promise((resolve, reject) => {
    const width = Math.max(1, Math.ceil(region.width * scale));
    const height = Math.max(1, Math.ceil(region.height * scale));
    svg.setAttribute('viewBox', `${region.x} ${region.y} ${region.width} ${region.height}`);
    svg.setAttribute('width', width);
    svg.setAttribute('height', height);
    const svgString = new XMLSerializer().serializeToString(svg);

    const image = new Image();
    image.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        canvas.getContext('2d').drawImage(image, 0, 0, width, height);
        resolve(canvas);
    };
    image.onerror = () => reject(new Error('Could not render blocks as an image'));
    image.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svgString)}`;
});

export {
    inlineImages,
    renderSvgRegion
};
