    _targetSay(message, off = true) {
        if (!this.enableLog) {
            return;
        }

        if (this.runtime.targets[1]) {
            this.runtime.emit("SAY", this.runtime.targets[1], "say", message);

            if (off) {
                setTimeout(() => {
                    this.runtime.emit(
                        "SAY",
                        this.runtime.targets[1],
                        "say",
                        ""
                    );
                }, 800);
            }
        }
    }

    // 좌표계를 스크래치 좌표로 변경하기 위한 함수
    // 480 * 360
    _transLocalCoord(val, iMin, iMax, oMin, oMax) {
        // 캔버스의 크기에 맞게 480, 360으로 변경.
        return MathUtil.scale(val, iMin, iMax, oMin, oMax);
    }

    zColor(data) {
        const z = MathUtil.clamp(data.from.z + 0.5, 0, 1);
        return `rgba(0, ${255 * z}, ${255 * (1 - z)}, 1)`;
    }

