    drawFaceLandmarks(canvas, landmarks, options = {}) {
        const pointColor = options.pointColor || 'blue';
        const pointRadius = options.pointRadius || 2;
        const drawLines = options.drawLines || false;
        const lineColor = options.lineColor || 'white';
        const lineWidth = options.lineWidth || 2;
        
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        // ctx.beginPath();
        // 랜드마크 점 그리기
        ctx.fillStyle = pointColor;
        ctx.strokeStyle = lineColor;        // 테두리 색상
        ctx.lineWidth = lineWidth;          // 테두리 두께 (필요에 따라 조정)

        // 랜드마크 점 그리기
        landmarks.forEach(pt => {
            ctx.beginPath();
            ctx.arc(pt.x, pt.y, pointRadius, 0, 2 * Math.PI);
            ctx.fill();

             // 원 외곽선 그리기: 동일한 원의 경로를 다시 정의하고, 흰색 외곽선을 그림
            ctx.beginPath();
            ctx.arc(pt.x, pt.y, pointRadius, 0, 2 * Math.PI);
            ctx.strokeStyle = '#FFFFFF';
            ctx.lineWidth = 2;
            ctx.stroke();
        });
    
        // 옵션이 true인 경우, 예시로 턱선을 연결하여 선을 그림 (68점 모델의 경우 인덱스 0~16)
        // if (drawLines && landmarks.length >= 68) {
        // ctx.strokeStyle = lineColor;
        // ctx.lineWidth = lineWidth;
        // ctx.beginPath();
        // for (let i = 0; i <= 16; i++) {
        //     const pt = landmarks[i];
        //     if (i === 0) {
        //     ctx.moveTo(pt.x, pt.y);
        //     } else {
        //     ctx.lineTo(pt.x, pt.y);
        //     }
        // }
        // ctx.stroke();
        // }
    }

    drawFaceExpressions(canvas, detection, options = {}) {
        // 기본 옵션 설정
        const defaults = {
          boxColor: 'white',
          boxLineWidth: 2,
          textColor: 'white',             // 텍스트 색상: 흰색
          textBackgroundColor: 'black',   // 텍스트 배경 색상: 검은색
          font: '16px sans-serif',
          offset: 10,
          padding: 4                      // 텍스트 주변 여백
        };
        options = Object.assign({}, defaults, options);
      
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        // 얼굴 영역(box) 정보
        const { x, y, width, height } = detection.detection.box;
      
        // 얼굴 영역 테두리 그리기 (옵션 적용)
        ctx.strokeStyle = options.boxColor;
        ctx.lineWidth = options.boxLineWidth;
        ctx.strokeRect(x, y, width, height);
      
        // detection.expressions 객체에서 최대값을 가진 감정 추출
        // getMaxExpression 함수는 { maxKey, maxValue } 객체를 리턴한다고 가정합니다.
        const { maxKey, maxValue } = this.getMaxExpression(detection.expressions);
        // 감정 확률을 백분율로 변환 (소수점 첫째자리)
        const score = (maxValue * 100).toFixed(1);
        // koreanExpressions 매핑 객체를 사용하여 한국어 레이블로 변환 (없으면 영어 그대로 사용)
        // 영상 위 표시 전용 라벨이다. 한국어일 때만 한국어로 바꾸고, 그 밖에는 영어 감정 이름을 그대로 쓴다.
        const label = this.locale === "ko" ? (koreanExpressions[maxKey] || maxKey) : maxKey;
        const text = `${label}: ${score}%`;
      
        // 텍스트 스타일 설정 (옵션 적용)
        ctx.font = options.font;
        // 텍스트 크기를 측정
        const textMetrics = ctx.measureText(text);
        // 실제 높이 정보가 없을 경우 기본값 사용
        const textHeight = textMetrics.actualBoundingBoxAscent
          ? textMetrics.actualBoundingBoxAscent + textMetrics.actualBoundingBoxDescent
          : 16;
        const textWidth = textMetrics.width;
      
        const padding = options.padding;
        // 배경 사각형의 크기에 padding 추가
        const bgWidth = textWidth + padding * 2;
        const bgHeight = textHeight + padding * 2;
      
        // 텍스트를 박스 위에 그릴지 아래에 그릴지 결정
        const textY = y > options.offset + bgHeight ? y - options.offset - bgHeight : y + options.offset;
      
        // 텍스트 배경 사각형 그리기 (검은색)
        ctx.fillStyle = options.textBackgroundColor;
        ctx.fillRect(x, textY, bgWidth, bgHeight);
      
        // 텍스트 그리기 (흰색)
        ctx.fillStyle = options.textColor;
        ctx.textBaseline = 'top';
        ctx.fillText(text, x + padding, textY + padding);
      }
      

    getMaxExpression(expressions) {
        let maxKey = null;
        let maxValue = -Infinity;
        
        for (const key in expressions) {
          if (expressions.hasOwnProperty(key)) {
            if (expressions[key] > maxValue) {
              maxValue = expressions[key];
              maxKey = key;
            }
          }
        }
        
        return { maxKey, maxValue };
    }

