    getArrAverage(i, arr) {
        const sum = arr.reduce(function add(sum, currValue) {
            return sum + currValue[i];
        }, 0);
        const ave = sum / arr.length;
        return ave;
    }

    getXYofNth(args) {
        // 0 : 왼쪽 눈
        // 1 : 오른쪽 눈
        // 2 : 코
        // 3 : 입

        const idx = Cast.toNumber(args.NTH);
        const xy = Cast.toNumber(args.POSXY);

        if (this.faceLandMarks.length > 5) {
            if (idx == 0) {
                const datas = this.faceLandMarks.slice(36, 42);
                if (xy == 0) {
                    const x_ = this.getArrAverage(0, datas);
                    return x_;
                } else {
                    const y_ = this.getArrAverage(1, datas);
                    return y_;
                }
            } else if (idx == 1) {
                const datas = this.faceLandMarks.slice(42, 47);
                if (xy == 0) {
                    const x_ = this.getArrAverage(0, datas);
                    return x_;
                } else {
                    const y_ = this.getArrAverage(1, datas);
                    return y_;
                }
            } else if (idx == 2) {
                // 코
                if (xy == 0) {
                    const x_ = this.faceLandMarks[30][0];
                    return x_;
                } else {
                    const y_ = this.faceLandMarks[30][1];
                    return y_;
                }
            } else if (idx == 3) {
                const datas = this.faceLandMarks.slice(48, 60);
                if (xy == 0) {
                    const x_ = this.getArrAverage(0, datas);
                    return x_;
                } else {
                    const y_ = this.getArrAverage(1, datas);
                    return y_;
                }
            }
        }
        return 0;
    }

