    getLandmark(args, utils) {
        if (this.faceLandMarks.length == 0) {
            return 0;
        }
        let idx = Cast.toNumber(args.LANDMARK);
        idx = MathUtil.clamp(idx, 0, 67);
        const xy = Cast.toNumber(args.POSXY);
        const landmark = this.faceLandMarks[idx];

        if (!landmark) {
            return 0;
        }

        if (xy === 0) {
            return landmark[0];
        }
        return landmark[1];
    }

    getExpression(args) {
        // expressions: Ms
        // angry: 0.007532863412052393
        // disgusted: 0.04662477970123291
        // fearful: 0.0003306788858026266
        // happy: 0.0014871166786178946
        // neutral: 0.2340736985206604
        // sad: 0.7013424038887024
        // surprised: 0.008608409203588963

        if (!this.expressions) {
            return eng2ko("none");
        }

        let sortable = [];
        for (let lbl in this.expressions) {
            sortable.push([lbl, this.expressions[lbl]]);
        }

        sortable.sort(function (a, b) {
            return b[1] - a[1];
        });

        return eng2ko(sortable[0][0]);
    }

