    // async
    async detectFace() {
        try {
            const originalCanvas = this.runtime.renderer._gl.canvas;
            const frame = this._getFrame(
                originalCanvas.offsetWidth,
                originalCanvas.offsetHeight
            );
            if (!frame) return; // 카메라가 꺼져 있으면 프레임이 없다.

            const results = await faceapi
                .detectSingleFace(frame, new faceapi.TinyFaceDetectorOptions())
                .withFaceLandmarks()
                .withFaceExpressions();

            // 얼굴이 없으면 빈 결과로 넘겨 이전 값을 지운다.
            this.onResults(
                results
                    ? faceapi.resizeResults(results, { width: originalCanvas.offsetWidth, height: originalCanvas.offsetHeight })
                    : {}
            );
        } catch (e) {
            console.error(LOGTAG, "감정 분류 실패", e);
        }
    }

    toggleDrawLandmarks(args) {
        


        if (args.ONOFF === "1") {
            if(args.DRAWINGS == "0") {
                this.drawBoundingBox = true;
                this.drawLandmarks = true;
            } else if (args.DRAWINGS == "1") {
                this.drawBoundingBox = true;
            } else {
                this.drawLandmarks = true;
            }
        } else {
            if(args.DRAWINGS == "0") {
                this.drawBoundingBox = false;
                this.drawLandmarks = false;
            } else if (args.DRAWINGS == "1") {
                this.drawBoundingBox = false;
            } else {
                this.drawLandmarks = false;
            }
        }
    }
