import bindAll from "lodash.bindall";
import PropTypes from "prop-types";
import React from "react";
import VM from "scratch-vm";
import { defineMessages, injectIntl, intlShape } from "react-intl";

import extensionLibraryContent from "../lib/libraries/extensions/index.jsx";

import LibraryComponent from "../components/library/library.jsx";
import extensionIcon from "../components/action-menu/icon--sprite.svg";
import log from "../lib/log";

const messages = defineMessages({
    extensionTitle: {
        defaultMessage: "Choose an Extension",
        description: "Heading for the extension library",
        id: "gui.extensionLibrary.chooseAnExtension",
    },
    extensionUrl: {
        defaultMessage: "Enter the URL of the extension",
        description: "Prompt for unoffical extension url",
        id: "gui.extensionLibrary.extensionUrl",
    },
});

class ExtensionLibrary extends React.PureComponent {
    constructor(props) {
        super(props);
        bindAll(this, ["handleItemSelect", "handleContextMenu"]);
    }

    componentDidMount() {
        document.addEventListener("contextmenu", this.handleContextMenu, true);
    }

    componentWillUnmount() {
        document.removeEventListener("contextmenu", this.handleContextMenu, true);
    }

    handleContextMenu(e) {
        if (this.props.visible) {
            e.preventDefault();
        }
    }

    // ks.moon
    handleItemSelect(item) {
        // const id = item.extensionId;
        let id = item.extensionId;
        let url = item.extensionURL ? item.extensionURL : id;

        if (!item.disabled && !id) {
            // eslint-disable-next-line no-alert
            url = prompt(this.props.intl.formatMessage(messages.extensionUrl));
            if (url) {
                id = url;
            }
        }

        // log.error(`######### 3 id:${id}, url:${url}`);
        // id:undefined, url:null
        if (typeof id === "undefined" || url === null) {
            // log.error(`@@@ id:${id}, url:${url}`);
            return;
        }

        if (id && !item.disabled) {
            if (this.props.vm.extensionManager.isExtensionLoaded(url)) {
                // ks.moon
                // 확장을 삭제하는 처리가 들어가면 된다.
                log.error(
                    "🐶🐶🐶🐶🐶 [extension-library] 확장 이미. url =>",
                    url,
                    "  id=>",
                    id
                );
                this.props.onCategorySelected(id);
            } else {
                this.props.vm.extensionManager
                    .loadExtensionURL(url)
                    .then(() => {
                        this.props.onCategorySelected(id);
                    });
            }
        }
    }
    render() {
        const extensionLibraryThumbnailData = extensionLibraryContent.map(
            (extension) => ({
                rawURL: extension.iconURL || extensionIcon,
                ...extension,
            })
        );
        return (
            <LibraryComponent
                data={extensionLibraryThumbnailData}
                filterable={false}
                id="extensionLibrary"
                title={this.props.intl.formatMessage(messages.extensionTitle)}
                visible={this.props.visible}
                onItemSelected={this.handleItemSelect}
                onRequestClose={this.props.onRequestClose}
            />
        );
    }
}

ExtensionLibrary.propTypes = {
    intl: intlShape.isRequired,
    onCategorySelected: PropTypes.func,
    onRequestClose: PropTypes.func,
    visible: PropTypes.bool,
    vm: PropTypes.instanceOf(VM).isRequired, // eslint-disable-line react/no-unused-prop-types
};

export default injectIntl(ExtensionLibrary);
