/**
 * 포즈 분류(TM)용 격리 실행 환경.
 * @teachablemachine/pose@0.8.6 은 tfjs 1.x 전용이라 메인 페이지의 tfjs 4.22 엔진에서는 동작하지 않는다.
 * 숨은 iframe(scratch-gui/static/lib/tmpose-sandbox/sandbox.html)에서 tfjs 1.3.1 과 함께 실행해
 * 메인 페이지의 전역 tf 를 쓰는 다른 확장에는 영향을 주지 않는다.
 * 처음 모델을 불러올 때 한 번만 iframe 을 만든다.
 */
const SANDBOX_URL = './static/lib/tmpose-sandbox/sandbox.html';
const READY_TIMEOUT_MS = 20000;

let sandboxPromise = null;

const createSandbox = () => new Promise((resolve, reject) => {
    const iframe = document.createElement('iframe');
    iframe.src = SANDBOX_URL;
    iframe.setAttribute('aria-hidden', 'true');
    iframe.tabIndex = -1;
    // display:none 이면 일부 브라우저에서 WebGL 이 제한될 수 있어 화면 밖 1px 로 둔다.
    iframe.style.cssText = 'position:fixed;left:-10px;top:-10px;width:1px;height:1px;border:0;opacity:0;pointer-events:none;';

    const timer = setTimeout(() => {
        reject(new Error('tmpose sandbox did not become ready'));
    }, READY_TIMEOUT_MS);

    iframe.onload = () => {
        const sandbox = iframe.contentWindow && iframe.contentWindow.TMPoseSandbox;
        clearTimeout(timer);
        if (sandbox) {
            resolve(sandbox);
        } else {
            reject(new Error('tmpose sandbox failed to load its libraries'));
        }
    };
    document.body.appendChild(iframe);
});

const getTmPoseSandbox = () => {
    if (!sandboxPromise) {
        sandboxPromise = createSandbox().catch(error => {
            sandboxPromise = null; // 다음 모델 다운로드 때 다시 시도한다.
            throw error;
        });
    }
    return sandboxPromise;
};

module.exports = getTmPoseSandbox;
