/* eslint-disable */
// Web Bluetooth API 기반 BLE 어댑터.
// BLELINK(bleLink.js)와 동일한 외부 인터페이스를 제공하여 Scratch Link 대신 브라우저 내장 BLE로 동작한다.
// - scan(): navigator.bluetooth.requestDevice()로 브라우저 네이티브 피커를 띄우고, 선택된 단일 디바이스를
//   PERIPHERAL_LIST_UPDATE 이벤트로 기존 UI에 흘려보낸다(= "UI 간소화": 리스트에 타일 1개만 표시).
// - connectPeripheral / read / write / startNotifications: GATT를 통해 직접 처리.
// - read/characteristicvaluechanged 콜백은 기존 BLELINK와 호환되도록 base64 문자열로 전달한다.
// 현재 Bitblock(type=1)과 Kamibot(type=0) 공용 어댑터.

const Base64Util = require("../util/base64-util");

class BLEWEBBLUETOOTH {
    /**
     * @param {Runtime} runtime
     * @param {string} extensionId
     * @param {object} peripheralOptions - BLELINK가 사용하던 것과 동일 형식: { filters: [{ services: [uuid] }] }
     * @param {function} connectCallback - 연결 성공 콜백
     * @param {function} resetCallback - 리셋/연결 해제 콜백
     * @param {number} type - 0: Kamibot, 1: Bitblock
     */
    constructor(
        runtime,
        extensionId,
        peripheralOptions,
        connectCallback,
        resetCallback,
        type
    ) {
        this._runtime = runtime;
        this._extensionId = extensionId;
        this._peripheralOptions = peripheralOptions || {};
        this._connectCallback = connectCallback;
        this._resetCallback = resetCallback;
        this._type = type;

        this._availablePeripherals = {};
        this._devices = {};
        this._btDevices = {};
        this._characteristics = {};

        this._server = null;
        this._connected = false;
        this._connecting = false;
        this._connectId = null;
        this._characteristicDidChangeCallback = null;
        this._discoverTimeoutID = null;
        this._stopScan = 0;
        this._gattDisconnectHandler = null;
        // Web Bluetooth 는 동일 device 에 대해 동시 GATT 작업을 허용하지 않는다
        // (NetworkError "GATT operation already in progress"). 모든 read/write/
        // startNotifications/getPrimaryService 호출을 FIFO 로 직렬화한다.
        this._opChain = Promise.resolve();

        // BLELINK는 WebSocket open 후 자동으로 requestPeripheral을 호출한다.
        // Web Bluetooth는 동기적으로 유저 제스처에서 호출해야 하므로,
        // 생성자에서 즉시 피커를 띄운다 (scan()이 유저 클릭 컨텍스트에서 호출된 경우에만 동작).
        this.requestPeripheral();
    }

    // ========== BLELINK 호환 인터페이스 ==========

    // BLELINK에서는 WebSocket open에 반응해서 실행되지만, 여기서는 생성자와 scan()에서 직접 호출된다.
    requestPeripheral() {
        if (typeof navigator === "undefined" || !navigator.bluetooth) {
            console.error(
                "🔥 [bleWebBluetooth] Web Bluetooth API not available. HTTPS/localhost + Chromium 필요."
            );
            this._handleRequestError(
                new Error("Web Bluetooth API not available")
            );
            return;
        }

        this._availablePeripherals = {};
        this._stopScan = 0;

        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
        }
        // 브라우저 피커는 사용자가 닫을 때까지 열려 있음. 넉넉히 30초로 잡아두고,
        // 피커가 이전에 닫히면 정상 경로에서 clear됨.
        this._discoverTimeoutID = setTimeout(
            this._handleDiscoverTimeout.bind(this),
            30000
        );

        const options = this._buildRequestDeviceOptions();

        navigator.bluetooth
            .requestDevice(options)
            .then((device) => this._handleDevicePicked(device))
            .catch((err) => {
                if (this._discoverTimeoutID) {
                    clearTimeout(this._discoverTimeoutID);
                    this._discoverTimeoutID = null;
                }
                // NotFoundError: 사용자가 피커에서 취소한 경우 — SCAN_TIMEOUT 이벤트로 UI에 "새로고침" 버튼 노출
                if (err && err.name === "NotFoundError") {
                    this._runtime.emit(
                        this._runtime.constructor.PERIPHERAL_SCAN_TIMEOUT
                    );
                } else {
                    console.error(
                        "🔥 [bleWebBluetooth] requestDevice error:",
                        err
                    );
                    this._handleRequestError(err);
                }
            });
    }

    // "새로고침" 버튼에서 호출 — 다시 피커 오픈
    scan() {
        console.log("🐲 [bleWebBluetooth] scan() — 브라우저 피커 재호출");

        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
            this._discoverTimeoutID = null;
        }

        this._availablePeripherals = {};
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_LIST_UPDATE,
            this._availablePeripherals
        );

        this.requestPeripheral();
    }

    stopScan() {
        this._stopScan = 1;
        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
            this._discoverTimeoutID = null;
        }
    }

    connectPeripheral(id) {
        // 중복 호출 방어 — 같은 id로 이미 연결 중이거나 연결되어 있으면 무시.
        // (상위(blocks.jsx + ConnectionModal 잔여 리스너)에서 동일 id로 두 번 호출되는 경우가 관측됨.
        //  두 번째 호출이 첫 번째 GATT.connect 완료 전에 들어오면 Web Bluetooth는
        //  'NetworkError: GATT operation already in progress'를 throw하고, 잘못 해석하면
        //  연결된 세션 자체를 끊어버리게 된다.)
        if (this._connected && this._connectId === id) {
            console.info(
                "🟡 [bleWebBluetooth] connectPeripheral: already connected, ignoring duplicate",
                id
            );
            return;
        }
        if (this._connecting && this._connectId === id) {
            console.info(
                "🟡 [bleWebBluetooth] connectPeripheral: already connecting, ignoring duplicate",
                id
            );
            return;
        }

        this._connectId = id;
        const device = this._btDevices[id];

        if (!device) {
            console.error(
                "🔥 [bleWebBluetooth] connectPeripheral: device not found for id:",
                id
            );
            this._handleRequestError(new Error("device not found"));
            return;
        }

        if (this._gattDisconnectHandler) {
            device.removeEventListener(
                "gattserverdisconnected",
                this._gattDisconnectHandler
            );
        }
        this._gattDisconnectHandler =
            this._handleGattDisconnected.bind(this, id);
        device.addEventListener(
            "gattserverdisconnected",
            this._gattDisconnectHandler
        );

        this._connecting = true;
        device.gatt
            .connect()
            .then((server) => {
                this._server = server;
                this._connected = true;
                this._connecting = false;
                this._characteristics = {};
                if (this._connectCallback) {
                    this._connectCallback(id);
                }
                this._runtime.emit(
                    this._runtime.constructor.PERIPHERAL_CONNECTED,
                    id
                );
            })
            .catch((err) => {
                this._connecting = false;
                console.error(
                    "🔥 [bleWebBluetooth] gatt.connect error:",
                    err
                );
                this._handleRequestError(err);
            });
    }

    disconnect(/* address */) {
        if (this._connected) {
            this._connected = false;
        }
        this._connecting = false;
        this._opChain = Promise.resolve();

        try {
            if (this._server && this._server.connected) {
                this._server.disconnect();
            }
        } catch (e) {
            // noop
        }

        this._characteristics = {};

        if (this._resetCallback) {
            this._resetCallback(this._connectId);
        }

        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
            this._discoverTimeoutID = null;
        }

        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_DISCONNECTED,
            this._connectId
        );
    }

    isConnected() {
        return this._connected;
    }

    // 모든 GATT 작업을 FIFO 로 직렬화. 이전 작업의 성공/실패와 무관하게 다음 작업이 진행되도록
    // 체인의 reject 는 여기서 흡수한다(상위 caller 는 별도로 자기 then/catch 사용).
    _enqueue(fn) {
        const next = this._opChain.then(fn, fn);
        this._opChain = next.catch(() => {});
        return next;
    }

    startNotifications(
        address,
        serviceId,
        characteristicId,
        onCharacteristicChanged = null
    ) {
        this._characteristicDidChangeCallback = onCharacteristicChanged;

        return this._enqueue(() =>
            this._getCharacteristic(serviceId, characteristicId)
                .then((ch) => ch.startNotifications().then(() => ch))
                .then((ch) => {
                    this._attachValueChangedListener(ch);
                })
        ).catch((err) => {
            this._handleOperationError(err, "startNotifications");
        });
    }

    read(
        address,
        serviceId,
        characteristicId,
        optStartNotifications = false,
        onCharacteristicChanged = null
    ) {
        if (onCharacteristicChanged) {
            this._characteristicDidChangeCallback = onCharacteristicChanged;
        }

        return this._enqueue(() =>
            this._getCharacteristic(serviceId, characteristicId)
                .then((ch) => {
                    if (optStartNotifications) {
                        return ch.startNotifications().then(() => {
                            this._attachValueChangedListener(ch);
                            return ch.readValue();
                        });
                    }
                    return ch.readValue();
                })
                .then((dataView) => {
                    if (!dataView) return null;
                    const bytes = new Uint8Array(
                        dataView.buffer,
                        dataView.byteOffset,
                        dataView.byteLength
                    );
                    return Base64Util.uint8ArrayToBase64(bytes);
                })
        ).catch((err) => {
            this._handleOperationError(err, "read");
        });
    }

    write(
        address,
        serviceId,
        characteristicId,
        message,
        encoding = null,
        withResponse = null
    ) {
        return this._enqueue(() =>
            this._getCharacteristic(serviceId, characteristicId)
            .then((ch) => {
                let bytes;
                if (encoding === "base64") {
                    bytes = Base64Util.base64ToUint8Array(message);
                } else if (message instanceof ArrayBuffer) {
                    bytes = new Uint8Array(message);
                } else if (message instanceof Uint8Array) {
                    bytes = message;
                } else if (typeof message === "string") {
                    bytes = new TextEncoder().encode(message);
                } else {
                    bytes = new Uint8Array(message);
                }

                // characteristic 속성 기반으로 가능한 write 모드 결정.
                // 호출자(withResponse) 선호도를 존중하되 지원하지 않으면 폴백.
                const props = ch.properties || {};
                const canWithResponse = !!props.write;
                const canWithoutResponse = !!props.writeWithoutResponse;

                let useWithoutResponse;
                if (withResponse === false) {
                    useWithoutResponse = canWithoutResponse || !canWithResponse;
                } else if (withResponse === true) {
                    useWithoutResponse = !canWithResponse && canWithoutResponse;
                } else {
                    // 미지정: 장치가 지원하는 쪽 선호(With-Response 우선)
                    useWithoutResponse = !canWithResponse && canWithoutResponse;
                }

                if (useWithoutResponse) {
                    if (typeof ch.writeValueWithoutResponse === "function") {
                        return ch.writeValueWithoutResponse(bytes);
                    }
                    return ch.writeValue(bytes);
                }
                if (typeof ch.writeValueWithResponse === "function") {
                    return ch.writeValueWithResponse(bytes);
                }
                return ch.writeValue(bytes);
            })
        ).catch((err) => {
            this._handleOperationError(err, "write");
        });
    }

    getDevice(pid) {
        return this._devices[pid];
    }

    // BLELINK 호환: 연결 성공 후 index.js에서 호출되나, Web Bluetooth 경로에서는 부가 처리 불필요
    setConnectDevice(/* device */) {
        // noop
    }

    setDisconnectDevice(/* device */) {
        this._devices = {};
    }

    // ========== 내부 헬퍼 ==========

    _buildRequestDeviceOptions() {
        // peripheralOptions는 BLELINK가 받던 것과 동일: { filters: [{ services: [uuid] }] }
        const incomingServices = [];
        if (
            this._peripheralOptions &&
            Array.isArray(this._peripheralOptions.filters)
        ) {
            for (const f of this._peripheralOptions.filters) {
                if (Array.isArray(f.services)) {
                    for (const s of f.services) {
                        if (incomingServices.indexOf(s) < 0) {
                            incomingServices.push(s);
                        }
                    }
                }
            }
        }

        // Bitblock MINI은 이름이 공백으로 광고되는 경우가 있어 services 필터만 사용.
        // Kamibot은 namePrefix 'kami'로 필터.
        const filters = [];
        const nameFilter =
            this._peripheralOptions && this._peripheralOptions.nameFilter;

        if (
            nameFilter &&
            Array.isArray(nameFilter.prefixes) &&
            nameFilter.prefixes.length > 0
        ) {
            // 실제 광고명 케이싱 기반 접두어(+선택적 번호)로 필터.
            for (const p of nameFilter.prefixes) {
                if (nameFilter.hasNumber) {
                    // 번호 지정 시 완전 일치(예: "BitBlock 7")로 네이티브 피커를 좁힌다.
                    filters.push({ name: p });
                } else {
                    filters.push({ namePrefix: p });
                }
            }
            // 번호가 없을 때만 services 광역 필터를 추가해 해당 타입 기기 가시성 보장.
            // 번호가 있으면 그 번호로 좁히기 위해 services 필터를 제외한다.
            if (!nameFilter.hasNumber && incomingServices.length > 0) {
                filters.push({ services: incomingServices });
            }
        } else {
            if (incomingServices.length > 0) {
                filters.push({ services: incomingServices });
            }
            if (this._type === 1) {
                // Bitblock
                filters.push({ namePrefix: "Bitb" });
                filters.push({ namePrefix: "BitB" });
                filters.push({ namePrefix: "bitb" });
            } else if (this._type === 0) {
                // Kamibot
                filters.push({ namePrefix: "kami" });
                filters.push({ namePrefix: "Kami" });
                filters.push({ namePrefix: "KAMI" });
            }
        }

        // GATT 접근 시 사용할 서비스는 optionalServices에 명시.
        const optionalServices = [
            "6e400000-b5a3-f393-e0a9-e50e24dcca9e",
            "6e400001-b5a3-f393-e0a9-e50e24dcca9e",
        ];
        for (const s of incomingServices) {
            if (optionalServices.indexOf(s) < 0) optionalServices.push(s);
        }

        if (filters.length === 0) {
            // 어떤 필터도 만들 수 없는 예외 케이스 — 모든 디바이스 허용
            return {
                acceptAllDevices: true,
                optionalServices: optionalServices,
            };
        }

        return {
            filters: filters,
            optionalServices: optionalServices,
        };
    }

    _handleDevicePicked(device) {
        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
            this._discoverTimeoutID = null;
        }

        if (this._stopScan === 1) {
            return;
        }

        if (this._runtime.SCANNING_DEVICE != this._extensionId) {
            return;
        }

        const peripheralId = device.id;
        let displayName = device.name || "";

        const nameFilter =
            this._peripheralOptions && this._peripheralOptions.nameFilter;

        if (
            nameFilter &&
            Array.isArray(nameFilter.matches) &&
            nameFilter.matches.length > 0
        ) {
            // 선택 후 최종 판정: 대소문자 무시(네이티브 피커가 못 하는 부분).
            const nm = displayName.toLowerCase();
            if (nameFilter.hasNumber) {
                // 번호가 지정된 경우 이름이 "키워드 번호"와 완전히 일치해야 함.
                const matched = nameFilter.matches.some((m) => nm === m);
                if (!matched) {
                    console.log("Not matched name filter : " + displayName);
                    return;
                }
            } else {
                // 빈 값(번호 없음): 이름이 비어있으면(서비스로 매칭된 기기) 허용,
                // 이름이 있으면 키워드 포함 여부로 판정.
                const matched = nameFilter.matches.some((m) => nm.indexOf(m) >= 0);
                if (nm !== "" && !matched) {
                    console.log("Not matched name filter : " + displayName);
                    return;
                }
            }
            if (displayName === "") {
                const tail = this._tailOfId(peripheralId);
                displayName = `${nameFilter.base} (${tail})`;
            }
        } else if (this._type === 1) {
            // bleLink.js의 이름 가공과 맞추기: type별로 표시명 보정
            // Bitblock — 이름이 공백이거나 bitb로 시작하면 "BitBlock MINI (XX:YY)" 형식으로
            if (
                displayName === "" ||
                displayName.toLowerCase().startsWith("bitb")
            ) {
                const tail = this._tailOfId(peripheralId);
                displayName = `BitBlock MINI (${tail})`;
            }
        } else if (this._type === 0) {
            if (displayName.toLowerCase().startsWith("kami")) {
                const tail = this._tailOfId(peripheralId);
                displayName = `${displayName} (${tail})`;
            } else {
                // 이름이 kami로 시작하지 않으면 Kamibot 아님 — 무시
                console.log("Not Kamibot : " + displayName);
                return;
            }
        }

        const peripheral = {
            name: displayName,
            // Web Bluetooth API는 RSSI를 노출하지 않음. UI 정렬용 더미 값.
            rssi: -50,
            peripheralId: peripheralId,
            // 카미봇 index.js의 getKamibotBle / KamibotBle.disconnect 등은 _device.id / _connectDevice.id로
            // 주소 비교를 수행한다. bleLink.js(Scratch Link) 경로와 호환되도록 id 필드도 함께 세팅한다.
            id: peripheralId,
            mac: "",
            isConnected: false,
            index: -1,
        };

        this._availablePeripherals[peripheralId] = peripheral;
        this._devices[peripheralId] = peripheral;
        this._btDevices[peripheralId] = device;

        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_LIST_UPDATE,
            this._availablePeripherals
        );
    }

    _tailOfId(id) {
        // Web Bluetooth의 device.id는 base64-ish 문자열. 짧은 표시용 tail 4자.
        if (!id || typeof id !== "string") return "??";
        const clean = id.replace(/[^A-Za-z0-9]/g, "");
        if (clean.length >= 4) {
            return `${clean.substr(clean.length - 4, 2)}:${clean.substr(
                clean.length - 2,
                2
            )}`;
        }
        return clean;
    }

    _getCharacteristic(serviceId, characteristicId) {
        const key = `${serviceId}::${characteristicId}`;
        if (this._characteristics[key]) {
            return Promise.resolve(this._characteristics[key]);
        }
        if (!this._server || !this._server.connected) {
            return Promise.reject(new Error("gatt server not connected"));
        }

        // Kamibot(type=0)의 index.js 는 모든 GATT 호출에 service1(6e400000)을 지정하지만,
        // 실제 펌웨어에서 Nordic UART 문자 특성은 service2(6e400001) 아래에 위치한 경우가 있다.
        // Scratch Link(네이티브) 경로에서는 내부 맵핑이 있어 동작했으나, Web Bluetooth 직접
        // 접근에서는 getPrimaryService 가 실패하거나 특성 조회가 안 되어 GATT 가 조기 종료되는
        // 문제가 있었다. 요청 service → 실패 시 다른 알려진 서비스 순으로 시도한다.
        const candidateServices = [serviceId];
        const fallbackServices = [
            "6e400000-b5a3-f393-e0a9-e50e24dcca9e",
            "6e400001-b5a3-f393-e0a9-e50e24dcca9e",
        ];
        for (const s of fallbackServices) {
            if (candidateServices.indexOf(s) < 0) candidateServices.push(s);
        }

        const tryIndex = (idx, lastErr) => {
            if (idx >= candidateServices.length) {
                return Promise.reject(
                    lastErr ||
                        new Error(
                            `characteristic ${characteristicId} not found in any known service`
                        )
                );
            }
            return this._server
                .getPrimaryService(candidateServices[idx])
                .then((service) => service.getCharacteristic(characteristicId))
                .then((ch) => {
                    this._characteristics[key] = ch;
                    if (candidateServices[idx] !== serviceId) {
                        console.info(
                            `🟡 [bleWebBluetooth] characteristic ${characteristicId} resolved via fallback service ${candidateServices[idx]} (requested ${serviceId})`
                        );
                    }
                    return ch;
                })
                .catch((err) => tryIndex(idx + 1, err));
        };

        return tryIndex(0, null);
    }

    _attachValueChangedListener(ch) {
        if (ch.__bbListenerAttached) return;
        ch.__bbListenerAttached = true;
        ch.addEventListener("characteristicvaluechanged", (event) => {
            const dataView = event.target.value;
            if (!dataView) return;
            const bytes = new Uint8Array(
                dataView.buffer,
                dataView.byteOffset,
                dataView.byteLength
            );
            // BLELINK는 base64 문자열을 콜백에 전달하므로 동일 형식 유지
            const base64 = Base64Util.uint8ArrayToBase64(bytes);
            if (this._characteristicDidChangeCallback) {
                this._characteristicDidChangeCallback(base64);
            }
        });
    }

    _handleGattDisconnected(id /* , event */) {
        console.warn(
            `[bleWebBluetooth] GATT disconnected (device/GATT 측 끊김) id=${id} connected=${this._connected}`
        );
        if (!this._connected) return;
        this._connected = false;
        // characteristic 객체에 남은 리스너-부착 플래그를 해제한다.
        // 재연결 시 브라우저가 동일 characteristic 객체를 돌려주더라도
        // _attachValueChangedListener 가 characteristicvaluechanged 리스너를
        // 다시 붙일 수 있도록 하기 위함.
        Object.keys(this._characteristics).forEach((key) => {
            const ch = this._characteristics[key];
            if (ch && ch.__bbListenerAttached) {
                delete ch.__bbListenerAttached;
            }
        });
        this._characteristics = {};

        if (this._resetCallback) {
            this._resetCallback(id);
        }
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_CONNECTION_LOST_ERROR,
            {
                message: "Scratch lost connection to",
                extensionId: this._extensionId,
            }
        );
    }

    handleDisconnectError(err) {
        console.warn(
            `[bleWebBluetooth] handleDisconnectError (app-레벨 단절 처리) connected=${this._connected}`,
            err && err.name,
            err && err.message
        );
        if (!this._connected) return;
        if (this._resetCallback) {
            this._resetCallback(this._connectId);
        }
        this.disconnect();
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_CONNECTION_LOST_ERROR,
            {
                message: "Scratch lost connection to",
                extensionId: this._extensionId,
            }
        );
    }

    // read/write 중 발생한 에러를 처리.
    // GATT 단절이 분명한 경우에만 disconnect 플로우를 태우고, 그 외 전송/프로토콜 에러는 로그만.
    // (기존에는 모든 에러가 disconnect를 트리거해서, 연결 직후 초기화 write 1건 실패만으로도
    //  전체 세션이 끊기는 문제가 있었다.)
    _handleOperationError(err, operation) {
        if (!err) return;
        const name = (err && err.name) || "";
        const msg = (err && err.message) || String(err);
        // "GATT operation already in progress" 같은 일시적 NetworkError 는
        // 단절이 아니므로 disconnect 플로우로 태우지 않는다. 실제 단절을 나타내는
        // 구체적 메시지 혹은 서버 상태만 단절로 판정.
        const serverDisconnected =
            this._server && this._server.connected === false;
        const disconnected =
            serverDisconnected ||
            /gatt server is disconnected/i.test(msg) ||
            /gatt server not connected/i.test(msg);

        if (disconnected) {
            this.handleDisconnectError(err);
            return;
        }
        console.warn(
            `[bleWebBluetooth] ${operation} error (연결 유지):`,
            name || err,
            msg
        );
    }

    _handleRequestError(/* err */) {
        this._runtime.emit(
            this._runtime.constructor.PERIPHERAL_REQUEST_ERROR,
            {
                message: "Scratch lost connection to",
                extensionId: this._extensionId,
            }
        );
    }

    _handleDiscoverTimeout() {
        this._stopScan = 1;
        if (this._discoverTimeoutID) {
            clearTimeout(this._discoverTimeoutID);
            this._discoverTimeoutID = null;
        }
        this._runtime.emit(this._runtime.constructor.PERIPHERAL_SCAN_TIMEOUT);
    }
}

module.exports = BLEWEBBLUETOOTH;
