import bindAll from 'lodash.bindall';
import PropTypes from 'prop-types';
import React from 'react';
import {defineMessages, injectIntl, intlShape} from 'react-intl';
import {connect} from 'react-redux';

import log from '../lib/log';
import {
    LoadingState,
    LoadingStates,
    onLoadedProject,
    requestProjectUpload
} from '../reducers/project-state';
import {setProjectTitle} from '../reducers/project-title';
import {openLoadingProject, closeLoadingProject} from '../reducers/modals';

// GitHub /blob/ and /raw/ pages return HTML and lack CORS headers; the raw
// subdomain serves the file bytes with Access-Control-Allow-Origin: *.
const normalizeProjectUrl = function (url) {
    const github = url.match(/^https?:\/\/github\.com\/([^/]+)\/([^/]+)\/(?:blob|raw)\/(.+)$/);
    if (github) {
        const [, owner, repo, rest] = github;
        return `https://raw.githubusercontent.com/${owner}/${repo}/${rest}`;
    }
    return url;
};

// Google Drive and Docs do not send CORS headers for anonymous browser fetches
// on any of their public share endpoints (/file/d/.../view, /drive/folders/...,
// /uc?export=download, drive.usercontent.google.com/download, etc.), so no
// URL rewrite can make this work from the browser. We detect these hosts up
// front and reject with a dedicated message telling the user to download the
// file locally first.
const isUnsupportedGoogleUrl = function (url) {
    return /^https?:\/\/(?:drive|docs)\.google\.com\//.test(url) ||
        /^https?:\/\/drive\.usercontent\.google\.com\//.test(url);
};

const messages = defineMessages({
    fetchError: {
        id: 'gui.urlProjectLoader.fetchError',
        defaultMessage: 'Failed to download the project from that URL.',
        description: 'Shown when fetching the project URL fails (network/CORS/404)'
    },
    loadError: {
        id: 'gui.urlProjectLoader.loadError',
        defaultMessage: 'The downloaded file is not a valid Scratch project.',
        description: 'Shown when the downloaded bytes cannot be loaded by the VM'
    },
    googleDriveUnsupported: {
        id: 'gui.urlProjectLoader.googleDriveUnsupported',
        defaultMessage: 'Google Drive links are not supported due to browser security (CORS) restrictions. Please download the file and use "Load from Computer" instead.',
        description: 'Shown when the user enters a Google Drive or Docs URL'
    }
});

/**
 * Higher Order Component that adds `onLoadFromUrl(url)` to the wrapped component.
 * The handler fetches an .sb3 file, hands the ArrayBuffer to vm.loadProject(), and
 * transitions project-state so the editor treats it like a normal upload (editable/savable).
 * Returns a Promise that resolves on success and rejects with an Error on failure so the
 * caller (modal) can surface the message inline.
 */
const SBUrlUploaderHOC = function (WrappedComponent) {
    class SBUrlUploaderComponent extends React.Component {
        constructor (props) {
            super(props);
            bindAll(this, [
                'handleLoadFromUrl'
            ]);
        }

        getProjectTitleFromUrl (url) {
            try {
                const pathname = new URL(url).pathname;
                const last = pathname.substring(pathname.lastIndexOf('/') + 1);
                const decoded = decodeURIComponent(last);
                const match = decoded.match(/^(.*)\.sb[23]?$/);
                if (match) return match[1].substring(0, 100);
                return decoded.substring(0, 100);
            } catch (e) {
                return '';
            }
        }

        handleLoadFromUrl (url) {
            const {intl, vm, loadingState} = this.props;

            if (isUnsupportedGoogleUrl(url)) {
                return Promise.reject(new Error(intl.formatMessage(messages.googleDriveUnsupported)));
            }

            const fetchUrl = normalizeProjectUrl(url);

            this.props.requestProjectUpload(loadingState);
            this.props.onLoadingStarted();

            // The requestProjectUpload dispatch above transitions state to
            // LOADING_VM_FILE_UPLOAD. We hardcode that here instead of reading
            // this.props.loadingState later, because synchronous CORS failures
            // can resolve before React has re-rendered with the new props.
            const uploadState = LoadingState.LOADING_VM_FILE_UPLOAD;

            return fetch(fetchUrl)
                .then(res => {
                    if (!res.ok) {
                        throw new Error(`${intl.formatMessage(messages.fetchError)} (HTTP ${res.status})`);
                    }
                    return res.arrayBuffer();
                })
                .catch(err => {
                    log.warn('[sb-url-uploader] fetch failed', err);
                    throw new Error(intl.formatMessage(messages.fetchError));
                })
                .then(buffer => vm.loadProject(buffer).catch(err => {
                    log.warn('[sb-url-uploader] vm.loadProject failed', err);
                    throw new Error(intl.formatMessage(messages.loadError));
                }))
                .then(() => {
                    const title = this.getProjectTitleFromUrl(url);
                    if (title) this.props.onSetProjectTitle(title);
                    this.props.onLoadingFinished(uploadState, true);
                })
                .catch(err => {
                    this.props.onLoadingFinished(uploadState, false);
                    throw err;
                });
        }

        render () {
            const {
                /* eslint-disable no-unused-vars */
                loadingState,
                onLoadingFinished,
                onLoadingStarted,
                onSetProjectTitle,
                requestProjectUpload: requestProjectUploadProp,
                /* eslint-enable no-unused-vars */
                ...componentProps
            } = this.props;
            return (
                <WrappedComponent
                    onLoadFromUrl={this.handleLoadFromUrl}
                    {...componentProps}
                />
            );
        }
    }

    SBUrlUploaderComponent.propTypes = {
        canSave: PropTypes.bool,
        intl: intlShape.isRequired,
        loadingState: PropTypes.oneOf(LoadingStates),
        onLoadingFinished: PropTypes.func,
        onLoadingStarted: PropTypes.func,
        onSetProjectTitle: PropTypes.func,
        requestProjectUpload: PropTypes.func,
        vm: PropTypes.shape({
            loadProject: PropTypes.func
        })
    };

    const mapStateToProps = state => ({
        loadingState: state.scratchGui.projectState.loadingState,
        vm: state.scratchGui.vm
    });

    const mapDispatchToProps = (dispatch, ownProps) => ({
        onLoadingStarted: () => dispatch(openLoadingProject()),
        onLoadingFinished: (loadingState, success) => {
            dispatch(onLoadedProject(loadingState, ownProps.canSave, success));
            dispatch(closeLoadingProject());
        },
        onSetProjectTitle: title => dispatch(setProjectTitle(title)),
        requestProjectUpload: loadingState => dispatch(requestProjectUpload(loadingState))
    });

    const mergeProps = (stateProps, dispatchProps, ownProps) =>
        Object.assign({}, stateProps, dispatchProps, ownProps);

    return injectIntl(
        connect(mapStateToProps, mapDispatchToProps, mergeProps)(SBUrlUploaderComponent)
    );
};

export {SBUrlUploaderHOC as default};
